class ReadOnlyTextView:
    """Stable retained-text controller for selectable, read-only Tk Text viewers."""
    def __init__(self,widget,clipboard_owner,initial_text=None):
        self.widget=widget; self.clipboard_owner=clipboard_owner
        if initial_text is None:
            try:initial_text=widget.get("1.0","end-1c")
            except Exception:initial_text=""
        self.text=str(initial_text or "")
        # Keep the Text selection local to the widget instead of exporting it
        # as X11 PRIMARY ownership. Otherwise focus/selection ownership changes
        # can make a valid mouse selection disappear visually on Linux/Tk.
        widget.configure(state="disabled",exportselection=False)
        widget.bind("<Control-a>",self.select_all)
        widget.bind("<Control-A>",self.select_all)
        widget.bind("<Control-c>",self.copy_selection)
        widget.bind("<Control-C>",self.copy_selection)

    def set_text(self,text):
        text=str(text)
        if text==self.text:return False
        self.text=text
        self.widget.configure(state="normal")
        self.widget.delete("1.0","end")
        self.widget.insert("1.0",text)
        self.widget.configure(state="disabled")
        return True

    def get_text(self):
        return self.text

    def select_all(self,event=None):
        try:self.widget.tag_add("sel","1.0","end-1c"); self.widget.mark_set("insert","1.0")
        except Exception:pass
        return "break"

    def copy_selection(self,event=None):
        try:text=self.widget.get("sel.first","sel.last")
        except Exception:return "break"
        if text:self._copy(text)
        return "break"

    def copy_all(self):
        if self.text:self._copy(self.text)
        return self.text

    def _copy(self,text):
        self.clipboard_owner.clipboard_clear(); self.clipboard_owner.clipboard_append(text)
        self.clipboard_owner.update_idletasks()


