class Meter(tk.Canvas):
    def __init__(self, parent, title, unit="", minv=0, maxv=100, **kw):
        super().__init__(parent, height=70, bg=PANEL, highlightthickness=0, **kw)
        self.title, self.unit, self.minv, self.maxv = title, unit, minv, maxv
        self.value = None
        self.display_text = None
        self.bind("<Configure>", lambda e:self.redraw())

    def set(self, value, display_text=None):
        self.value = value
        self.display_text = display_text
        self.redraw()

    def redraw(self):
        self.delete("all")
        w=max(20,self.winfo_width())
        self.create_text(8,8,anchor="nw",fill=MUTED,font=("Sans",9,"bold"),text=self.title)
        if self.display_text is not None:
            txt=self.display_text
        elif self.value is None:
            txt="—"
        elif isinstance(self.value,float):
            txt=f"{self.value:.1f}{self.unit}"
        else:
            txt=f"{self.value}{self.unit}"
        self.create_text(w-8,8,anchor="ne",fill=FG,font=("Sans",11,"bold"),text=txt)
        x1,y1,x2,y2=8,40,w-8,54
        self.create_rectangle(x1,y1,x2,y2,fill="#05070a",outline=BORDER)
        if self.value is not None and self.maxv > self.minv:
            frac=max(0,min(1,(float(self.value)-self.minv)/(self.maxv-self.minv)))
            self.create_rectangle(x1,y1,x1+(x2-x1)*frac,y2,fill=BLUE,outline="")

class HistoryGraph(tk.Canvas):
    def __init__(self,parent,**kw):
        height=kw.pop("height",175)
        super().__init__(parent,bg=PANEL,highlightthickness=0,height=height,**kw)
        self.series={"GPU %":[],"Junction °C":[],"Power W":[]}
        self.colors={"GPU %":BLUE,"Junction °C":YELLOW,"Power W":GREEN}
        self.bind("<Configure>",lambda e:self.redraw())

    def add(self,busy,temp,power):
        vals={"GPU %":busy,"Junction °C":temp,"Power W":power}
        for k,v in vals.items():
            self.series[k].append(v)
            if len(self.series[k])>120:self.series[k]=self.series[k][-120:]
        self.redraw()

    def redraw(self):
        self.delete("all")
        w,h=max(20,self.winfo_width()),max(20,self.winfo_height())
        self.create_text(10,8,anchor="nw",fill=FG,font=("Sans",10,"bold"),text="GPU history")
        for i,(k,c) in enumerate(self.colors.items()):
            self.create_text(95+i*125,8,anchor="nw",fill=c,font=("Sans",9,"bold"),text=k)
        x0,y0,x1,y1=10,34,w-10,h-12
        self.create_rectangle(x0,y0,x1,y1,outline=BORDER,fill="#070a0f")
        for gy in range(1,4):
            y=y0+(y1-y0)*gy/4
            self.create_line(x0,y,x1,y,fill="#182331")
        maxes={"GPU %":100.0,"Junction °C":120.0,"Power W":500.0}
        for k,arr in self.series.items():
            pts=[]; n=max(2,len(arr))
            for i,v in enumerate(arr):
                if v is None:continue
                xx=x0+(x1-x0)*(i/max(1,n-1))
                yy=y1-(y1-y0)*max(0,min(1,float(v)/maxes[k]))
                pts += [xx,yy]
            if len(pts)>=4:self.create_line(*pts,fill=self.colors[k],width=2,smooth=True)

class GamingPerformanceGraph(tk.Canvas):
    """Compact sampled-FPS history. Uses only telemetry values already supplied by MangoHud."""
    def __init__(self,parent,**kw):
        height=kw.pop("height",105)
        super().__init__(parent,bg="#070a0f",highlightthickness=1,highlightbackground=BORDER,height=height,**kw)
        self.samples=[]
        self.p1=None
        self.avg=None
        self.bind("<Configure>",lambda e:self.redraw())

    def set_data(self,samples,p1=None,avg=None):
        self.samples=list(samples or [])[-240:]
        self.p1=p1
        self.avg=avg
        self.redraw()

    def redraw(self):
        self.delete("all")
        w,h=max(40,self.winfo_width()),max(40,self.winfo_height())
        self.create_text(9,7,anchor="nw",fill=FG,font=("Sans",9,"bold"),text="Gaming performance • recent sampled FPS")
        if self.avg is not None:
            self.create_text(w-9,7,anchor="ne",fill=FG,font=("Sans",9,"bold"),text=f"Avg {self.avg:.0f} FPS")
        x0,y0,x1,y1=9,27,w-9,h-10
        self.create_rectangle(x0,y0,x1,y1,outline=BORDER,fill="#05070a")

        vals=[float(v) for v in self.samples if v is not None and float(v)>0]
        if not vals:
            self.create_text((x0+x1)/2,(y0+y1)/2,fill=MUTED,font=("Sans",9),text="Waiting for live FPS samples")
            return

        ymax=max(60.0,max(vals)*1.12)
        # Round up to a calm readable scale.
        ymax=math.ceil(ymax/30.0)*30.0
        for gy in range(1,3):
            y=y0+(y1-y0)*gy/3
            self.create_line(x0,y,x1,y,fill="#182331")

        pts=[]
        n=max(2,len(self.samples))
        for i,v in enumerate(self.samples):
            try:v=float(v)
            except Exception:continue
            xx=x0+(x1-x0)*(i/max(1,n-1))
            yy=y1-(y1-y0)*max(0,min(1,v/ymax))
            pts += [xx,yy]
        if len(pts)>=4:
            self.create_line(*pts,fill=BLUE,width=2,smooth=True)

        if self.p1 is not None:
            py=y1-(y1-y0)*max(0,min(1,float(self.p1)/ymax))
            self.create_line(x0,py,x1,py,fill=YELLOW,width=1,dash=(4,3))
            self.create_text(x1-5,py-2,anchor="se",fill=YELLOW,font=("Sans",8,"bold"),text=f"P1 {self.p1:.0f}")

class SessionTrendGraph(tk.Canvas):
    """Small responsive chronological graph with shared-unit series and point selection."""
    def __init__(self,parent,title,unit,series,on_select=None,display_range=None,**kw):
        height=kw.pop("height",190)
        super().__init__(parent,bg="#070a0f",highlightthickness=1,highlightbackground=BORDER,height=height,**kw)
        self.title,self.unit,self.series,self.on_select,self.display_range=title,unit,series,on_select,display_range
        self.points=[]; self.point_xy=[]; self.session_x=[]; self.selected_history_index=None
        self.bind("<Configure>",lambda e:self.redraw()); self.bind("<Motion>",self._hover); self.bind("<Leave>",lambda e:self.delete("trend_tip")); self.bind("<Button-1>",self._click)

    def set_data(self,points,selected_history_index=None):
        self.points=list(points or []); self.selected_history_index=selected_history_index; self.redraw()

    def redraw(self):
        self.delete("all"); self.point_xy=[]; self.session_x=[]
        w,h=max(100,self.winfo_width()),max(80,self.winfo_height())
        header=self.header_layout(w,self.title,self.series)
        self.create_text(header["title_x"],header["title_y"],anchor="nw",fill=FG,font=("Sans",10,"bold"),text=self.title)
        for (_,label,color),(x,y) in zip(self.series,header["legend_positions"]):self.create_text(x,y,anchor="nw",fill=color,font=("Sans",8,"bold"),text=label)
        x0,y0,x1,y1=46,header["plot_top"],w-12,h-30; self.create_rectangle(x0,y0,x1,y1,outline=BORDER,fill="#05070a")
        n=max(2,len(self.points))
        for i,p in enumerate(self.points):
            x=x0+(x1-x0)*i/max(1,n-1); self.session_x.append((x,p))
            if p.get("history_index")==self.selected_history_index:
                self.create_line(x,y0,x,y1,fill="#ffffff",width=2,dash=(4,3))
        values=[float(p.get(key)) for p in self.points for key,_,_ in self.series if p.get(key) is not None]
        if not values:
            self.create_text((x0+x1)/2,(y0+y1)/2,fill=MUTED,text="No compatible metrics available")
            self._draw_x_labels(x0,x1,y1,w); return
        ymin,ymax=self.scale_bounds(values,self.display_range)
        if ymax<=ymin:ymax=ymin+1
        for gy in range(4):
            frac=gy/3; y=y1-(y1-y0)*frac; val=ymin+(ymax-ymin)*frac
            self.create_line(x0,y,x1,y,fill="#182331"); self.create_text(x0-5,y,anchor="e",fill=MUTED,font=("Sans",7),text=f"{val:.0f}")
        for key,label,color in self.series:
            segment=[]
            for i,p in enumerate(self.points):
                value=p.get(key); x=x0+(x1-x0)*i/max(1,n-1)
                if value is None:
                    if len(segment)>=4:self.create_line(*segment,fill=color,width=2)
                    segment=[]; continue
                y=y1-(y1-y0)*(float(value)-ymin)/(ymax-ymin); segment += [x,y]
                self.point_xy.append((x,y,p,key)); selected=p.get("history_index")==self.selected_history_index
                radius=6 if selected else 4; self.create_oval(x-radius,y-radius,x+radius,y+radius,fill=color,outline="#ffffff" if selected else "",width=2 if selected else 0)
            if len(segment)>=4:self.create_line(*segment,fill=color,width=2)
        self._draw_x_labels(x0,x1,y1,w)

    @staticmethod
    def header_layout(width,title,series):
        count=max(1,len(series)); usable=max(120,int(width)-20); cell=usable/count
        return {"title_x":10,"title_y":6,"title_bottom":22,"legend_positions":[(10+i*cell,24) for i in range(count)],"legend_top":24,"legend_cell_width":cell,"plot_top":43}

    @staticmethod
    def scale_bounds(values,display_range=None):
        values=[float(v) for v in values]
        if display_range:
            low,high=map(float,display_range); maximum=max(values) if values else high
            if maximum>high:high=math.ceil(maximum*1.03/10.0)*10.0
            return low,high
        low=min(0.0,min(values)*.9); high=max(values)*1.1
        return (low,high if high>low else low+1)

    @staticmethod
    def _time_label(timestamp,mode):
        tm=time.localtime(timestamp); hour=tm.tm_hour%12 or 12; ampm="AM" if tm.tm_hour<12 else "PM"
        if mode=="time":return f"{hour}:{tm.tm_min:02d} {ampm}"
        if mode=="date_time":return f"{tm.tm_mon}/{tm.tm_mday} {hour}:{tm.tm_min:02d} {ampm}"
        return f"{tm.tm_mon}/{tm.tm_mday}"

    @classmethod
    def axis_labels(cls,points,width):
        points=list(points or [])
        if not points:return []
        timestamps=[float(p.get("timestamp") or 0) for p in points]
        same_day=time.strftime("%Y-%m-%d",time.localtime(min(timestamps)))==time.strftime("%Y-%m-%d",time.localtime(max(timestamps)))
        span=max(timestamps)-min(timestamps); mode="time" if same_day else ("date_time" if span<=7*86400 else "date")
        samples=[cls._time_label(t,mode) for t in timestamps]; spacing=max(58,max(len(label) for label in samples)*7+14)
        count=max(2,min(len(points),max(2,(max(100,int(width))-58)//spacing)))
        indexes=sorted({round(i*(len(points)-1)/max(1,count-1)) for i in range(count)})
        return [(i,samples[i]) for i in indexes]

    def _draw_x_labels(self,x0,x1,y1,width):
        n=max(2,len(self.points))
        for i,label in self.axis_labels(self.points,width):
            x=x0+(x1-x0)*i/max(1,n-1); self.create_line(x,y1,x,y1+3,fill=BORDER)
            anchor="nw" if i==0 else "ne" if i==len(self.points)-1 else "n"
            self.create_text(x,y1+5,anchor=anchor,fill=MUTED,font=("Sans",7),text=label)

    def _nearest_coordinates(self,x,y):
        by_session={}
        for px,py,p,_ in self.point_xy:
            distance=math.hypot(px-x,py-y); index=p.get("history_index")
            if index not in by_session or distance<by_session[index][0]:by_session[index]=(distance,p)
        matches=sorted(by_session.values(),key=lambda item:(item[0],item[1].get("timestamp",0),item[1].get("history_index",0)))
        if matches and matches[0][0]<=26:return matches[0]
        columns=sorted(((abs(px-x),p) for px,p in self.session_x),key=lambda item:(item[0],item[1].get("timestamp",0),item[1].get("history_index",0)))
        return columns[0] if columns and columns[0][0]<=18 else (matches[0] if matches else (999,None))

    def _nearest(self,event):return self._nearest_coordinates(event.x,event.y)

    def _hover(self,event):
        distance,point=self._nearest(event); self.delete("trend_tip")
        if point is None or distance>24:return
        text=point.get("tooltip",""); x=min(max(event.x+10,10),max(10,self.winfo_width()-330)); y=max(30,event.y-35)
        self.create_rectangle(x,y,x+320,y+32,fill=PANEL2,outline=BORDER,tags="trend_tip")
        self.create_text(x+5,y+4,anchor="nw",fill=FG,font=("Sans",8),width=310,text=text,tags="trend_tip")

    def _click(self,event):
        distance,point=self._nearest(event)
        if point is not None and distance<=26 and self.on_select:
            self.focus_set(); self.on_select(point.get("history_index"))

class App(LiveIntelligenceMixin, RuntimeDetectionMixin, AnalysisLabEngineMixin, RecommendationEngineMixin, OptimizationEngineMixin, tk.Tk):
    def __init__(self):
        super().__init__(className="AMD-Linux-Control-Center")
        self.title(f"{APP_NAME} {VERSION}")
        self.geometry("1330x940")
        self.minsize(980,680)
        self.configure(bg=BG)
        self.gpus=AMDGPU.discover()
        self.gpu=self._preferred_gpu()
        self.curve_proc=None
        self.curve_stop_file=None
        self.profile_data=load_profiles_file()
        self.active_profile_name=None
        self.game_profile_data=load_game_profiles_file()
        self.game_session_history=load_game_session_history_file()
        self.optimization_trials=load_optimization_trials_file()
        self.game_session_current=None
        self.game_session_sort_key="ended_iso"
        self.game_session_sort_reverse=True
        self.game_session_filter_game=None
        self.game_session_filter_quality=None
        self.game_session_same_setup_var=None
        self.game_session_missing_since=None
        self.game_session_exit_grace_seconds=10.0
        self.telemetry_runtime_status={"state":"Telemetry stopped","reason":"No detected game yet","game_id":None}
        self.telemetry_onboarding_results={}
        self.telemetry_onboarding_retry_job=None
        self.live_intelligence=self._new_live_intelligence_state()
        self.live_analysis_context=None
        self.game_monitor_armed=True

        self.game_active_rule=None
        self.game_previous_profile=None
        self.game_previous_snapshot=None
        self.game_monitor_job=None
        self.game_apply_busy=False
        # Never allow a saved automatic game rule to invoke pkexec merely because
        # the GUI started. Automatic privileged writes must be explicitly armed
        # by the user for the current application session.
        self.game_monitor_armed=False
        self.game_launch_pending=None
        self.game_monitor_last_event="Waiting for game activity"
        self.game_monitor_last_match=""
        self.game_exit_missing_since=None
        self.game_exit_grace_seconds=10.0
        self.app_settings=load_app_settings()
        self.tray_icon=None
        self.tray_available=(pystray is not None and Image is not None)
        self.really_quit=False
        self._shutdown_session_finalized=False
        self._style()
        self._header()
        self.nb=ttk.Notebook(self); self.nb.pack(fill="both",expand=True,padx=14,pady=(8,12))
        self._app_focus_outside=False
        self._display_focus_refresh_job=None
        self.bind("<FocusOut>",self._app_focus_out_event,add="+")
        self.bind("<FocusIn>",self._app_focus_in_event,add="+")
        self.nb.bind("<<NotebookTabChanged>>",self._main_tab_changed,add="+")
        # Runtime process discovery can briefly touch many /proc entries.  Defer
        # that scan while the user is actively scrolling, dragging a scrollbar,
        # or changing workspaces so Tk's main event loop stays responsive.
        self._ui_interaction_active_until=0.0
        # Full same-user /proc scans are performed by a daemon worker in the real
        # GUI.  Pure backend/self-test harnesses retain synchronous semantics.
        self._runtime_nonblocking_enabled=True
        for _sequence in ("<MouseWheel>","<Button-4>","<Button-5>","<B1-Motion>"):
            self.bind_all(_sequence,self._note_ui_interaction,add="+")
        # Organize the mature feature set into a small number of top-level
        # workspaces.  Keep self.tabs mappings for existing builders so this is
        # a navigation/layout change rather than a behavioral rewrite.
        self.tabs={}
        dashboard=ttk.Frame(self.nb); self.nb.add(dashboard,text="Dashboard"); self.tabs["Dashboard"]=dashboard

        gpu_workspace=ttk.Frame(self.nb); self.nb.add(gpu_workspace,text="GPU")
        self.gpu_nb=ttk.Notebook(gpu_workspace); self.gpu_nb.pack(fill="both",expand=True,padx=10,pady=10)
        for name,label in (("GPU Capabilities","Capabilities"),("Performance","Performance"),("Advanced Performance","Advanced"),("Fan Control","Fan Control"),("Profiles","Profiles")):
            f=ttk.Frame(self.gpu_nb); self.gpu_nb.add(f,text=label); self.tabs[name]=f
        self.gpu_nb.bind("<<NotebookTabChanged>>",self._workspace_subtab_changed,add="+")

        gaming=ttk.Frame(self.nb); self.nb.add(gaming,text="Games"); self.tabs["Gaming"]=gaming
        analysis=ttk.Frame(self.nb); self.nb.add(analysis,text="Analysis"); self.tabs["Analysis"]=analysis
        optimization=ttk.Frame(self.nb); self.nb.add(optimization,text="Optimization"); self.tabs["Optimization"]=optimization
        display=ttk.Frame(self.nb); self.nb.add(display,text="Display"); self.tabs["Display"]=display

        system_workspace=ttk.Frame(self.nb); self.nb.add(system_workspace,text="System")
        self.system_nb=ttk.Notebook(system_workspace); self.system_nb.pack(fill="both",expand=True,padx=10,pady=10)
        for name,label in (("Background","Background"),("System","System Info"),("Recovery","Recovery")):
            f=ttk.Frame(self.system_nb); self.system_nb.add(f,text=label); self.tabs[name]=f

        about=ttk.Frame(self.nb); self.nb.add(about,text="About"); self.tabs["About"]=about
        self._build_dashboard(); self._build_gpu_capabilities(); self._build_performance(); self._build_advanced_performance(); self._build_fan(); self._build_profiles(); self._build_game_profiles(); self._build_display(); self._build_background(); self._build_system(); self._build_recovery(); self._build_about()
        self.populate_gpu_selector()
        self.populate_static()
        self.after(300,self._sync_dpm_ui_from_driver)
        self.after(1100,self._sync_dpm_ui_from_driver)
        self.protocol("WM_DELETE_WINDOW", self.on_window_close)
        self.after(1600,self._apply_startup_profile_if_configured)
        # Restore a previously active custom curve only after startup profile work
        # has had a chance to settle.  Silent restore is limited to sessions where
        # the narrowly scoped helper is already authorized without a prompt.
        self.after(2300,self._restore_saved_fan_curve_if_requested)
        self.after(700,self._start_tray_if_available)
        if self.app_settings.get("start_minimized",False):
            self.after(900,self.hide_to_tray)
        self.after(250,self.refresh)
        # Keep live-game status separate from the critical GPU sensor/history loop.
        # A parsing/provider error must never freeze temperatures, meters or history.
        self.after(550,self._refresh_live_game_dashboard_loop)
        self.after(1200,self._game_monitor_tick)

    def _preferred_gpu(self):
        if not self.gpus:return None
        # Discrete cards normally expose substantially more VRAM; choose largest VRAM by default.
        return max(self.gpus,key=lambda g:g.vram_total())

