    def _header(self):
        h=ttk.Frame(self); h.pack(fill="x",padx=16,pady=(14,0))
        left=ttk.Frame(h); left.pack(side="left",fill="x",expand=True)
        ttk.Label(left,text=f"{APP_NAME}  {VERSION}",style="Title.TLabel").pack(anchor="w")
        ttk.Label(left,text="Radeon monitoring and safe driver-aware control for Linux",style="Sub.TLabel").pack(anchor="w")
        right=ttk.Frame(h); right.pack(side="right")
        ttk.Label(right,text="GPU:",style="Sub.TLabel").pack(side="left",padx=(0,5))
        self.gpu_combo=ttk.Combobox(right,state="readonly",width=46)
        self.gpu_combo.pack(side="left",padx=(0,12))
        self.gpu_combo.bind("<<ComboboxSelected>>",self.on_gpu_change)
        self.status=ttk.Label(right,text="Detecting…",foreground=YELLOW); self.status.pack(side="left")

    def _panel(self,parent,title):
        outer=tk.Frame(parent,bg=PANEL,highlightbackground=BORDER,highlightthickness=1)
        tk.Label(outer,text=title,bg=PANEL,fg=FG,font=("Sans",11,"bold")).pack(anchor="w",padx=12,pady=(10,5))
        body=tk.Frame(outer,bg=PANEL); body.pack(fill="both",expand=True,padx=10,pady=(0,10))
        return outer,body

    def _build_gpu_capabilities(self):
        t=self.tabs["GPU Capabilities"]
        outer=tk.Frame(t,bg=BG); outer.pack(fill="both",expand=True,padx=16,pady=14)

        tk.Label(
            outer,text="GPU Capability Detection",bg=BG,fg=FG,
            font=("Sans",18,"bold"),anchor="w"
        ).pack(fill="x")
        tk.Label(
            outer,
            text="Read-only probe of the AMDGPU sysfs/hwmon interfaces actually exposed by this GPU and kernel. "
                 "This page does not change clocks, voltage, power limits, fan settings, or performance modes.",
            bg=BG,fg=MUTED,font=("Sans",10),anchor="w",justify="left",wraplength=1050
        ).pack(fill="x",pady=(4,12))

        top=tk.Frame(outer,bg=PANEL); top.pack(fill="x",pady=(0,10))
        tk.Label(top,text="Selected GPU",bg=PANEL,fg=FG).pack(side="left",padx=(12,8),pady=10)
        self.cap_gpu_label=tk.Label(top,text="—",bg=PANEL,fg=BLUE2,anchor="w")
        self.cap_gpu_label.pack(side="left",fill="x",expand=True,pady=10)
        ttk.Button(top,text="Copy Results",command=self.copy_gpu_capabilities).pack(side="right",padx=(0,6),pady=7)
        ttk.Button(top,text="Scan Capabilities",command=self.refresh_gpu_capabilities).pack(side="right",padx=10,pady=7)

        body=tk.Frame(outer,bg=PANEL); body.pack(fill="both",expand=True)
