        steam_canvas=tk.Canvas(steam_page,bg=BG,highlightthickness=0)
        self._game_library_scroll_active_until=0.0
        def _steam_scrollbar(*args):
            self._game_library_scroll_active_until=time.monotonic()+0.8
            steam_canvas.yview(*args)
        steam_scroll=ttk.Scrollbar(steam_page,orient="vertical",command=_steam_scrollbar)
        steam_canvas.configure(yscrollcommand=steam_scroll.set)
        steam_scroll.pack(side="right",fill="y")
        steam_canvas.pack(side="left",fill="both",expand=True)

        steam_inner=tk.Frame(steam_canvas,bg=BG)
        steam_window=steam_canvas.create_window((0,0),window=steam_inner,anchor="nw")

        def _steam_scroll_region(event=None):
            steam_canvas.configure(scrollregion=steam_canvas.bbox("all"))
        def _steam_canvas_width(event):
            steam_canvas.itemconfigure(steam_window,width=event.width)
        def _steam_mousewheel(event):
            self._game_library_scroll_active_until=time.monotonic()+0.8
            # X11 commonly sends Button-4/5; other Tk builds use MouseWheel.
            if getattr(event,"num",None)==4:
                steam_canvas.yview_scroll(-3,"units")
            elif getattr(event,"num",None)==5:
                steam_canvas.yview_scroll(3,"units")
            elif getattr(event,"delta",0):
                steam_canvas.yview_scroll(int(-event.delta/120)*3,"units")

        steam_inner.bind("<Configure>",_steam_scroll_region)
        steam_canvas.bind("<Configure>",_steam_canvas_width)
        for widget in (steam_canvas,steam_inner):
            widget.bind("<MouseWheel>",_steam_mousewheel)
            widget.bind("<Button-4>",_steam_mousewheel)
            widget.bind("<Button-5>",_steam_mousewheel)

        def _steam_bind_wheel_all(event=None):
            steam_canvas.bind_all("<MouseWheel>",_steam_mousewheel)
            steam_canvas.bind_all("<Button-4>",_steam_mousewheel)
            steam_canvas.bind_all("<Button-5>",_steam_mousewheel)

        def _steam_unbind_wheel_all(event=None):
            steam_canvas.unbind_all("<MouseWheel>")
            steam_canvas.unbind_all("<Button-4>")
            steam_canvas.unbind_all("<Button-5>")

        steam_canvas.bind("<Enter>",_steam_bind_wheel_all)
        steam_inner.bind("<Enter>",_steam_bind_wheel_all)
        steam_canvas.bind("<Leave>",_steam_unbind_wheel_all)

