    def _steam_process_running(self):
        return steam_process_running()

    def _steam_localconfig_candidates(self):
        return steam_localconfig_candidates(self._steam_root_candidates())

    def _steam_localconfig_for_selected_game(self):
        # Steam does not encode the active account in appmanifest files. Use the
        # most recently modified localconfig.vdf, which is normally the account
        # currently/most-recently used on this desktop, and display it in the UI.
        cands=self._steam_localconfig_candidates()
        return cands[0] if cands else None

    def _vdf_unescape(self, value):
        return steam_vdf_unescape(value)

    def _vdf_escape(self, value):
        return steam_vdf_escape(value)

    def _vdf_tokenize(self, text):
        return steam_vdf_tokenize(text)

    def _vdf_nodes(self, text):
        return steam_vdf_nodes(text)

    def _vdf_find_node(self, text, path):
        return steam_vdf_find_node(text,path)

    def _steam_app_path(self, appid):
        return steam_app_path_for_id(appid)

    def _read_launch_options_from_localconfig(self, path, appid):
        return steam_read_launch_options_from_localconfig(path,appid)

    def _patch_steam_launch_options_text(self, text, appid, launch_options):
        return steam_patch_launch_options_text(text,appid,launch_options)

    def _validate_steam_localconfig_text(self,text):
        return steam_validate_localconfig_text(text)

    @staticmethod
    def _atomic_replace_text(path,text):
        """Preserve file metadata, flush the replacement, then atomically rename it."""
        path=str(path); tmp=path+".amd-control-center.tmp"
        shutil.copy2(path,tmp)
        try:
            with open(tmp,"w",encoding="utf-8",newline="") as handle:
                handle.write(text); handle.flush(); os.fsync(handle.fileno())
            os.replace(tmp,path)
        finally:
            try:
                if os.path.exists(tmp):os.unlink(tmp)
            except OSError:pass

    def _steam_backup_dir(self):
        p=os.path.join(CONFIG_DIR,"steam_backups")
        os.makedirs(p,exist_ok=True)
        return p

    def _steam_backup_localconfig(self, cfg, appid):
        stamp=time.strftime("%Y%m%d-%H%M%S")
        name=f"localconfig-user{cfg['uid']}-appid{appid}-{stamp}.vdf.bak"
        dest=os.path.join(self._steam_backup_dir(),name)
        shutil.copy2(cfg["path"],dest)
        latest=self.game_profile_data.setdefault("steam_backup_latest",{})
        latest[str(appid)]=dest
        save_game_profiles_file(self.game_profile_data)
        return dest

    def _set_readonly_entry(self, entry, value):
        entry.configure(state="normal")
        entry.delete(0,"end")
        entry.insert(0,value or "")
        entry.configure(state="readonly")

    def _normalize_launch_options(self, value):
        return steam_normalize_launch_options(value)

    def _generated_launch_options_for_selected_steam_game(self):
        g=self._selected_steam_game()
        if not g:
            return ""
        hit=self._rule_for_steam_appid(g["appid"])
        if not hit:
            return ""
        _,rule=hit
        gfx=rule.get("graphics_preset","").strip()
        if not gfx:
            return ""
        return self._launch_options_for_graphics_preset(gfx) or ""

    def _steam_launch_sync_state(self, current, generated):
        current=self._normalize_launch_options(current)
        generated=self._normalize_launch_options(generated)
        if not generated:
            return ("NO PRESET","No generated launch options are linked to this game.",MUTED)
        if not current:
            return ("NOT SET","Steam has no launch options for this game yet.",YELLOW)
        if current==generated:
            return ("APPLIED","Steam matches the associated graphics preset.",GREEN)
        return ("DIFFERENT","Steam launch options differ from the associated graphics preset.",YELLOW)

    def refresh_selected_steam_launch_state(self):
        if not hasattr(self,"steam_current_launch"):
            return
        g=self._selected_steam_game()
        if not g:
            self._set_readonly_entry(self.steam_current_launch,"")
            self.steam_sync_label.configure(text="Launch options status: —",fg=MUTED)
            self.steam_config_label.configure(text="")
            if hasattr(self,"steam_launch_game_btn"):
                self.steam_launch_game_btn.configure(state="disabled")
            if hasattr(self,"steam_smart_launch_btn"):
                self.steam_smart_launch_btn.configure(state="disabled")
            if hasattr(self,"steam_diag_text"):
                self.refresh_selected_game_diagnostics()
            return

        cfg=self._steam_localconfig_for_selected_game()
        if not cfg:
            self._set_readonly_entry(self.steam_current_launch,"")
            self.steam_sync_label.configure(
                text="Launch options status: UNKNOWN  •  Steam localconfig.vdf was not found.",
                fg=YELLOW
            )
            self.steam_config_label.configure(
                text="No Steam userdata/*/config/localconfig.vdf was detected.",fg=YELLOW
            )
            self.steam_write_btn.configure(state="disabled")
            self.steam_close_apply_btn.configure(state="disabled")
            self.steam_restore_btn.configure(state="disabled")
            self.steam_restart_btn.configure(state="normal" if not self._steam_process_running() else "disabled")
            if hasattr(self,"steam_launch_game_btn"):
                self.steam_launch_game_btn.configure(state="normal")
            if hasattr(self,"steam_smart_launch_btn"):
                self.steam_smart_launch_btn.configure(state="normal")
            return

        current=self._read_launch_options_from_localconfig(cfg["path"],g["appid"])
        self._set_readonly_entry(self.steam_current_launch,current)

        generated=self._generated_launch_options_for_selected_steam_game()
        state,detail,color=self._steam_launch_sync_state(current,generated)
        last=self.game_profile_data.get("steam_last_verified_apply",{}) or {}
        if (str(last.get("appid",''))==str(g.get("appid",'')) and last.get("launch_options")
                and current!=str(last.get("launch_options"))):
            state="CHANGED AFTER APPLY"
            detail="Steam's current LaunchOptions differ from ALCC's last verified write. See steam-apply-audit.log."
            color=YELLOW
        self.steam_sync_label.configure(
            text=f"Launch options status: {state}  •  {detail}",
            fg=color
        )

        running=self._steam_process_running()
        backup=self.game_profile_data.get("steam_backup_latest",{}).get(str(g["appid"]),"")
        self.steam_config_label.configure(
            text=f"Steam user {cfg['uid']}  •  {'Steam is running — writes disabled' if running else 'Steam closed — safe to write'}\n"
                 f"{cfg['path']}",
            fg=YELLOW if running else MUTED
        )
        can_apply=bool(generated)
        self.steam_write_btn.configure(
            state="disabled" if (running or not can_apply) else "normal",
            text="Write Launch Options to Steam" if state!="APPLIED" else "Launch Options Already Applied"
        )
        self.steam_close_apply_btn.configure(
            state="normal" if can_apply else "disabled",
            text="Close Steam & Apply" if state!="APPLIED" else "Close Steam & Reapply"
        )
        self.steam_restore_btn.configure(
            state="normal" if (backup and os.path.isfile(backup) and not running) else "disabled"
        )
        self.steam_restart_btn.configure(state="disabled" if running else "normal")
        if hasattr(self,"steam_launch_game_btn"):
            self.steam_launch_game_btn.configure(state="normal")
        if hasattr(self,"steam_smart_launch_btn"):
            self.steam_smart_launch_btn.configure(
                state="normal",
                text="Smart Launch — Ready" if state=="APPLIED" else f"Smart Launch — {state.title()}"
            )
        if hasattr(self,"steam_bulk_status"):
            self.after_idle(self.refresh_steam_bulk_status)
        if hasattr(self,"steam_diag_text"):
            self.after_idle(self.refresh_selected_game_diagnostics)

    def _steam_running_pids(self):
        pids=[]
        names={"steam","steamwebhelper","steam-runtime-supervisor"}
        try:
            for d in os.scandir("/proc"):
                if not d.name.isdigit():
                    continue
                try:
                    comm=pathlib.Path(d.path,"comm").read_text(errors="ignore").strip().lower()
                    if comm in names:
                        pids.append(int(d.name))
                except Exception:
                    pass
        except Exception:
            pass
        return sorted(set(pids))

    def _steam_client_pids(self):
        # Always rescan /proc. Only the real same-user Steam client counts as a
        # configuration writer. Runtime helpers/webhelpers are deliberately
        # excluded because they can outlive the client briefly after shutdown.
        return steam_client_pids()

    def _steam_config_writer_running(self):
        """Return True only while the real same-user Steam client still exists."""
        return bool(self._steam_client_pids())

    def _request_steam_shutdown(self):
        """Ask Steam to exit, then SIGTERM a lingering same-user Steam client."""
        self._steam_shutdown_lingering_pids=[]
        if not self._steam_process_running():
            return True

        # First use Steam's own shutdown command. This is the preferred path on
        # mutable distributions and also works on many Bazzite sessions.
        steam_bin=shutil.which("steam")
        if steam_bin:
            try:
                subprocess.Popen(
                    [steam_bin,"-shutdown"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    start_new_session=True
                )
            except Exception:
                pass

        graceful_deadline=time.time()+5.0
        while time.time()<graceful_deadline:
            if not self._steam_process_running():
                return True
            self.update_idletasks()
            time.sleep(0.25)

        # Bazzite can close the visible Steam UI yet leave the actual `steam`
        # process alive. Because this path is reached only after the user chose a
        # Close Steam / Setup & Apply action, terminate only same-user processes
        # whose /proc comm is exactly `steam`. Never signal webhelpers, Pressure
        # Vessel, runtime services, other users, or unrelated processes.
        for pid in self._steam_client_pids():
            try:
                os.kill(pid,signal.SIGTERM)
            except (ProcessLookupError,PermissionError,OSError):
                pass

        deadline=time.time()+15.0
        while time.time()<deadline:
            # Rescan /proc on every pass and key shutdown completion to the real
            # same-user Steam client, not webhelpers/runtime processes that can
            # linger after the client has exited. This also avoids stale PID
            # decisions and naturally handles PID disappearance/reuse.
            lingering=self._steam_client_pids()
            if not lingering:
                self._steam_shutdown_lingering_pids=[]
                return True
            self.update_idletasks()
            time.sleep(0.25)

        # One final fresh identity scan at the deadline before reporting failure.
        self._steam_shutdown_lingering_pids=self._steam_client_pids()
        return not bool(self._steam_shutdown_lingering_pids)

    def _fresh_launch_options_for_steam_game(self, g=None):
        """Generate launch options from the saved per-game preset, never the UI preview.

        Steam writes are transactional configuration operations.  The preview entry is
        presentation-only and may be stale after Quick Setup refreshes/rebuilds the
        Steam list, so it must never be authoritative for a write.
        """
        g=g or self._selected_steam_game()
        if not g:
            return None, None
        hit=self._rule_for_steam_appid(g.get("appid"))
        if not hit:
            return None, None
        _,rule=hit
        preset_name=str(rule.get("graphics_preset") or "").strip()
        if not preset_name:
            return None, None
        launch=self._launch_options_for_graphics_preset(preset_name)
        return (str(launch or "").strip() or None), preset_name

    @staticmethod
    def _validate_quick_setup_launch_command(template, settings, launch):
        """Fail closed when a normal template accidentally leaks diagnostics/HUD state."""
        launch=str(launch or "")
        if not launch:
            raise RuntimeError("generated launch options are empty")
        if str(template or "") != "Diagnostics":
            forbidden=("PROTON_LOG=1", "DXVK_HUD=", "MANGOHUD_CONFIG=full", "--mangoapp")
            leaked=[token for token in forbidden if token in launch]
            if leaked:
                raise RuntimeError("normal game template leaked diagnostic/visible HUD option(s): "+", ".join(leaked))
        selected=str((settings or {}).get("display") or "Automatic")
        if selected!="Automatic":
            compositor_helper="alcc_kwin_gamescope.py" in launch and "--output" in launch
            indexed="--display-index" in launch
            if not (compositor_helper or indexed):
                raise RuntimeError("preferred display is saved but generated command has no placement method")
            # SDL is expected when the KDE/Wayland compositor helper owns placement.
            if "--backend sdl" in launch and not compositor_helper:
                raise RuntimeError("preferred display generated the cursor-placed SDL Gamescope path")
        return True

    def _steam_apply_audit(self, stage, *, g=None, cfg=None, launch=None, current=None, readback=None, detail=""):
        """Append a compact transaction trace for Steam launch-option applies."""
        try:
            os.makedirs(CONFIG_DIR,exist_ok=True)
            path=os.path.join(CONFIG_DIR,"steam-apply-audit.log")
            appid=str((g or {}).get("appid","") or "")
            name=str((g or {}).get("name","") or "")
            cfg_path=str((cfg or {}).get("path","") or "")
            def one(v): return str(v or "").replace("\n","\\n")
            with open(path,"a",encoding="utf-8") as h:
                h.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {stage} appid={appid} name={name!r} cfg={cfg_path!r} detail={one(detail)!r}\n")
                if launch is not None: h.write(f"  intended={one(launch)}\n")
                if current is not None: h.write(f"  before={one(current)}\n")
                if readback is not None: h.write(f"  readback={one(readback)}\n")
            return path
        except Exception:
            return ""

    def _remember_verified_steam_apply(self, g, cfg, launch, audit_path=""):
        rec={
            "appid":str(g.get("appid","") or ""),
            "name":str(g.get("name","") or ""),
            "path":str(cfg.get("path","") or ""),
            "launch_options":str(launch or ""),
            "verified_at":time.time(),
            "audit_path":audit_path or os.path.join(CONFIG_DIR,"steam-apply-audit.log"),
        }
        self.game_profile_data["steam_last_verified_apply"]=rec
        save_game_profiles_file(self.game_profile_data)
        return rec

    def _perform_selected_steam_launch_write(self, interactive=True, g=None, launch=None, preset_name=None, cfg=None):
        # A Setup & Apply transaction may refresh/rebuild the Steam game list.
        # When the caller supplies g/launch/cfg, those locked values are the
        # authority for the entire write; never re-read the mutable UI selection.
        g=g or self._selected_steam_game()
        if not g:
            if interactive:
                messagebox.showerror("Steam Launch Options","Select an installed Steam game first.")
            return False

        if self._steam_config_writer_running():
            if interactive:
                messagebox.showwarning(
                    "Steam Is Running",
                    "The Steam client must be closed before launch options can be written safely."
                )
            self.refresh_selected_steam_launch_state()
            return False

        if launch is None:
            launch,preset_name=self._fresh_launch_options_for_steam_game(g)
        else:
            launch=str(launch or "").strip() or None
        if not launch:
            if interactive:
                messagebox.showerror(
                    "Steam Launch Options",
                    "No generated launch options are available. Associate this game with a rule that has a graphics preset first."
                )
            return False
        # Keep the preview synchronized for the user, but it is not the source
        # of truth for this write.
        if hasattr(self,"steam_launch_preview"):
            self.steam_launch_preview.delete(0,"end")
            self.steam_launch_preview.insert(0,launch)

        cfg=cfg or self._steam_localconfig_for_selected_game()
        if not cfg:
            if interactive:
                messagebox.showerror("Steam Launch Options","No Steam localconfig.vdf was detected.")
            return False

        current=self._read_launch_options_from_localconfig(cfg["path"],g["appid"])
        audit_path=self._steam_apply_audit("BEGIN",g=g,cfg=cfg,launch=launch,current=current,detail=f"preset={preset_name or ''}")
        if interactive:
            if not messagebox.askyesno(
                "Write Steam Launch Options",
                f"Write launch options for:\n\n{g['name']}  (AppID {g['appid']})\n\n"
                f"Current:\n{current or '(none)'}\n\nNew:\n{launch}\n\n"
                "A full backup of localconfig.vdf will be created first."
            ):
                return False

        try:
            original=pathlib.Path(cfg["path"]).read_text(encoding="utf-8",errors="strict")
            patched=self._patch_steam_launch_options_text(original,g["appid"],launch)
            if patched==original:
                self.steam_status.configure(text="Launch options already match; nothing was changed.",fg=MUTED)
                self.refresh_selected_steam_launch_state()
                return True

            backup=self._steam_backup_localconfig(cfg,g["appid"])
            tmp=cfg["path"]+".amd-control-center.tmp"
            pathlib.Path(tmp).write_text(patched,encoding="utf-8")
            os.replace(tmp,cfg["path"])

            verify=self._read_launch_options_from_localconfig(cfg["path"],g["appid"])
            self._steam_apply_audit("READBACK",g=g,cfg=cfg,launch=launch,current=current,readback=verify,detail=f"backup={backup}")
            if verify!=launch:
                shutil.copy2(backup,cfg["path"])
                restored=self._read_launch_options_from_localconfig(cfg["path"],g["appid"])
                self._steam_apply_audit("VERIFY-FAILED-RESTORED",g=g,cfg=cfg,launch=launch,current=current,readback=restored,detail=f"backup={backup}")
                raise RuntimeError("Verification failed after writing AppID "+str(g.get("appid"))+". The backup was restored automatically.")

            self._remember_verified_steam_apply(g,cfg,launch,audit_path)
            self._steam_apply_audit("VERIFIED",g=g,cfg=cfg,launch=launch,current=current,readback=verify,detail=f"backup={backup}")
            self.steam_status.configure(
                text=f"Verified Steam write for {g['name']} (AppID {g['appid']}) • {cfg['path']}",fg=GREEN
            )
            self.refresh_selected_steam_launch_state()
            self.after(100,self.refresh_steam_games)
            return True
        except Exception as e:
            self._steam_apply_audit("ERROR",g=g,cfg=cfg,launch=launch,detail=str(e))
            if interactive:
                messagebox.showerror("Steam Launch Options",str(e))
            else:
                self.steam_status.configure(text=f"Steam write failed: {e}",fg=RED)
            self.refresh_selected_steam_launch_state()
            return False

    def _associated_steam_sync_plan(self):
        source_games=self.steam_all_games if hasattr(self,"steam_all_games") else self.steam_games
        games_by_appid={str(g.get("appid","")):g for g in source_games}
        plan=[]
        for i,rule in enumerate(self.game_profile_data.get("rules",[])):
            appid=str(rule.get("steam_appid","")).strip()
            gfx=rule.get("graphics_preset","").strip()
            if not appid or not gfx:
                continue
            g=games_by_appid.get(appid)
            if not g:
                continue
            generated=self._launch_options_for_graphics_preset(gfx)
            if not generated:
                continue
            plan.append({
                "rule_index":i,
                "rule":rule,
                "game":g,
                "appid":appid,
                "graphics_preset":gfx,
                "generated":generated,
            })
        return plan

    def refresh_steam_bulk_status(self):
        if not hasattr(self,"steam_bulk_status"):
            return
        plan=self._associated_steam_sync_plan()
        if not plan:
            self.steam_bulk_status.configure(
                text="Bulk sync: no installed Steam games are associated with a rule that has a graphics preset.",
                fg=MUTED
            )
            return

        cfg=self._steam_localconfig_for_selected_game()
        if not cfg:
            self.steam_bulk_status.configure(
                text=f"Bulk sync: {len(plan)} associated game(s), but Steam localconfig.vdf was not found.",
                fg=YELLOW
            )
            return

        applied=different=notset=0
        for item in plan:
            current=self._read_launch_options_from_localconfig(cfg["path"],item["appid"])
            state,_,_=self._steam_launch_sync_state(current,item["generated"])
            if state=="APPLIED":
                applied+=1
            elif state=="NOT SET":
                notset+=1
            else:
                different+=1

        self.steam_bulk_status.configure(
            text=f"Bulk sync: {len(plan)} associated game(s)  •  {applied} applied  •  "
                 f"{different} different  •  {notset} not set",
            fg=GREEN if applied==len(plan) else YELLOW
        )

    def _backup_localconfig_for_bulk_sync(self, cfg):
        stamp=time.strftime("%Y%m%d-%H%M%S")
        dest=os.path.join(
            self._steam_backup_dir(),
            f"localconfig-user{cfg['uid']}-bulk-{stamp}.vdf.bak"
        )
        shutil.copy2(cfg["path"],dest)
        self.game_profile_data["steam_bulk_backup_latest"]=dest
        save_game_profiles_file(self.game_profile_data)
        return dest

    def _perform_bulk_steam_sync(self):
        if self._steam_process_running():
            raise RuntimeError("Steam must be completely closed before bulk sync.")

        plan=self._associated_steam_sync_plan()
        if not plan:
            raise RuntimeError(
                "No installed Steam games are associated with a rule that has a graphics preset."
            )

        cfg=self._steam_localconfig_for_selected_game()
        if not cfg:
            raise RuntimeError("No Steam localconfig.vdf was detected.")

        original=pathlib.Path(cfg["path"]).read_text(encoding="utf-8",errors="strict")
        patched=original
        changed=[]
        unchanged=[]

        for item in plan:
            current=self._read_launch_options_from_localconfig(cfg["path"],item["appid"])
            if self._normalize_launch_options(current)==self._normalize_launch_options(item["generated"]):
                unchanged.append(item)
                continue
            patched=self._patch_steam_launch_options_text(
                patched,item["appid"],item["generated"]
            )
            changed.append(item)

        if not changed:
            return {
                "changed":0,
                "unchanged":len(unchanged),
                "backup":"",
                "games":[x["game"]["name"] for x in plan],
            }

        backup=self._backup_localconfig_for_bulk_sync(cfg)
        tmp=cfg["path"]+".amd-control-center.bulk.tmp"
        try:
            pathlib.Path(tmp).write_text(patched,encoding="utf-8")
            os.replace(tmp,cfg["path"])

            failed=[]
            for item in changed:
                verify=self._read_launch_options_from_localconfig(cfg["path"],item["appid"])
                if self._normalize_launch_options(verify)!=self._normalize_launch_options(item["generated"]):
                    failed.append(item["game"]["name"])
            if failed:
                shutil.copy2(backup,cfg["path"])
                raise RuntimeError(
                    "Verification failed for: "+", ".join(failed)+
                    ". The pre-sync backup was restored automatically."
                )
        except Exception:
            try:
                if os.path.exists(tmp):
                    os.unlink(tmp)
            except Exception:
                pass
            raise

        return {
            "changed":len(changed),
            "unchanged":len(unchanged),
            "backup":backup,
            "games":[x["game"]["name"] for x in changed],
        }

    def close_steam_and_sync_all_associated_games(self):
        plan=self._associated_steam_sync_plan()
        if not plan:
            messagebox.showinfo(
                "Sync All Steam Games",
                "There are no installed Steam games associated with a game rule that has a graphics preset."
            )
            return

        running=self._steam_process_running()
        names="\n".join(f"• {x['game']['name']}" for x in plan[:12])
        extra=f"\n… and {len(plan)-12} more" if len(plan)>12 else ""

        prompt=(
            f"Sync launch options for {len(plan)} associated Steam game(s)?\n\n"
            f"{names}{extra}\n\n"
            "Steam will be closed first if it is running. One full localconfig.vdf backup "
            "will be created before the batch write, and every changed AppID will be verified."
        )
        if not messagebox.askyesno("Close Steam & Sync All",prompt):
            return

        if running:
            self.steam_bulk_status.configure(text="Waiting for Steam to close…",fg=YELLOW)
            self.update_idletasks()
            if not self._request_steam_shutdown():
                lingering=getattr(self,"_steam_shutdown_lingering_pids",[])
                pid_note=(f" Lingering Steam client PID(s): {', '.join(map(str,lingering))}." if lingering else "")
                messagebox.showwarning(
                    "Steam Still Running",
                    "Steam launch options were not written because the real Steam client is still running in the background."+pid_note
                )
                self.refresh_steam_bulk_status()
                return

        try:
            result=self._perform_bulk_steam_sync()
            if result["changed"]==0:
                messagebox.showinfo(
                    "Sync All Steam Games",
                    f"All {result['unchanged']} associated game(s) already match their graphics presets."
                )
            else:
                messagebox.showinfo(
                    "Sync All Steam Games",
                    f"Updated {result['changed']} game(s). "
                    f"{result['unchanged']} already matched.\n\n"
                    f"Backup:\n{result['backup']}"
                )
            self.refresh_steam_games()
            self.refresh_steam_bulk_status()
        except Exception as e:
            messagebox.showerror("Sync All Steam Games",str(e))
            self.refresh_steam_bulk_status()

    def close_steam_and_apply_selected_launch_options(self, g=None):
        # g may be locked by Quick Setup before UI refreshes. Preserve that exact
        # AppID/title for shutdown, write, readback, and success reporting.
        g=g or self._selected_steam_game()
        if not g:
            messagebox.showerror("Steam Launch Options","Select an installed Steam game first.")
            return

        launch,preset_name=self._fresh_launch_options_for_steam_game(g)
        if not launch:
            messagebox.showerror(
                "Steam Launch Options",
                "No generated launch options are available for the selected game."
            )
            return
        if hasattr(self,"steam_launch_preview"):
            self.steam_launch_preview.delete(0,"end")
            self.steam_launch_preview.insert(0,launch)

        cfg=self._steam_localconfig_for_selected_game()
        if not cfg:
            messagebox.showerror("Steam Launch Options","No Steam localconfig.vdf was detected.")
            return
        current=self._read_launch_options_from_localconfig(cfg["path"],g["appid"])
        self._steam_apply_audit("PREPARED",g=g,cfg=cfg,launch=launch,current=current,detail=f"preset={preset_name or ''}")

        running=self._steam_config_writer_running()
        if running:
            if not messagebox.askyesno(
                "Close Steam & Apply",
                f"Close Steam, then write the generated launch options for:\n\n"
                f"{g['name']}  (AppID {g['appid']})\n\n"
                "Steam will be asked to exit cleanly. If the real same-user Steam client stays alive in the background, "
                "ALCC will send it SIGTERM before writing. A full localconfig.vdf backup will be created first."
            ):
                return
            self.steam_status.configure(text="Waiting for Steam to close…",fg=YELLOW)
            self.update_idletasks()
            if not self._request_steam_shutdown():
                lingering=getattr(self,"_steam_shutdown_lingering_pids",[])
                pid_note=(f"\n\nLingering Steam client PID(s): {', '.join(map(str,lingering))}." if lingering else "")
                messagebox.showwarning(
                    "Steam Still Running",
                    "Steam launch options were not written because the real Steam client is still running in the background."
                    f"{pid_note}\n\nClose Steam completely, then try again."
                )
                # Refresh the Steam readback first, then set the transactional
                # Quick Setup result last so the refresh cannot overwrite the
                # failure state with the earlier "Applying..." message.
                self.refresh_selected_steam_launch_state()
                if hasattr(self,"steam_quick_status"):
                    try:
                        self.steam_quick_status.configure(
                            text="GPU profile applied; Steam launch options were not written because the Steam client is still running.",
                            fg=YELLOW
                        )
                    except Exception:
                        pass
                return
        else:
            if not messagebox.askyesno(
                "Apply Steam Launch Options",
                f"Steam is already closed. Write the generated launch options for:\n\n"
                f"{g['name']}  (AppID {g['appid']})?"
            ):
                return

        if self._perform_selected_steam_launch_write(
            interactive=False,g=g,launch=launch,preset_name=preset_name,cfg=cfg
        ):
            if hasattr(self,"steam_quick_status"):
                try:
                    if "Applying launch options to Steam" in self.steam_quick_status.cget("text"):
                        self.steam_quick_status.configure(
                            text="Game settings synchronized, GPU profile applied, and Steam launch options written successfully.",
                            fg=GREEN
                        )
                except Exception:
                    pass
            messagebox.showinfo(
                "Steam Launch Options",
                f"Launch options for {g['name']} (AppID {g['appid']}) were written and read back successfully.\n\n"
                f"Verified file:\n{cfg['path']}\n\n"
                f"Audit log:\n{os.path.join(CONFIG_DIR,'steam-apply-audit.log')}\n\n"
                "You can now reopen Steam."
            )

    def reopen_steam(self):
        if self._steam_process_running():
            self.steam_status.configure(text="Steam is already running.",fg=MUTED)
            self.refresh_selected_steam_launch_state()
            return
        steam_bin=shutil.which("steam")
        if not steam_bin:
            messagebox.showerror("Reopen Steam","The Steam executable was not found in PATH.")
            return
        try:
            subprocess.Popen(
                [steam_bin],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                start_new_session=True
            )
            self.steam_status.configure(text="Steam launch requested.",fg=GREEN)
            self.after(2500,self.refresh_selected_steam_launch_state)
        except Exception as e:
            messagebox.showerror("Reopen Steam",str(e))

    def write_selected_steam_launch_options(self):
        if self._steam_process_running():
            messagebox.showwarning(
                "Steam Is Running",
                "Steam is currently running. Use Close Steam & Apply for the guided workflow, "
                "or close Steam manually before writing."
            )
            self.refresh_selected_steam_launch_state()
            return
        self._perform_selected_steam_launch_write(interactive=True)

    def restore_latest_steam_backup(self):
        g=self._selected_steam_game()
        if not g:
            messagebox.showerror("Restore Steam Backup","Select an installed Steam game first.")
            return
        if self._steam_process_running():
            messagebox.showwarning("Steam Is Running","Close Steam completely before restoring a Steam backup.")
            return

        backup=self.game_profile_data.get("steam_backup_latest",{}).get(str(g["appid"]),"")
        if not backup or not os.path.isfile(backup):
            messagebox.showerror("Restore Steam Backup","No saved backup was found for this game.")
            return
        cfg=self._steam_localconfig_for_selected_game()
        if not cfg:
            messagebox.showerror("Restore Steam Backup","No Steam localconfig.vdf was detected.")
            return

        if not messagebox.askyesno(
            "Restore Steam Backup",
            f"Restore the most recent pre-write localconfig.vdf backup for {g['name']}?\n\n"
            f"Backup:\n{backup}\n\n"
            "This restores the entire Steam localconfig.vdf file to its pre-write state."
        ):
            return
        try:
            shutil.copy2(backup,cfg["path"])
            self.steam_status.configure(text=f"Restored backup for {g['name']}.",fg=GREEN)
            self.refresh_selected_steam_launch_state()
            self.after(100,self.refresh_steam_games)
        except Exception as e:
            messagebox.showerror("Restore Steam Backup",str(e))

