        def _color_control(parent,row,column,label,var,values,command,width=10,status_attr=None):
            cell=tk.Frame(parent,bg="#0b1119")
            cell.grid(row=row,column=column,sticky="ew",padx=(0,12) if column==0 else (12,0),pady=3)
            tk.Label(cell,text=label,bg="#0b1119",fg=FG,width=15,anchor="w").pack(side="left")
