            combo.pack(side="left",padx=(4,5))
            button=ttk.Button(cell,text="Apply",command=command)
            button.pack(side="left")
            status=None
            if status_attr:
                status=tk.Label(cell,text="",bg="#0b1119",fg=MUTED,font=("Sans",9))
                status.pack(side="left",padx=(7,0))
                setattr(self,status_attr,status)
            return combo,button

