    def _write_gpu_authorization_preference(self, value):
        try:
            os.makedirs(CONFIG_DIR,exist_ok=True)
            with open(AUTH_PREF_FILE,"w",encoding="utf-8") as handle:
                handle.write(f"passwordless_policykit={value}\n")
        except Exception:
            pass

    def _refresh_gpu_authorization_controls(self):
        if not hasattr(self,"system_auth_status"):
            return
        text,color=self._gpu_authorization_label()
        self.system_auth_status.configure(text=text,fg=color)
        enabled=self._passwordless_gpu_control_status()
        self.system_auth_button.configure(
            text="Disable Passwordless Authorization" if enabled else "Enable Passwordless Authorization"
        )

    def _toggle_passwordless_gpu_authorization(self):
        enabled=self._passwordless_gpu_control_status()
        mode="disable" if enabled else "enable"
        verb="disable" if enabled else "enable"
        if not os.path.isfile(AUTH_SETUP_SCRIPT):
            messagebox.showerror(
                "GPU Authorization",
                "The installed authorization setup script is missing. Reinstall AMD Linux Control Center first."
            )
            return
        if not shutil.which("pkexec"):
            messagebox.showerror("GPU Authorization","pkexec is unavailable on this system.")
            return
        if not messagebox.askyesno(
            "GPU Authorization",
            f"{verb.title()} passwordless GPU authorization for AMD Linux Control Center?\n\n"
            + (
                "After disabling it, privileged GPU changes may require authentication."
                if enabled else
                "This authorizes only ALCC's validated AMDGPU helper using the supported host mechanism."
            )
        ):
            return
        try:
            user=os.environ.get("USER") or os.environ.get("LOGNAME") or str(os.getuid())
            proc=subprocess.run(
                ["pkexec","env",f"TARGET_DESKTOP_USER={user}","bash",AUTH_SETUP_SCRIPT,mode],
                text=True,capture_output=True,timeout=30,check=False
            )
            if proc.returncode != 0:
                detail=(proc.stderr or proc.stdout or "Authorization change failed.").strip()
                raise RuntimeError(detail)
            self._write_gpu_authorization_preference("disabled" if enabled else "enabled")
            self.after(250,self._refresh_gpu_authorization_controls)
            messagebox.showinfo(
                "GPU Authorization",
                "Passwordless GPU authorization disabled." if enabled
                else "Passwordless GPU authorization enabled."
            )
        except Exception as exc:
            messagebox.showerror("GPU Authorization",str(exc))
            self._refresh_gpu_authorization_controls()

    def _passwordless_gpu_control_status(self):
        """Use the same noninteractive authorization probe as the GPU backend."""
        return passwordless_gpu_authorization_active()

    def _gpu_authorization_label(self):
        if self._passwordless_gpu_control_status():
            return "GPU authorization: passwordless helper enabled", GREEN
        helper_ok=os.path.isfile(PROFILE_APPLY_HELPER_SYSTEM) and os.access(PROFILE_APPLY_HELPER_SYSTEM,os.X_OK)
        if helper_ok:
            return "GPU authorization: PolicyKit helper installed • password may be required", MUTED
        if shutil.which("pkexec"):
            return "GPU authorization: standard PolicyKit on demand", MUTED
        return "GPU authorization: privileged GPU changes unavailable", YELLOW

