    def populate_gpu_selector(self):
        vals=[g.short_name() for g in self.gpus]
        self.gpu_combo["values"]=vals
        if self.gpu and self.gpu in self.gpus:
            self.gpu_combo.current(self.gpus.index(self.gpu))
        elif vals:
            self.gpu_combo.current(0)
            # Keep the application's selected GPU synchronized with the visual
            # combobox selection. The previous code selected row 0 visually but
            # could leave self.gpu unset.
            self.gpu=self.gpus[0]
        self._sync_capability_gpu()

    def on_gpu_change(self,event=None):
        if self._curve_is_running():
            self._signal_curve_stop()
        idx=self.gpu_combo.current()
        if 0<=idx<len(self.gpus):
            self.gpu=self.gpus[idx]
            self._sync_capability_gpu()
            self.populate_static()
            self.refresh_once()

    def refresh_devices(self):
        oldpci=self.gpu.pci_slot() if self.gpu else None
        self.gpus=AMDGPU.discover()
        self.gpu=next((g for g in self.gpus if g.pci_slot()==oldpci),None) or self._preferred_gpu()
        self.populate_gpu_selector(); self._sync_capability_gpu(); self.populate_static(); self.refresh_once()

    def populate_static(self):
        self.cap_tree.delete(*self.cap_tree.get_children())
        self.sys_tree.delete(*self.sys_tree.get_children())
        if not self.gpu:
            return
        g=self.gpu
        interfaces=[
            "power_dpm_force_performance_level","pp_power_profile_mode","pp_od_clk_voltage",
            "pp_dpm_sclk","pp_dpm_mclk","pp_dpm_pcie","gpu_busy_percent","mem_info_vram_used"
        ]
        for name in interfaces:
            p=os.path.join(g.device,name)
            if os.path.exists(p):
                state="Available (root write required)" if not os.access(p,os.W_OK) and os.access(p,os.R_OK) else ("Writable" if os.access(p,os.W_OK) else "Read only")
            else:
                state="Not exposed"
            self.cap_tree.insert("","end",values=(name,state))
        if g.hwmon:
            for name in ("power1_cap","pwm1","pwm1_enable","fan1_target"):
                p=os.path.join(g.hwmon,name)
                if os.path.exists(p):
                    state="Available (root write required)" if not os.access(p,os.W_OK) else "Writable"
                    self.cap_tree.insert("","end",values=(f"hwmon/{name}",state))
        for k,v in g.info().items():
            self.sys_tree.insert("","end",values=(k,v))
        self._populate_controls()
        # Synchronize Advanced Performance / Clock Domains from the driver's
        # actual current mode at startup and whenever the selected GPU changes.
        if hasattr(self,"dpm_domain_text"):
            self.refresh_dpm_domain_monitor(rebuild_controls=True)
        self.refresh_fan_status()

    def _read_live_clock_mhz(self, label_name):
        if not self.gpu or not self.gpu.hwmon:
            return None
        for lp in glob.glob(os.path.join(self.gpu.hwmon,"freq*_label")):
            if read_text(lp).strip().lower()==label_name.lower():
                ip=lp.replace("_label","_input")
                val=read_int(ip)
                if val is not None:
                    return val/1_000_000.0
        return None

    def refresh_clock_telemetry(self):
        if not hasattr(self,"live_gpu_clock") or not self.gpu:
            return
        gclk=self._read_live_clock_mhz("sclk")
        mclk=self._read_live_clock_mhz("mclk")
        self.live_gpu_clock.configure(text=f"{gclk:.0f} MHz" if gclk is not None else "—")
        self.live_mem_clock.configure(text=f"{mclk:.0f} MHz" if mclk is not None else "—")

    def _temp_crit_c(self, wanted_label):
        if not self.gpu or not self.gpu.hwmon:
            return None
        for lp in glob.glob(os.path.join(self.gpu.hwmon,"temp*_label")):
            if read_text(lp).strip().lower()==wanted_label.lower():
                cp=lp.replace("_label","_crit")
                val=read_int(cp)
                if val is not None:
                    return val/1000.0
        return None

    def _driver_throttle_reason(self):
        if not self.gpu:
            return None
        # Different kernels/ASICs expose different optional text/status nodes.
        # Only display a reason when a readable interface actually exists.
        candidates=(
            "throttle_status",
            "throttling_status",
            "gpu_throttle_status",
        )
        for name in candidates:
            p=os.path.join(self.gpu.device,name)
            if os.path.exists(p) and os.access(p,os.R_OK):
                raw=read_text(p).strip()
                if raw:
                    return f"{name}: {raw}"
        return None

    def refresh_electrical_telemetry(self, d=None):
        if not hasattr(self,"electrical_labels") or not self.gpu:
            return
        if d is None:
            d=self.gpu.metric()

        v=d.get("voltage_v")
        p=d.get("power_w")
        clk=d.get("sclk")
        eff=d.get("electrical_efficiency_mhz_per_w")

        val,sub=self.electrical_labels["voltage"]
        if v is not None:
            val.configure(text=f"{v:.3f} V",fg=GREEN)
            sub.configure(text=f"{d.get('voltage_mv',0):.0f} mV VDDGFX",fg=MUTED)
        else:
            val.configure(text="—",fg=MUTED)
            sub.configure(text="Sensor unavailable",fg=MUTED)

        val,sub=self.electrical_labels["power"]
        if p is not None:
            cap=d.get("power_cap_w")
            val.configure(text=f"{p:.1f} W",fg=GREEN if not cap or p < cap*0.9 else YELLOW)
            sub.configure(text=f"{(100*p/cap):.0f}% of cap" if cap else "Board power",fg=MUTED)
        else:
            val.configure(text="—",fg=MUTED)
            sub.configure(text="Sensor unavailable",fg=MUTED)

        val,sub=self.electrical_labels["clock"]
        if clk is not None:
            val.configure(text=f"{clk:.0f} MHz",fg=GREEN)
            sub.configure(text="Instantaneous SCLK",fg=MUTED)
        else:
            val.configure(text="—",fg=MUTED)
            sub.configure(text="Telemetry unavailable",fg=MUTED)

        val,sub=self.electrical_labels["efficiency"]
        if eff is not None:
            val.configure(text=f"{eff:.1f} MHz/W",fg=GREEN)
            sub.configure(text="Live observational ratio",fg=MUTED)
        else:
            val.configure(text="—",fg=MUTED)
            sub.configure(text="Requires clock + power",fg=MUTED)

    def refresh_performance_limits(self, d=None):
        if not hasattr(self,"limit_overall") or not self.gpu:
            return
        if d is None:
            d=self.gpu.metric()

        # Board power
        pwr=d.get("power_w")
        cap=d.get("power_cap_w")
        power_ratio=None
        if pwr is not None and cap:
            power_ratio=100.0*pwr/cap
            pval,psub=self.limit_labels["power"]
            pval.configure(text=f"{pwr:.0f} / {cap:.0f} W")
            if power_ratio>=95:
                pc=RED; state="At/near power cap"
            elif power_ratio>=85:
                pc=YELLOW; state="Approaching power cap"
            else:
                pc=GREEN; state="Power headroom"
            pval.configure(fg=pc)
            psub.configure(text=f"{power_ratio:.0f}% of board limit",fg=pc if power_ratio>=85 else MUTED)
        else:
            pval,psub=self.limit_labels["power"]
            pval.configure(text="—",fg=MUTED)
            psub.configure(text="Sensor unavailable",fg=MUTED)

        # Junction thermal headroom
        temp=d.get("temps",{}).get("junction")
        if temp is None:
            temp=d.get("temps",{}).get("edge")
            temp_label="edge"
        else:
            temp_label="junction"
        crit=self._temp_crit_c(temp_label) if temp is not None else None
        thermal_headroom=None
        tval,tsub=self.limit_labels["thermal"]
        if temp is not None:
            tval.configure(text=f"{temp:.0f} °C")
            if crit is not None:
                thermal_headroom=crit-temp
                if thermal_headroom<=5:
                    tc=RED; tstate="At/near thermal limit"
                elif thermal_headroom<=15:
                    tc=YELLOW; tstate="Thermal margin narrowing"
                else:
                    tc=GREEN; tstate="Thermal headroom"
                tval.configure(fg=tc)
                tsub.configure(text=f"{thermal_headroom:.0f} °C below {crit:.0f} °C critical",fg=tc if thermal_headroom<=15 else MUTED)
            else:
                tval.configure(fg=FG)
                tsub.configure(text=f"{temp_label.title()} sensor • critical value unavailable",fg=MUTED)
        else:
            tval.configure(text="—",fg=MUTED)
            tsub.configure(text="Sensor unavailable",fg=MUTED)

        # Load
        busy=d.get("busy")
        lval,lsub=self.limit_labels["load"]
        if busy is not None:
            lval.configure(text=f"{busy}%")
            lc=GREEN if busy<85 else (YELLOW if busy<98 else RED)
            lval.configure(fg=lc)
            lsub.configure(text="High utilization" if busy>=90 else "Utilization",fg=MUTED)
        else:
            lval.configure(text="—",fg=MUTED)
            lsub.configure(text="Sensor unavailable",fg=MUTED)

        # Clock headroom uses live instantaneous clock versus highest reported DPM ceiling.
        gclk=d.get("sclk")
        sstates=self.gpu.dpm_states("sclk")
        ceiling=max((x["mhz"] for x in sstates),default=None)
        cval,csub=self.limit_labels["clock"]
        clock_ratio=None
        if gclk is not None and ceiling:
            clock_ratio=100.0*gclk/ceiling
            head=max(0.0,ceiling-gclk)
            cval.configure(text=f"{gclk:.0f} / {ceiling:.0f} MHz")
            cval.configure(fg=GREEN if clock_ratio<90 else YELLOW)
            csub.configure(text=f"{head:.0f} MHz below reported ceiling",fg=MUTED)
        else:
            cval.configure(text="—",fg=MUTED)
            csub.configure(text="Telemetry unavailable",fg=MUTED)

        # Overall indicator: intentionally conservative.  It reports pressure,
        # not a definitive hardware throttle cause.
        overall="No active limit indicated"
        oc=GREEN
        if thermal_headroom is not None and thermal_headroom<=5:
            overall="THERMAL LIMIT PRESSURE"
            oc=RED
        elif power_ratio is not None and power_ratio>=95:
            overall="POWER LIMIT PRESSURE"
            oc=RED
        elif busy is not None and busy>=90:
            if thermal_headroom is not None and thermal_headroom<=15:
                overall="High load • thermal margin low"
                oc=YELLOW
            elif power_ratio is not None and power_ratio>=85:
                overall="High load • power margin low"
                oc=YELLOW
            elif clock_ratio is not None and clock_ratio>=90:
                overall="High load • near clock ceiling"
                oc=YELLOW
            else:
                overall="High GPU load"
                oc=YELLOW

        self.limit_overall.configure(text=overall,fg=oc)
        reason=self._driver_throttle_reason()
        if reason:
            self.limit_driver.configure(text=f"Driver throttle reason: {reason}",fg=YELLOW)
        else:
            self.limit_driver.configure(
                text="Driver throttle reason: not exposed by this kernel/GPU interface",
                fg=MUTED
            )

    def refresh_clock_domains(self):
        if not hasattr(self,"domain_labels") or not self.gpu:
            return

        names={
            "pcie":"PCIe",
            "socclk":"SoC",
            "fclk":"Fabric",
            "dcefclk":"Display",
            "vclk":"Video",
            "dclk":"Decode",
            "vclk1":"Video1",
            "dclk1":"Decode1",
        }

        for key in self.domain_labels:
            val,sub=self.domain_labels[key]
            states=self.gpu.dpm_domain_states(key)
            if not states:
                val.configure(text="Unavailable",fg=MUTED)
                sub.configure(text="Not exposed",fg=MUTED)
                continue

            active=next((x for x in states if x["active"]),None)
            if active:
                val.configure(text=active["text"],fg=GREEN)
                sub.configure(
                    text=f"Active state {active['index']} • {len(states)} available",
                    fg=MUTED
                )
            else:
                val.configure(text="No active marker",fg=YELLOW)
                sub.configure(text=f"{len(states)} states reported",fg=MUTED)

        ppf=os.path.join(self.gpu.device,"pp_features")
        if os.path.exists(ppf):
            raw=read_text(ppf).strip()
            if raw:
                # Keep this compact; first useful line only, full raw remains discoverable in diagnostics.
                first=raw.splitlines()[0].strip()
                self.pp_features_label.configure(text=f"PowerPlay features: {first}")
            else:
                self.pp_features_label.configure(text="PowerPlay features: exposed, no readable value")
        else:
            self.pp_features_label.configure(text="PowerPlay features: not exposed")

    def _populate_controls(self):
        g=self.gpu
        levels=g.perf_levels() if g else []
        self.level_combo["values"]=levels
        cur=read_text(os.path.join(g.device,"power_dpm_force_performance_level")) if g else ""
        if cur in levels:self.level_combo.set(cur)
        elif levels:self.level_combo.current(0)

        sstates=g.dpm_states("sclk") if g else []
        mstates=g.dpm_states("mclk") if g else []
        pstates=g.dpm_domain_states("pcie") if g else []
        self._sclk_map={f"{x['index']} — {x['mhz']} MHz":x["index"] for x in sstates}
        self._mclk_map={f"{x['index']} — {x['mhz']} MHz":x["index"] for x in mstates}
        self._pcie_map={f"{x['index']} — {x['text']}":x["index"] for x in pstates}
        self.sclk_combo["values"]=list(self._sclk_map.keys())
        self.mclk_combo["values"]=list(self._mclk_map.keys())
        self.pcie_combo["values"]=list(self._pcie_map.keys())
        sa=next((f"{x['index']} — {x['mhz']} MHz" for x in sstates if x["active"]),None)
        ma=next((f"{x['index']} — {x['mhz']} MHz" for x in mstates if x["active"]),None)
        pa=next((f"{x['index']} — {x['text']}" for x in pstates if x["active"]),None)
        if sa:self.sclk_combo.set(sa)
        elif sstates:self.sclk_combo.current(0)
        if ma:self.mclk_combo.set(ma)
        elif mstates:self.mclk_combo.current(0)
        if pa:self.pcie_combo.set(pa)
        elif pstates:self.pcie_combo.current(0)
        self.sclk_combo.configure(state="readonly" if sstates else "disabled")
        self.mclk_combo.configure(state="readonly" if mstates else "disabled")
        self.pcie_combo.configure(state="readonly" if pstates else "disabled")
        self.sclk_apply.configure(state="normal" if sstates else "disabled")
        self.mclk_apply.configure(state="normal" if mstates else "disabled")
        self.pcie_apply.configure(state="normal" if pstates else "disabled")
        self.sclk_status.configure(text=f"DPM reports: {sa or 'Unknown'}")
        self.mclk_status.configure(text=f"DPM reports: {ma or 'Unknown'}")
        self.pcie_status.configure(text=f"DPM reports: {pa or 'Unknown'}")
        if sstates:
            self.gpu_ceiling_label.configure(text=f"{max(x['mhz'] for x in sstates)} MHz")
        else:
            self.gpu_ceiling_label.configure(text="—")
        if mstates:
            self.mem_ceiling_label.configure(text=f"{max(x['mhz'] for x in mstates)} MHz")
        else:
            self.mem_ceiling_label.configure(text="—")
        self.refresh_clock_telemetry()
        if g:
            snapshot=g.metric()
            self.refresh_performance_limits(snapshot)
            self.refresh_electrical_telemetry(snapshot)
            self.refresh_clock_domains()

        if hasattr(self,"builtin_profile_details"):
            self._update_builtin_profile_details()
            self._refresh_builtin_profile_status()
        profs=g.performance_profiles() if g else []
        self._profile_map={}
        self._profile_raw_map={}
        active_key=None
        for idx,name,is_active in profs:
            friendly=self._friendly_power_profile(name)
            key=f"{idx} — {friendly}"
            self._profile_map[key]=idx
            self._profile_raw_map[key]=name
            if is_active:
                active_key=key
        self.profile_combo["values"]=list(self._profile_map.keys())
        if active_key:
            self.profile_combo.set(active_key)
            self.profile_active_label.configure(text=f"Active: {active_key}",fg=GREEN)
        elif profs:
            self.profile_combo.current(0)
            self.profile_active_label.configure(text="Active: not marked by driver",fg=MUTED)
        else:
            self.profile_combo.set("")
            self.profile_active_label.configure(text="Active: unavailable",fg=MUTED)
        self.profile_combo.configure(state="readonly" if profs else "disabled")
        self._update_power_profile_description()

        if hasattr(self,"safe_write_status") and g:
            level=read_text(os.path.join(g.device,"power_dpm_force_performance_level"),"—")
            active_prof=next(
                (self._friendly_power_profile(name) for _,name,is_active in g.performance_profiles() if is_active),
                "—"
            )
            cap_now=g.power_cap_limits()
            cap_text=f"{cap_now[0]:.0f} W" if cap_now else "—"
            exposed=sum(1 for r in g.capability_snapshot() if r["exists"])
            total=len(g.capability_snapshot())
            self.safe_write_status.configure(
                text=f"Current: performance {level}  •  workload {active_prof}  •  power limit {cap_text}  "
                     f"•  detected interfaces {exposed}/{total}",
                fg=MUTED
            )

        lim=g.power_cap_limits() if g else None
        if lim:
            cur,lo,hi=lim
            self.power_scale.configure(from_=lo,to=hi,state="normal")
            self.power_var.set(cur)
        else:
            self.power_scale.configure(from_=0,to=1,state="disabled")
            self.power_var.set(0)
        self._update_power_label()
        self._refresh_power_limit_details()
        if hasattr(self,"recovery_status"):
            self._refresh_recovery_status()

    def _update_power_label(self):
        if not self.gpu:
            self.power_label.configure(text="—")
            if hasattr(self,"power_pct_label"): self.power_pct_label.configure(text="")
            return
        lim=self.gpu.power_cap_limits()
        if not lim:
            self.power_label.configure(text="Not exposed")
            if hasattr(self,"power_pct_label"): self.power_pct_label.configure(text="")
            return
        _,lo,hi=lim
        val=float(self.power_var.get())
        self.power_label.configure(text=f"{val:.0f} W")
        if hasattr(self,"power_pct_label"):
            if hi>lo:
                pct=100.0*(val-lo)/(hi-lo)
                self.power_pct_label.configure(text=f"{pct:.0f}% of range")
            else:
                self.power_pct_label.configure(text="fixed limit")

    def _refresh_power_limit_details(self):
        if not hasattr(self,"power_detail"):
            return
        if not self.gpu:
            self.power_detail.configure(text="Power limit details: —")
            self.power_state.configure(text="")
            return
        lim=self.gpu.power_cap_limits()
        default=self.gpu.power_cap_default_w()
        if not lim:
            self.power_detail.configure(text="Power limit details: Unavailable")
            self.power_state.configure(text="")
            return
        cur,lo,hi=lim
        parts=[]
        if default is not None:
            parts.append(f"Default {default:.0f} W")
        parts.append(f"Current {cur:.0f} W")
        parts.append(f"Minimum {lo:.0f} W")
        parts.append(f"Maximum {hi:.0f} W")
        self.power_detail.configure(text="Power limit details: " + "  •  ".join(parts))

        if abs(cur-hi)<0.5:
            self.power_state.configure(text="AT DRIVER MAXIMUM",fg=YELLOW)
        elif default is not None and abs(cur-default)<0.5:
            self.power_state.configure(text="DEFAULT",fg=GREEN)
        elif default is not None and cur>default:
            self.power_state.configure(text="ABOVE DEFAULT",fg=YELLOW)
        elif default is not None and cur<default:
            self.power_state.configure(text="BELOW DEFAULT",fg=YELLOW)
        else:
            self.power_state.configure(text="",fg=MUTED)

    def _confirm_write(self,title,detail):
        return messagebox.askyesno(title,detail+"\n\nThis writes to the Linux amdgpu driver and may request administrator authentication.")

    def toggle_advanced_dpm(self):
        self.advanced_dpm_open=not self.advanced_dpm_open
        if self.advanced_dpm_open:
            self.advanced_dpm_button.configure(text="▼ Advanced DPM State Controls")
            self.advanced_dpm_frame.pack(fill="x",padx=0,pady=(0,6))
        else:
            self.advanced_dpm_button.configure(text="▶ Advanced DPM State Controls")
            self.advanced_dpm_frame.pack_forget()

    def _apply_dpm_state(self, domain):
        if not self.gpu:return
        if domain=="sclk":
            key=self.sclk_combo.get()
            idx=self._sclk_map.get(key)
            label="GPU"
        elif domain=="mclk":
            key=self.mclk_combo.get()
            idx=self._mclk_map.get(key)
            label="Memory"
        elif domain=="pcie":
            key=self.pcie_combo.get()
            idx=self._pcie_map.get(key)
            label="PCIe"
        else:
            messagebox.showerror("Unsupported","Unknown DPM domain.")
            return
        if idx is None:
            messagebox.showerror("Unsupported",f"No {label.lower()} clock state is selected.")
            return
        state_path=os.path.join(self.gpu.device,f"pp_dpm_{domain}")
        perf_path=os.path.join(self.gpu.device,"power_dpm_force_performance_level")
        if not (os.path.exists(state_path) and os.path.exists(perf_path)):
            messagebox.showerror("Unsupported","The required AMDGPU DPM interfaces are not exposed.")
            return
        if domain=="pcie":
            confirm_title="Lock PCIe DPM state"
            confirm_detail=f"Lock PCIe to state {key}?\n\nThis can increase idle power consumption."
        else:
            confirm_title=f"Lock {label} clock state"
            confirm_detail=f"Lock {label.lower()} clock to state {key}?"
        if not self._confirm_write(confirm_title,confirm_detail):
            return
        try:
            # One privileged transaction: manual mode first, then select the state.
            atomic_write_sysfs_many([(perf_path,"manual"),(state_path,str(idx))])
            suffix="state" if domain=="pcie" else "clock"
            self.status.configure(text=f"● {label} {suffix} locked: {key}",foreground=GREEN)
            self.after(500,self._populate_controls)
        except Exception as e:
            messagebox.showerror("Could not apply clock state",str(e))

    def apply_sclk_state(self):
        self._apply_dpm_state("sclk")

    def apply_mclk_state(self):
        self._apply_dpm_state("mclk")

    def apply_pcie_state(self):
        self._apply_dpm_state("pcie")

    def reset_dpm_auto(self):
        if not self.gpu:return
        perf_path=os.path.join(self.gpu.device,"power_dpm_force_performance_level")
        if not os.path.exists(perf_path):
            messagebox.showerror("Unsupported","The AMDGPU performance-level interface is not exposed.")
            return
        if not self._confirm_write("Return clocks to automatic",
                                   f"Return {self.gpu.card_name} to the normal/default automatic dynamic clock selection?"):
            return
        try:
            atomic_write_sysfs(perf_path,"auto")
            self.status.configure(text="● Restored default automatic clock control",foreground=GREEN)
            self.after(500,self._populate_controls)
        except Exception as e:
            messagebox.showerror("Could not restore automatic mode",str(e))

    def _capture_tuning_telemetry(self):
        if not self.gpu:
            return None
        d=self.gpu.metric()
        temp=d.get("temps",{}).get("junction")
        if temp is None:
            temp=d.get("temps",{}).get("edge")
        if temp is None and d.get("temps"):
            try:
                temp=next(iter(d["temps"].values()))
            except Exception:
                temp=None
        return {
            "sclk":d.get("sclk"),
            "voltage_v":d.get("voltage_v"),
            "power_w":d.get("power_w"),
            "temperature":temp,
            "busy":d.get("busy"),
        }

    def _format_tuning_value(self, key, value, unit):
        if value is None:
            return "—"
        if key=="voltage_v":
            return f"{float(value):.3f} {unit}"
        if key in ("sclk","power_w","temperature","busy"):
            return f"{float(value):.0f} {unit}"
        return f"{value} {unit}".strip()

    def refresh_tuning_current_values(self, snapshot=None):
        if not hasattr(self,"tuning_compare_labels") or not self.gpu:
            return
        if snapshot is None:
            snapshot=self._capture_tuning_telemetry()
        if not snapshot:
            return
        for key,(c_label,b_label,a_label,unit) in self.tuning_compare_labels.items():
            c_label.configure(
                text="Current: "+self._format_tuning_value(key,snapshot.get(key),unit)
            )
        if hasattr(self,"tuning_compare_status") and self.tuning_compare_status.cget("text")=="No tuning change measured yet.":
            self.tuning_compare_status.configure(
                text="Live current values shown — no tuning change measured yet.",
                fg=MUTED
            )

    def _show_tuning_comparison(self, label, before):
        if not before or not hasattr(self,"tuning_compare_labels"):
            return
        after=self._capture_tuning_telemetry()
        if not after:
            return
        for key,(c_label,b_label,a_label,unit) in self.tuning_compare_labels.items():
            c_label.configure(text="Current: "+self._format_tuning_value(key,after.get(key),unit))
            b_label.configure(text="  Before: "+self._format_tuning_value(key,before.get(key),unit))
            a_label.configure(text="  After: "+self._format_tuning_value(key,after.get(key),unit))
        self.tuning_compare_status.configure(
            text=f"{label} — sampled after driver update",
            fg=GREEN
        )

    def _schedule_tuning_comparison(self, label, before):
        # Allow the driver and sensors a short time to settle without blocking the UI.
        if before and hasattr(self,"tuning_compare_status"):
            self.tuning_compare_status.configure(text=f"{label} — waiting for live sample…",fg=YELLOW)
            self.after(900,lambda:self._show_tuning_comparison(label,before))

    def _verified_sysfs_write(self, path, value, verify=None, label="GPU setting"):
        """Write one validated sysfs value, then read it back and verify it."""
        atomic_write_sysfs(path,value)
        time.sleep(0.08)
        actual=read_text(path).strip()
        if verify is None:
            ok=(actual==str(value).strip())
        else:
            ok=bool(verify(actual))
        if not ok:
            raise RuntimeError(
                f"{label} was written, but read-back verification did not match. "
                f"Requested: {value}; driver reports: {actual or 'empty'}."
            )
        if hasattr(self,"safe_write_status"):
            self.safe_write_status.configure(text=f"Verified: {label} → {actual}",fg=GREEN)
        return actual

    def apply_perf_level(self):
        if not self.gpu:return
        val=self.level_combo.get().strip()
        if val not in self.gpu.perf_levels():
            messagebox.showerror("Unsupported","That performance level is not available."); return
        if not self._confirm_write("Apply performance level",f"Set {self.gpu.card_name} performance level to '{val}'?"):return
        try:
            before=self._capture_tuning_telemetry()
            path=os.path.join(self.gpu.device,"power_dpm_force_performance_level")
            actual=self._verified_sysfs_write(path,val,label="Performance level")
            self.status.configure(text=f"● Verified performance level {actual}",foreground=GREEN)
            self._schedule_tuning_comparison("Performance level",before)
            self.after(300,self._populate_controls)
        except Exception as e:
            messagebox.showerror("Could not apply setting",str(e))

    def _friendly_power_profile(self, raw_name):
        return gpu_profile_friendly_power_profile(raw_name)

    def _power_profile_description(self, raw_name):
        key=(raw_name or "").strip().upper()
        desc={
            "BOOTUP_DEFAULT":"AMD's normal default workload behavior.",
            "3D_FULL_SCREEN":"Biases power management toward sustained 3D/full-screen graphics workloads such as games.",
            "POWER_SAVING":"Biases power management toward lower power consumption.",
            "VIDEO":"Optimizes power-management behavior for video playback and media workloads.",
            "VR":"Workload hint intended for virtual-reality rendering.",
            "COMPUTE":"Biases behavior toward compute-heavy workloads.",
            "CUSTOM":"Driver custom profile. Behavior depends on the values exposed by the kernel/firmware.",
        }
        return desc.get(
            key,
            "Driver-defined AMDGPU workload/power-management profile. "
            "This profile name is being shown exactly because this GPU/kernel exposes it."
        )

    def _update_power_profile_description(self):
        if not hasattr(self,"profile_description"):
            return
        key=self.profile_combo.get()
        raw=self._profile_raw_map.get(key) if hasattr(self,"_profile_raw_map") else None
        self.profile_description.configure(
            text=self._power_profile_description(raw) if raw else ""
        )

    def apply_power_profile(self):
        if not self.gpu:return
        key=self.profile_combo.get()
        idx=self._profile_map.get(key)
        raw=self._profile_raw_map.get(key) if hasattr(self,"_profile_raw_map") else None
        if idx is None:
            messagebox.showerror("Unsupported","No selectable power profile is exposed for this GPU."); return
        friendly=self._friendly_power_profile(raw or key)
        if not self._confirm_write(
            "Apply AMD workload profile",
            f"Set {self.gpu.card_name} workload profile to {friendly}?\n\n"
            f"{self._power_profile_description(raw)}"
        ):return
        try:
            before=self._capture_tuning_telemetry()
            path=os.path.join(self.gpu.device,"pp_power_profile_mode")
            atomic_write_sysfs(path,str(idx))
            time.sleep(0.08)
            active=next(((i,n) for i,n,is_active in self.gpu.performance_profiles() if is_active),None)
            if not active or active[0]!=idx:
                raise RuntimeError(
                    f"Workload profile write was not verified. Requested profile index {idx}; "
                    f"driver active profile: {active[0] if active else 'not marked'}."
                )
            self.status.configure(text=f"● Verified AMD workload profile: {friendly}",foreground=GREEN)
            if hasattr(self,"safe_write_status"):
                self.safe_write_status.configure(text=f"Verified: Workload profile → {friendly}",fg=GREEN)
            self._schedule_tuning_comparison(f"Workload profile: {friendly}",before)
            self.after(300,self._populate_controls)
        except Exception as e:
            messagebox.showerror("Could not apply setting",str(e))

    def restore_default_power_cap(self):
        if not self.gpu or not self.gpu.hwmon:
            return
        default=self.gpu.power_cap_default_w()
        if default is None:
            messagebox.showerror("Unsupported","The driver does not expose a default board power limit.")
            return
        path=os.path.join(self.gpu.hwmon,"power1_cap")
        if not os.path.exists(path):
            messagebox.showerror("Unsupported","The board power-limit interface is unavailable.")
            return
        if not self._confirm_write(
            "Restore default board power limit",
            f"Restore {self.gpu.card_name} board power limit to the driver default of {default:.0f} W?"
        ):
            return
        try:
            before=self._capture_tuning_telemetry()
            requested=int(round(default*1_000_000))
            self._verified_sysfs_write(
                path,requested,
                verify=lambda raw: raw.isdigit() and abs(int(raw)-requested)<=1000,
                label="Default board power limit"
            )
            self.status.configure(text=f"● Verified default power limit {default:.0f} W",foreground=GREEN)
            self._schedule_tuning_comparison("Restore default power limit",before)
            self.after(300,self._populate_controls)
        except Exception as e:
            messagebox.showerror("Could not restore default power limit",str(e))

    def apply_power_cap(self):
        if not self.gpu or not self.gpu.hwmon:return
        lim=self.gpu.power_cap_limits()
        if not lim:
            messagebox.showerror("Unsupported","The driver does not expose a writable board power cap."); return
        cur,lo,hi=lim
        val=float(self.power_var.get())
        if not (lo<=val<=hi):
            messagebox.showerror("Out of range",f"Driver-reported range is {lo:.0f}–{hi:.0f} W."); return
        if not self._confirm_write("Apply board power limit",f"Set {self.gpu.card_name} board power limit to {val:.0f} W?"):return
        try:
            before=self._capture_tuning_telemetry()
            path=os.path.join(self.gpu.hwmon,"power1_cap")
            requested=int(round(val*1_000_000))
            self._verified_sysfs_write(
                path,requested,
                verify=lambda raw: raw.isdigit() and abs(int(raw)-requested)<=1000,
                label="Board power limit"
            )
            self.status.configure(text=f"● Verified power limit {val:.0f} W",foreground=GREEN)
            self._schedule_tuning_comparison("Board power limit",before)
            self.after(300,self._populate_controls)
        except Exception as e:
            messagebox.showerror("Could not apply setting",str(e))

    def _dashboard_cpu_load(self):
        """Return whole-system CPU utilization without inventing CPU frame latency."""
        try:
            fields=Path("/proc/stat").read_text().splitlines()[0].split()[1:]
            vals=[int(x) for x in fields]
            idle=vals[3] + (vals[4] if len(vals)>4 else 0)
            total=sum(vals)
            prev=self._live_cpu_prev
            self._live_cpu_prev=(total,idle)
            if not prev:
                return None
            dt=total-prev[0]; di=idle-prev[1]
            if dt<=0:return None
            return max(0.0,min(100.0,100.0*(dt-di)/dt))
        except Exception:
            return None

    def _latest_mangohud_sample(self,context=None):
        """Read current MangoHud telemetry and clearly distinguish provider metrics from sampled ones."""
        dirs=[pathlib.Path(context["expected_dir"])] if context and context.get("game_id") else [Path.home()/".local/share/amd-linux-control-center/telemetry",Path.home()/"MangoHud",Path.home()/".config/MangoHud"]
        if context and context.get("legacy_shared_dir"):
            legacy=pathlib.Path(context["legacy_shared_dir"])
            if legacy not in dirs:dirs.append(legacy)
        candidates=[]
        now=time.time()
        for d in dirs:
            try:
                if d.exists():
                    candidates += [p for p in d.glob("*.csv") if p.is_file()]
            except Exception:
                pass
        candidates=sorted(candidates,key=lambda p:p.stat().st_mtime if p.exists() else 0,reverse=True)

        mango_process_active=False
        if context:
            try:mango_process_active=any("mangohud" in (str(proc.get("comm") or "")+" "+str(proc.get("cmdline") or "")).casefold() for proc in self._process_snapshot().values())
            except Exception:pass
        preparation=(context or {}).get("telemetry_preparation_state")
        unavailable_state=("Telemetry preparation pending — restart Steam to activate" if preparation=="pending_steam_restart" else "Telemetry preparation pending — close the game, then restart Steam" if preparation=="pending_game_exit" else "Telemetry preparation pending — next safe launch" if preparation=="pending_next_launch" else "Telemetry setup failed" if preparation=="setup_failed" else "Telemetry provider unsupported" if preparation=="unsupported" else "Telemetry not instrumented")
        result={
            "fps":None,"low":None,"low_kind":None,
            "frametime":None,"frametime_kind":None,
            "gpu_frame":None,"cpu_frame":None,"source":None,
            "samples":[],"avg_fps":None,"stability_pct":None,
            "telemetry_state":unavailable_state if context and not context.get("instrumented") else "Game detected — waiting for telemetry",
            "parser_status":"No telemetry file found","expected_path":str(dirs[0]) if dirs else None,"file_exists":bool(candidates),"most_recent_sample_time":None,"mangohud_process_active":mango_process_active,
        }

        for p in candidates[:10]:
            try:
                if now-p.stat().st_mtime>15:
                    continue
                parsed=parse_mangohud_csv_text(p.read_text(errors="ignore"),max_samples=240)
                if not parsed:
                    continue
                result.update(parsed)
                result["source"]=p.name
                result["source_path"]=str(p)
                result["file_exists"]=True
                result["most_recent_sample_time"]=p.stat().st_mtime
                result["parser_status"]="Valid FPS sample parsed"
                result["telemetry_state"]="Telemetry active"
                self.telemetry_runtime_status={**result,"game_id":context.get("game_id") if context else None,"method":context.get("method") if context else None}
                return result
            except Exception as exc:
                result["parser_status"]=f"Parser error: {type(exc).__name__}"
                continue
        if candidates:
            result["file_exists"]=True
            if result["parser_status"]=="No telemetry file found":result["parser_status"]="Telemetry file found but no valid FPS samples"; result["telemetry_state"]="Telemetry file found — waiting for samples"
        elif context and context.get("instrumented") and not shutil.which("mangohud"):
            result["telemetry_state"]="Telemetry unavailable"; result["parser_status"]="MangoHud executable not available"
        elif context and context.get("instrumented"):
            result["telemetry_state"]="MangoHud process active but CSV unavailable" if mango_process_active else "Game detected — waiting for telemetry"
        self.telemetry_runtime_status={**result,"game_id":context.get("game_id") if context else None,"method":context.get("method") if context else None}
        return result

    def _game_session_rule_identity(self, hit):
        if not hit:
            return None
        idx,rule=hit
        return (
            str(rule.get("steam_appid") or rule.get("alcc_game_id") or "").strip(),
            str(rule.get("steam_title") or rule.get("title") or rule.get("match") or "Game").strip(),
            idx
        )




















    def _create_optimization_trial(self,game,goal,baseline_sessions,baseline_configuration,candidate_configuration,tested_variable,baseline_source="selected historical session"):
        game=dict(game or {}); game_id=str(game.get("game_id") or stable_game_id(game.get("provider"),game.get("provider_id"),game.get("launch_command")))
        validation=self._trial_candidate_validation(baseline_configuration,candidate_configuration,tested_variable)
        if not validation["valid"]:raise ValueError(validation["warning"])
        sessions=self.game_session_history.get("sessions",[]) if isinstance(self.game_session_history,dict) else []
        indexes=[]; expected_baseline=self._trial_configuration(baseline_configuration)
        for index in baseline_sessions or []:
            if not isinstance(index,int) or not 0<=index<len(sessions):continue
            rec=sessions[index]
            if self._game_session_quality(rec)!="Gameplay" or self._optimization_game_identity(rec)!=self._optimization_game_identity({"steam_appid":game.get("steam_appid"),"game":game.get("display_name")}):continue
            actual=self._trial_configuration(rec); mismatch=[key for key,value in expected_baseline.items() if value!="Unknown" and actual.get(key)!=value]
            if mismatch:raise ValueError("Baseline sessions contain incompatible configurations: "+", ".join(mismatch))
            indexes.append(index)
        if baseline_source!="current configuration" and not indexes:raise ValueError("No comparable Gameplay baseline sessions were selected")
        trial_id=f"trial-{int(time.time()*1000)}-{hashlib.sha1(game_id.encode()).hexdigest()[:6]}"
        trial={"format_version":OPTIMIZATION_TRIAL_FORMAT_VERSION,"association_policy_version":2,"trial_id":trial_id,"game_id":game_id,"game_name":game.get("display_name") or "Game","provider":game.get("provider") or "other","provider_id":str(game.get("provider_id") or ""),"steam_appid":str(game.get("steam_appid") or ""),"goal":goal,"tested_variable":tested_variable,"baseline_source":baseline_source,"baseline_configuration":self._trial_configuration(baseline_configuration),"baseline_fingerprint":self._trial_fingerprint(baseline_configuration),"baseline_session_indexes":indexes,"candidate_configuration":self._trial_configuration(candidate_configuration),"candidate_fingerprint":self._trial_fingerprint(candidate_configuration),"candidate_session_indexes":[],"rejected_sessions":[],"created_at":time.time(),"status":"Planned","application_error":""}
        self.optimization_trials.setdefault("trials",[]).append(trial); self.optimization_trials["trials"]=self.optimization_trials["trials"][-50:]; self.optimization_trials["active_trial_id"]=trial_id; save_optimization_trials_file(self.optimization_trials); return trial

    def _active_optimization_trial(self):
        active=self.optimization_trials.get("active_trial_id") if isinstance(self.optimization_trials,dict) else None
        return next((row for row in self.optimization_trials.get("trials",[]) if row.get("trial_id")==active),None) if active else None




    def _arm_optimization_trial_run(self,trial,target=None):
        if not trial:return {"armed":False,"reason":"No active trial"}
        if trial.get("status") in ("Cancelled",):
            return {"armed":False,"reason":f"A {str(trial.get('status')).lower()} trial cannot capture another run"}
        if target not in (None,"baseline","candidate"):raise ValueError("invalid trial run target")
        if target is None:target="candidate" if trial.get("status") in ("Candidate Applied","Waiting for Candidate Run","Ready to Compare","More Evidence Needed","Completed") or trial.get("candidate_session_indexes") else "baseline"
        trial["waiting_for"]=target
        trial["status"]="Waiting for Baseline Run" if target=="baseline" else "Waiting for Candidate Run"
        value=self._trial_configuration(trial.get(f"{target}_configuration")).get(trial.get("tested_variable"),"Unknown")
        trial["run_instruction"]=f"Waiting for {target} run — {value} — launch {trial.get('game_name') or 'the selected game'} normally."
        save_optimization_trials_file(self.optimization_trials)
        return {"armed":True,"target":target,"instruction":trial["run_instruction"]}






    def _associate_session_with_active_trial(self,history_index,rec):
        trial=self._active_optimization_trial()
        if not trial:return {"accepted":False,"reason":"No active trial"}
        target=trial.get("waiting_for")
        if target not in ("baseline","candidate"):return {"accepted":False,"reason":"Trial is not waiting for a run"}
        reason=None
        if not self._trial_game_matches_session(trial,rec):reason="Wrong game identity"
        elif self._game_session_quality(rec)!="Gameplay":reason=f"Session quality is {self._game_session_quality(rec)}, not Gameplay"
        else:
            matches,mismatches=self._trial_session_matches_configuration(trial.get(f"{target}_configuration"),rec,trial.get("tested_variable"))
            if not matches:reason=f"Session configuration does not match the {target} fingerprint: "+", ".join(mismatches)
        if not reason and self._session_num(rec.get("gameplay_avg_fps")) is None and trial.get("goal") not in ("Lower power","Lower junction temperature"):reason="Requested goal requires FPS telemetry"
        indexes=trial.setdefault(f"{target}_session_indexes",[])
        if not reason and history_index in indexes:reason=f"Session is already associated as a {target} run"
        if reason:
            now=time.time(); rejection={"history_index":history_index,"target":target,"reason":reason,"time":now}
            if 'mismatches' in locals() and mismatches:
                expected=self._trial_configuration(trial.get(f"{target}_configuration")); actual=self._trial_configuration(rec); rejection["mismatches"]={key:{"expected":expected.get(key),"actual":actual.get(key)} for key in mismatches}
            trial.setdefault("rejected_sessions",[]).append(rejection); trial["rejected_sessions"]=trial["rejected_sessions"][-20:]; trial["last_rejection"]=rejection; save_optimization_trials_file(self.optimization_trials); return {"accepted":False,"reason":reason}
        indexes.append(history_index); trial["waiting_for"]=None; trial["run_instruction"]=""
        value=self._trial_configuration(trial.get(f"{target}_configuration")).get(trial.get("tested_variable"),"Unknown"); count=len(indexes)
        trial["last_capture"]={"side":target,"configuration":value,"history_index":history_index,"captured_at":time.time(),"message":f"{target.title()} run captured successfully"}; trial["last_rejection"]=None
        trial["status"]="Ready to Compare" if trial.get("baseline_session_indexes") and trial.get("candidate_session_indexes") else "Session Captured"
        save_optimization_trials_file(self.optimization_trials); return {"accepted":True,"target":target,"reason":f"Gameplay session matches game and {target} fingerprint"}

    def _upgrade_active_trial_association_policy(self,trial):
        if not trial or int(trial.get("association_policy_version") or 1)>=2:return None
        trial["association_policy_version"]=2; result=None
        rejected=trial.get("rejected_sessions") or []
        if trial.get("waiting_for") in ("baseline","candidate") and rejected:
            index=rejected[-1].get("history_index"); sessions=self.game_session_history.get("sessions",[])
            if isinstance(index,int) and 0<=index<len(sessions):result=self._associate_session_with_active_trial(index,sessions[index])
        save_optimization_trials_file(self.optimization_trials); return result





    def _apply_trial_stopping_rule(self,trial,result):
        if trial.get("final_choice"):return {"stop":True,"outcome":trial.get("trial_outcome") or "INCONCLUSIVE","reason":trial.get("stopping_reason") or "Trial already finished by explicit user choice."}
        decision=self._trial_stopping_decision(trial,result)
        if not decision["stop"]:return decision
        changed=not trial.get("trial_complete") or trial.get("trial_outcome")!=decision.get("outcome") or trial.get("stopping_reason")!=decision.get("reason")
        trial["trial_complete"]=True; trial["trial_outcome"]=decision.get("outcome") or "INCONCLUSIVE"; trial["stopping_reason"]=decision["reason"]; trial["status"]="Trial Complete — Inconclusive" if trial["trial_outcome"]=="INCONCLUSIVE" else "Trial Complete — "+str(trial["trial_outcome"]).title(); trial["waiting_for"]=None; trial["run_instruction"]=""; trial.setdefault("completed_at",time.time())
        if changed:save_optimization_trials_file(self.optimization_trials)
        return decision

    def _continue_optimization_trial(self,trial):
        if trial.get("final_choice"):return {"continued":False,"reason":"A trial with a final user choice is archived and cannot resume."}
        trial["evidence_budget_override"]=True; trial["trial_complete"]=False; trial["status"]="More Evidence Needed"; trial["waiting_for"]=None; trial["run_instruction"]=""; trial["continued_at"]=time.time(); save_optimization_trials_file(self.optimization_trials); return {"continued":True}

    def _complete_optimization_trial_choice(self,trial,choice,apply_callback=None):
        if choice not in ("baseline","candidate","no_change"):raise ValueError("invalid final trial choice")
        if choice!="no_change":
            configuration=trial[f"{choice}_configuration"]
            try:
                ok=apply_callback(configuration,trial["tested_variable"]) if apply_callback else self._apply_trial_change(trial,configuration)
                if ok is False:raise RuntimeError("existing configuration mechanism reported failure")
            except Exception as exc:return {"completed":False,"error":str(exc)}
        value="Configuration unchanged" if choice=="no_change" else self._trial_configuration(trial[f"{choice}_configuration"]).get(trial.get("tested_variable"),"Unknown")
        trial["final_choice"]={"choice":choice,"configuration":value,"chosen_at":time.time()}; trial["status"]="Trial Complete — Finished Without Changing" if choice=="no_change" else f"Trial Complete — Kept {choice.title()}"; trial["trial_complete"]=True; trial["waiting_for"]=None; trial["run_instruction"]=""; save_optimization_trials_file(self.optimization_trials); return {"completed":True,"choice":choice,"configuration":value}







    def _cancel_optimization_trial(self,trial):
        trial["status"]="Cancelled"; trial["waiting_for"]=None; trial["run_instruction"]=""; self.optimization_trials["active_trial_id"]=None; save_optimization_trials_file(self.optimization_trials)

    def _rebase_optimization_trial_indexes(self,dropped):
        if dropped<=0:return
        for trial in self.optimization_trials.get("trials",[]):
            for key in ("baseline_session_indexes","candidate_session_indexes"):
                trial[key]=[index-dropped for index in trial.get(key,[]) if isinstance(index,int) and index>=dropped]

    def _apply_optimization_trial_target(self,trial,target,apply_callback=None):
        if target not in ("candidate","baseline"):raise ValueError("invalid trial target")
        config=trial[f"{target}_configuration"]
        try:
            ok=apply_callback(config,trial["tested_variable"]) if apply_callback else self._apply_trial_change(trial,config)
            if ok is False:raise RuntimeError("existing configuration mechanism reported failure")
        except Exception as exc:
            trial["application_error"]=str(exc); save_optimization_trials_file(self.optimization_trials); return {"applied":False,"error":str(exc)}
        trial["application_error"]=""; trial["status"]="Candidate Applied" if target=="candidate" else "Baseline Applied"; trial["waiting_for"]=target
        value=self._trial_configuration(trial.get(f"{target}_configuration")).get(trial.get("tested_variable"),"Unknown")
        trial["run_instruction"]=f"Waiting for {target} run — {value} — launch {trial.get('game_name') or 'the selected game'} normally."
        save_optimization_trials_file(self.optimization_trials); return {"applied":True,"target":target}

