                original=pathlib.Path(cfg["path"]).read_text(encoding="utf-8",errors="strict"); self._validate_steam_localconfig_text(original); patched=self._patch_steam_launch_options_text(original,appid,generated); backup=self._steam_backup_localconfig(cfg,appid); self._atomic_replace_text(cfg["path"],patched)
