        if not trial:messagebox.showinfo("Optimization Trial","No active trial is available."); return
        if trial.get("trial_complete"):messagebox.showinfo("Optimization Trial","This trial has stopped. Choose Continue Testing explicitly before collecting another run."); return
        target=self._trial_recommended_run_target(trial); game={"game_id":trial.get("game_id"),"provider":trial.get("provider"),"provider_id":trial.get("provider_id"),"steam_appid":trial.get("steam_appid"),"display_name":trial.get("game_name")}; current=self._trial_current_configuration(game); matches,expected,actual=self._trial_target_configuration_matches(trial,target,current)
