        if not messagebox.askyesno("Finish Optimization Trial",f"Final choice: {value}\n\n{('No GPU or scaling setting will be changed.' if choice=='no_change' else 'The existing safe application and readback path will apply this configuration.')}\n\nContinue?"):return
        result=self._complete_optimization_trial_choice(trial,choice); self._refresh_optimization_trials_ui()
