        recommendation=self._derive_game_recommendation(game,self.recommendation_goal_var.get() or "Balanced"); self.current_recommendation=recommendation; current=recommendation["current_configuration"]; wanted=recommendation.get("recommended_configuration"); changes=self._recommendation_changes(current,wanted) if wanted else []
