        index=self._optimization_selected_history_index()
        if index is None:return
        sessions=self.game_session_history.get("sessions",[]); rec=sessions[index]
        self.trend_game_var.set(str(rec.get("game") or "Game")); self.trend_mode_var.set("All sessions for game"); self.trend_selected_index=index
        self.nb.select(self.tabs["Analysis"]); self.analysis_nb.select(self.game_trends_page); self._refresh_session_trends(); self._select_trend_session(index)

