    @staticmethod
    def _trend_timestamp(rec,fallback=0):
        return trends_timestamp(rec,fallback)

    @staticmethod
    def _trend_game_matches(rec,reference):
        return trends_game_matches(rec,reference)

    @staticmethod
    def _trend_point(index,rec):
        return trends_point(index,rec)

    @staticmethod
    def _trend_sessions(sessions,reference_index=None,comparable_only=False):
        return trends_sessions(sessions,reference_index,comparable_only)

    def _layout_trend_cards(self,event=None):
        width=event.width if event is not None else self.trend_metric_cards.winfo_width(); columns=4 if width>=900 else 2
        if columns==self.trend_card_columns:return
        for card in self.trend_card_widgets:card.grid_forget()
        for column in range(4):self.trend_metric_cards.grid_columnconfigure(column,weight=1 if column<columns else 0,uniform="trendcards" if column<columns else "")
        for i,card in enumerate(self.trend_card_widgets):card.grid(row=i//columns,column=i%columns,sticky="nsew",padx=(0,5) if i%columns<columns-1 else 0,pady=(0,5))
        self.trend_card_columns=columns

    @staticmethod
    def _trend_responsive_columns(width,kind):
        width=int(width or 0)
        if kind=="baseline":return 6 if width>=1120 else 3 if width>=680 else 2
        return 4 if width>=980 else 2

    @staticmethod
    def _layout_cell_grid(frame,cells,columns,uniform):
        for cell in cells:cell.grid_forget()
        for column in range(max(6,columns)):frame.grid_columnconfigure(column,weight=1 if column<columns else 0,uniform=uniform if column<columns else "")
        for i,cell in enumerate(cells):cell.grid(row=i//columns,column=i%columns,sticky="nsew",padx=(0,4) if i%columns<columns-1 else 0,pady=(0,4))

    def _layout_trend_inspector(self,event=None):
        width=event.width if event is not None else self.trend_inspector_grid.winfo_width(); columns=self._trend_responsive_columns(width,"inspector")
        if columns!=self.trend_inspector_columns:self._layout_cell_grid(self.trend_inspector_grid,self.trend_inspector_cells,columns,"inspectorcells"); self.trend_inspector_columns=columns

    def _layout_trend_baseline(self,event=None):
        width=event.width if event is not None else self.trend_baseline_grid.winfo_width(); columns=self._trend_responsive_columns(width,"baseline")
        if columns!=self.trend_baseline_columns:self._layout_cell_grid(self.trend_baseline_grid,self.trend_baseline_cells,columns,"baselinecells"); self.trend_baseline_columns=columns

    @staticmethod
    def _trend_neighbor_index(points,current,step):
        return trends_neighbor_index(points,current,step)

    @staticmethod
    def _trend_baseline(points,selected_index):
        return trends_baseline(points,selected_index)

    @staticmethod
    def _trend_change_text(point,baseline):
        return trends_change_text(point,baseline)

    @staticmethod
    def _trend_baseline_cell_data(point,baseline):
        return trends_baseline_cell_data(point,baseline)

    def _trend_graph_list(self):
        return [self.__dict__[name] for name in ("trend_fps_graph","trend_consistency_graph","trend_temp_graph","trend_power_graph","trend_util_graph","trend_efficiency_graph") if name in self.__dict__]

    def _refresh_session_trends(self):
        if "trend_game_combo" not in self.__dict__:return
        sessions=self.game_session_history.get("sessions",[]) if isinstance(self.game_session_history,dict) else []
        games=sorted({str(r.get("game") or "Game") for r in sessions if isinstance(r,dict)})
        self.trend_game_combo.configure(values=["All games"]+games)
        if self.trend_game_var.get() not in ["All games"]+games:
            self.trend_game_var.set(str(sessions[-1].get("game") or "Game") if sessions else "All games")
        game=self.trend_game_var.get(); candidates=[i for i,r in enumerate(sessions) if isinstance(r,dict) and (game=="All games" or str(r.get("game") or "Game")==game)]
        comparable=self.trend_mode_var.get()=="Comparable sessions only"
        gameplay_candidates=[i for i in candidates if self._game_session_quality(sessions[i])=="Gameplay"]
        reference=(gameplay_candidates[-1] if gameplay_candidates else candidates[-1]) if candidates else None
        if game=="All games" and reference is not None:
            self.trend_game_var.set(str(sessions[reference].get("game") or "Game")); game=self.trend_game_var.get()
            candidates=[i for i,r in enumerate(sessions) if isinstance(r,dict) and str(r.get("game") or "Game")==game]
            gameplay_candidates=[i for i in candidates if self._game_session_quality(sessions[i])=="Gameplay"]
            reference=(gameplay_candidates[-1] if gameplay_candidates else candidates[-1]) if candidates else None
        points,reasons=self._trend_sessions(sessions,reference,comparable); self.trend_points=points
        point_indexes={p["history_index"] for p in points}
        if self.trend_selected_index not in point_indexes:self.trend_selected_index=points[-1]["history_index"] if points else None
        excluded=sum(reasons.values()); explanation=", ".join(f"{count} {reason}" for reason,count in reasons.items() if count)
        setups={self._game_session_setup_key(p["record"]) for p in points}; mixed_warning=(not comparable and len(setups)>1)
        status=f"{len(points)} shown • {excluded} excluded"+(f" ({explanation})" if explanation else "")
        if mixed_warning:status+=f" • Warning: includes {len(setups)} configurations; not directly comparable"
        self.trend_filter_status.configure(text=status,fg=YELLOW if excluded or mixed_warning else MUTED)
        self._update_trend_summary_cards(points,allow_baseline=comparable)
        for graph in self._trend_graph_list():graph.set_data(points,self.trend_selected_index)
        self._update_trend_inspector(comparable)
        labels=[]; indexes=[]
        for p in points:
            if p["history_index"]==self.trend_selected_index:continue
            labels.append(f"{p['record'].get('ended_iso','—')} • {p['record'].get('game','Game')}"); indexes.append(p["history_index"])
        self.trend_compare_indexes=indexes; self.trend_compare_combo.configure(values=labels or ["No other compatible session"]); self.trend_compare_combo.current(0)

    def _update_trend_summary_cards(self,points,allow_baseline=True):
        def values(key):return [p[key] for p in points if p.get(key) is not None]
        def mean(key):
            vals=values(key); return sum(vals)/len(vals) if vals else None
        values_by_key={"sessions":str(len(points)),"avg_fps":self._format_session_metric(mean("gameplay_avg")," FPS"),"avg_p1":self._format_session_metric(mean("gameplay_p1")," FPS"),"avg_consistency":self._format_session_metric(mean("consistency_pct"),"%"),"avg_junction":self._format_session_metric(mean("avg_junction"),"°C"),"avg_power":self._format_session_metric(mean("avg_power")," W"),"avg_load":self._format_session_metric(mean("avg_gpu_load"),"%"),"avg_efficiency":self._format_session_metric(mean("fps_per_watt")," FPS/W")}
        for key,label in self.trend_card_values.items():label.configure(text=values_by_key.get(key,"Unavailable"))
        fps=values("gameplay_avg"); dates=[p["record"].get("ended_iso") or p["record"].get("started_iso") for p in points if p["record"].get("ended_iso") or p["record"].get("started_iso")]
        span=f"{dates[0]} → {dates[-1]}" if dates else "Unavailable"; baseline="Recent baseline: insufficient comparable sessions"
        if allow_baseline and len(fps)>=4:
            prior=fps[-4:-1]; baseline=f"Recent baseline: newest session {fps[-1]-sum(prior)/len(prior):+.1f} FPS versus prior 3-session mean"
        elif not allow_baseline:baseline="Recent baseline: suppressed while incompatible configurations are included"
        best=self._format_session_metric(max(fps)," FPS") if fps else "Unavailable"; worst=self._format_session_metric(min(fps)," FPS") if fps else "Unavailable"
        self.trend_summary_context.configure(text=f"Time span: {span}    Best/Worst Gameplay FPS: {best} / {worst}\n{baseline}    •    Comparable/exclusion information is shown above.")

    def _update_trend_inspector(self,comparable=None):
        point=next((p for p in self.trend_points if p["history_index"]==self.trend_selected_index),None)
        if point is None:
            self.trend_selection_label.configure(text="No filtered session is available."); self.trend_change_label.configure(text="Comparable baseline unavailable.")
            for label in self.__dict__.get("trend_inspector_values",{}).values():label.configure(text="Unavailable")
            for value,change in self.__dict__.get("trend_baseline_values",{}).values():value.configure(text="Unavailable"); change.configure(text="Baseline unavailable")
            for button in (self.trend_prev_button,self.trend_next_button,self.trend_replay_button,self.trend_previous_compare_button,self.trend_baseline_compare_button):button.configure(state="disabled")
            return
        rec=point["record"]; advisor=self._performance_advisor(rec); ratio=self._format_session_metric(point.get("consistency_pct"),"%")
        self.trend_selection_label.configure(text=f"{rec.get('ended_iso') or rec.get('started_iso') or 'Unavailable'}    Duration {self._format_session_duration(rec.get('duration_seconds'))}")
        grouped={"performance":f"Gameplay average  {self._format_session_metric(point.get('gameplay_avg'),' FPS')}\nGameplay P1       {self._format_session_metric(point.get('gameplay_p1'),' FPS')}\nP1 / average      {ratio}\n{rec.get('frame_dip_rating') or 'Frame consistency unavailable'}",
                 "gpu":f"Average load       {self._format_session_metric(point.get('avg_gpu_load'),'%')}\nJunction avg/max  {self._format_session_metric(point.get('avg_junction'),'°C')} / {self._format_session_metric(point.get('max_junction'),'°C')}\nBoard power       {self._format_session_metric(point.get('avg_power'),' W')}\nComparative FPS/W {self._format_session_metric(point.get('fps_per_watt'),' FPS/W')}",
                 "configuration":f"GPU profile\n{rec.get('gpu_profile') or 'Unavailable'}\nScaling\n{rec.get('scaling') or 'Unavailable'}",
                 "advisor":f"Primary limiter\n{advisor['primary_limiter']}"}
        for key,label in self.__dict__.get("trend_inspector_values",{}).items():label.configure(text=grouped[key])
        if comparable is None:comparable=self.trend_mode_var.get()=="Comparable sessions only"
        baseline=self._trend_baseline(self.trend_points,self.trend_selected_index) if comparable else None
        self.trend_current_baseline=baseline
        if comparable:self.trend_change_label.configure(text=f"SELECTED VS {baseline['sessions']}-SESSION COMPARABLE BASELINE" if baseline else "COMPARABLE BASELINE UNAVAILABLE • at least two other sessions are required")
        else:self.trend_change_label.configure(text="BASELINE SUPPRESSED • All sessions mode may include incompatible configurations")
        cells=self._trend_baseline_cell_data(point,baseline if comparable else None)
        for key,(value_label,change_label) in self.__dict__.get("trend_baseline_values",{}).items():value,change=cells[key]; value_label.configure(text=value); change_label.configure(text=change)
        previous=self._trend_neighbor_index(self.trend_points,self.trend_selected_index,-1); next_index=self._trend_neighbor_index(self.trend_points,self.trend_selected_index,1)
        self.trend_prev_button.configure(state="normal" if previous is not None else "disabled"); self.trend_next_button.configure(state="normal" if next_index is not None else "disabled")
        self.trend_replay_button.configure(state="normal" if self._stored_raw_telemetry(rec) else "disabled")
        self.trend_previous_compare_button.configure(state="normal" if previous is not None else "disabled")
        representative=baseline.get("representative_history_index") if baseline else None; self.trend_baseline_compare_button.configure(state="normal" if representative is not None else "disabled")

    @staticmethod
    def _trend_summary_text(points,allow_baseline=True):
        return trends_summary_text(points,allow_baseline)

    def _select_trend_session(self,index):
        if index is None:return
        self.trend_selected_index=index; point=next((p for p in self.trend_points if p["history_index"]==index),None)
        if point is None:return
        for graph in self._trend_graph_list():graph.set_data(self.trend_points,index)
        self._update_trend_inspector()
        labels=[]; indexes=[]
        for p in self.trend_points:
            if p["history_index"]==index:continue
            labels.append(f"{p['record'].get('ended_iso','—')} • {p['record'].get('game','Game')}"); indexes.append(p["history_index"])
        self.trend_compare_indexes=indexes; self.trend_compare_combo.configure(values=labels or ["No other compatible session"]); self.trend_compare_combo.current(0)

    def _trend_navigate(self,step):
        target=self._trend_neighbor_index(self.trend_points,self.trend_selected_index,step)
        if target is not None:self._select_trend_session(target)

    @staticmethod
    def _trend_comparison_pair(points,selected_index,mode):
        return trends_comparison_pair(points,selected_index,mode)

    def _show_trend_comparison(self,pair,label=None):
        if not pair:return
        text=self._game_session_comparison_text(pair[0]["record"],pair[1]["record"])
        if label:text=f"{label}\n\n{text}"
        self.nb.select(self.tabs["Analysis"]); self.analysis_nb.select(self.game_history_page); self.game_session_detail_record=None; self.game_session_comparison_text=text; self.game_session_detail_view.set_text(text)

    def _trend_compare_previous(self):self._show_trend_comparison(self._trend_comparison_pair(self.trend_points,self.trend_selected_index,"previous"),"QUICK COMPARISON • selected vs previous filtered session")

    def _trend_compare_baseline(self):
        pair=self._trend_comparison_pair(self.trend_points,self.trend_selected_index,"baseline")
        if pair:
            baseline=self.trend_current_baseline or {}; representative=baseline.get("representative_history_index")
            representative_point=next((p for p in self.trend_points if p["history_index"]==representative),None); identity=representative_point["record"].get("ended_iso") if representative_point else f"history record {representative}"
            self._show_trend_comparison(pair,f"QUICK COMPARISON • selected vs representative actual baseline session {identity} (closest to {baseline.get('sessions',0)}-session mean)")

    def _trend_open_details(self):
        if self.trend_selected_index is None:return
        self.nb.select(self.tabs["Analysis"]); self.analysis_nb.select(self.game_history_page); self.game_session_filter_game.set("All games"); self.game_session_filter_quality.set("All sessions"); self.game_session_same_setup_var.set(False); self._refresh_game_session_history_ui()
        if self.game_session_tree.exists(str(self.trend_selected_index)):self.game_session_tree.selection_set(str(self.trend_selected_index)); self.game_session_tree.see(str(self.trend_selected_index)); self._show_game_session_details_by_iid(str(self.trend_selected_index))

    def _trend_replay(self):
        if self.trend_selected_index is None:return
        self._refresh_analysis_lab_sessions()
        try:pos=self.analysis_lab_session_indexes.index(self.trend_selected_index)
        except ValueError:return
        self.analysis_lab_session_combo.current(pos); self._analysis_lab_selection_changed(); self.nb.select(self.tabs["Analysis"]); self.analysis_nb.select(self.analysis_lab_page); self._replay_analysis_lab_session()

    def _trend_compare(self):
        if self.trend_selected_index is None:return
        pos=self.trend_compare_combo.current()
        if pos<0 or pos>=len(self.trend_compare_indexes):return
        other=self.trend_compare_indexes[pos]; sessions=self.game_session_history.get("sessions",[])
        try:
            pair=[sessions[other],sessions[self.trend_selected_index]]; pair.sort(key=lambda rec:self._trend_timestamp(rec))
            text=self._game_session_comparison_text(pair[0],pair[1])
        except Exception:return
        self.nb.select(self.tabs["Analysis"]); self.analysis_nb.select(self.game_history_page); self.game_session_detail_record=None; self.game_session_comparison_text=text; self.game_session_detail_view.set_text(text)

    def _build_analysis_lab(self, page):
        """Build the deliberately separate, scrollable offline-analysis workspace."""
        canvas=tk.Canvas(page,bg=BG,highlightthickness=0,borderwidth=0)
        scroll=ttk.Scrollbar(page,orient="vertical",command=canvas.yview)
        canvas.configure(yscrollcommand=scroll.set)
        scroll.pack(side="right",fill="y")
        canvas.pack(side="left",fill="both",expand=True)
        inner=tk.Frame(canvas,bg=BG)
        window=canvas.create_window((0,0),window=inner,anchor="nw")
        inner.bind("<Configure>",lambda e:canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>",lambda e:canvas.itemconfigure(window,width=e.width))

        panel,body=self._panel(inner,"Analysis Lab / Offline Session Replay")
        panel.pack(fill="both",expand=True,padx=10,pady=10)
        tk.Label(body,text=(
            "Develop and verify frame analysis without launching a game. Self-tests, live sessions, and replay all use the same analyzer. "
            "Replay is read-only unless Update Historical Record is explicitly selected."
        ),bg=PANEL,fg=MUTED,justify="left",wraplength=1050).pack(fill="x",pady=(0,8))

        controls=tk.Frame(body,bg=PANEL); controls.pack(fill="x",pady=(0,7))
        ttk.Button(controls,text="Run Analysis Self-Test",command=self._run_analysis_self_test_ui).pack(side="left")
        ttk.Button(controls,text="Refresh Sessions",command=self._refresh_analysis_lab_sessions).pack(side="left",padx=6)
        ttk.Button(controls,text="Copy Analysis",command=self._copy_analysis_lab_output).pack(side="left")
        self.analysis_lab_status=tk.Label(controls,text=f"Current analyzer {ANALYZER_VERSION} • schema {SESSION_SCHEMA_VERSION}",bg=PANEL,fg=MUTED)
        self.analysis_lab_status.pack(side="left",padx=8)

        replay=tk.Frame(body,bg="#0b1119",highlightthickness=1,highlightbackground=BORDER)
        replay.pack(fill="x",pady=(0,8),ipadx=8,ipady=8)
        selector_row=tk.Frame(replay,bg="#0b1119"); selector_row.pack(fill="x",padx=8,pady=(5,3))
        selector_row.grid_columnconfigure(1,weight=1)
        tk.Label(selector_row,text="Saved session:",bg="#0b1119",fg=FG).grid(row=0,column=0,sticky="w")
        self.analysis_lab_session_var=tk.StringVar(value="No saved sessions")
        self.analysis_lab_session_combo=ttk.Combobox(selector_row,textvariable=self.analysis_lab_session_var,state="readonly",width=56)
        self.analysis_lab_session_combo.grid(row=0,column=1,sticky="ew",padx=7)
        self.analysis_lab_session_combo.bind("<<ComboboxSelected>>",self._analysis_lab_selection_changed)
        self.analysis_lab_replay_status=tk.Label(selector_row,text="Replay: Unavailable — no saved session selected",bg="#0b1119",fg=MUTED,font=("Sans",9,"bold"),anchor="w")
        self.analysis_lab_replay_status.grid(row=1,column=1,sticky="ew",padx=7,pady=(3,0))

        action_row=tk.Frame(replay,bg="#0b1119"); action_row.pack(fill="x",padx=8,pady=(3,5))
        self.analysis_lab_action_row=action_row
        self.analysis_lab_replay_button=ttk.Button(action_row,text="Replay with Current Analyzer",command=self._replay_analysis_lab_session)
        self.analysis_lab_replay_button.pack(side="left",padx=(0,6))
        self.analysis_lab_export_button=ttk.Button(action_row,text="Export Diagnostic JSON",command=self._export_analysis_lab_session)
        self.analysis_lab_export_button.pack(side="left",padx=(0,6))
        self.analysis_lab_update_button=ttk.Button(action_row,text="Update Historical Record",command=self._update_analysis_lab_session)
        self.analysis_lab_update_button.pack(side="left")
        self.analysis_lab_action_layout="wide"
        action_row.bind("<Configure>",self._analysis_lab_layout_actions)

        self._build_telemetry_simulator(body)

        out_frame=tk.Frame(body,bg="#0b1119")
        out_frame.pack(fill="both",expand=True)
        self.analysis_lab_output=tk.Text(out_frame,height=27,wrap="word",bg="#070a0f",fg=FG,insertbackground=FG,relief="flat",font=("Monospace",9),padx=8,pady=7)
        out_scroll=ttk.Scrollbar(out_frame,orient="vertical",command=self.analysis_lab_output.yview)
        self.analysis_lab_output.configure(yscrollcommand=out_scroll.set)
        self.analysis_lab_output.pack(side="left",fill="both",expand=True)
        out_scroll.pack(side="right",fill="y")
        initial_report="Run the deterministic self-test, run a simulation, or select a replay-compatible session."
        self.analysis_lab_output.insert("1.0",initial_report)
        self.analysis_lab_text_view=ReadOnlyTextView(self.analysis_lab_output,self,initial_report)
        self.analysis_lab_session_indexes=[]
        self.after(80,self._refresh_analysis_lab_sessions)

    def _build_telemetry_simulator(self,parent):
        sim=tk.Frame(parent,bg="#0b1119",highlightthickness=1,highlightbackground=BORDER)
        sim.pack(fill="x",pady=(0,8),ipadx=8,ipady=8)
        head=tk.Frame(sim,bg="#0b1119"); head.pack(fill="x",padx=8,pady=(6,4))
        tk.Label(head,text="TELEMETRY SIMULATOR",bg="#0b1119",fg=BLUE2,font=("Sans",9,"bold")).pack(side="left")
        tk.Label(head,text=f"Deterministic • maximum {int(MAX_SIMULATION_DURATION_SECONDS/3600)}h / {MAX_SIMULATION_SAMPLES:,} samples",bg="#0b1119",fg=MUTED).pack(side="right")
        preset_row=tk.Frame(sim,bg="#0b1119"); preset_row.pack(fill="x",padx=8,pady=(0,5))
        tk.Label(preset_row,text="Preset:",bg="#0b1119",fg=FG).pack(side="left")
        self.analysis_sim_preset=tk.StringVar(value="Smooth 90 FPS")
        preset=ttk.Combobox(preset_row,textvariable=self.analysis_sim_preset,state="readonly",width=31,values=tuple(self._telemetry_simulator_presets()))
        preset.pack(side="left",padx=6)
        preset.bind("<<ComboboxSelected>>",lambda e:self._apply_telemetry_simulator_preset())
        ttk.Button(preset_row,text="Apply Preset",command=self._apply_telemetry_simulator_preset).pack(side="left")
        ttk.Button(preset_row,text="Run Simulation",command=self._run_telemetry_simulation_ui).pack(side="right")

        grid=tk.Frame(sim,bg="#0b1119"); grid.pack(fill="x",padx=8,pady=(0,6))
        for col in range(4):grid.grid_columnconfigure(col,weight=1,uniform="simcols")
        self.analysis_sim_grid=grid; self.analysis_sim_group_boxes=[]; self.analysis_sim_grid_columns=4
        self.analysis_sim_vars={}
        groups=(
            ("SESSION / BASELINE",(("duration","Duration (s)"),("interval","Sample interval (s)"),("baseline_fps","Baseline FPS"),("baseline_load","GPU load (%)"),("baseline_power","Board power (W)"),("baseline_clock","GPU clock (MHz)"))),
            ("DIP / HITCH EVENT",(("event_start","Start (s)"),("event_duration","Duration (s)"),("event_fps","FPS"),("event_load","GPU load (%)"),("event_power","Power (W)"),("event_clock","Clock (MHz)"),("repeat_count","Repeat count"),("repeat_interval","Repeat interval (s)"))),
            ("MENU / CAP INTERVAL",(("menu_start","Start (s)"),("menu_duration","Duration (s)"),("menu_fps","Capped FPS"),("menu_load","GPU load (%)"),("menu_power","Power (W)"),("menu_clock","Clock (MHz)"))),
            ("FULL-STALL SAMPLE",(("stall_offset","Offset (s)"),("stall_fps","FPS (0 allowed)"),("stall_load","GPU load (%)"),("stall_power","Power (W)"),("stall_clock","Clock (MHz)"))),
        )
        enabled=(None,"event_enabled","menu_enabled","stall_enabled")
        for col,(title,fields) in enumerate(groups):
            box=tk.Frame(grid,bg=PANEL2,highlightthickness=1,highlightbackground=BORDER)
            box.grid(row=0,column=col,sticky="nsew",padx=(0,5) if col<3 else 0)
            self.analysis_sim_group_boxes.append(box)
            if enabled[col]:
                var=tk.BooleanVar(value=False); self.analysis_sim_vars[enabled[col]]=var
                ttk.Checkbutton(box,text=title,variable=var).grid(row=0,column=0,columnspan=2,sticky="w",padx=6,pady=5)
            else:tk.Label(box,text=title,bg=PANEL2,fg=BLUE2,font=("Sans",8,"bold")).grid(row=0,column=0,columnspan=2,sticky="w",padx=6,pady=5)
            box.grid_columnconfigure(1,weight=1)
            for row,(key,label) in enumerate(fields,start=1):
                tk.Label(box,text=label,bg=PANEL2,fg=MUTED,font=("Sans",8)).grid(row=row,column=0,sticky="w",padx=(6,3),pady=2)
                var=tk.StringVar(); self.analysis_sim_vars[key]=var
                ttk.Entry(box,textvariable=var,width=9).grid(row=row,column=1,sticky="ew",padx=(3,6),pady=2)
        grid.bind("<Configure>",self._layout_telemetry_simulator_groups)
        self._apply_telemetry_simulator_preset()

    def _layout_telemetry_simulator_groups(self,event=None):
        grid=getattr(self,"analysis_sim_grid",None); boxes=getattr(self,"analysis_sim_group_boxes",[])
        if grid is None or not boxes:return
        width=event.width if event is not None else grid.winfo_width()
        columns=1 if width and width<560 else (2 if width and width<900 else 4)
        if columns==getattr(self,"analysis_sim_grid_columns",None):return
        for box in boxes:box.grid_forget()
        for col in range(4):grid.grid_columnconfigure(col,weight=1 if col<columns else 0,uniform="simcols" if col<columns else "",minsize=0)
        for index,box in enumerate(boxes):
            box.grid(row=index//columns,column=index%columns,sticky="nsew",padx=(0,5) if index%columns<columns-1 else 0,pady=(0,5))
        self.analysis_sim_grid_columns=columns

    def _apply_telemetry_simulator_preset(self):
        config=self._telemetry_simulator_presets().get(self.analysis_sim_preset.get())
        if not config:return
        for key,var in self.analysis_sim_vars.items():
            value=config.get(key,False if key.endswith("_enabled") else "")
            var.set(value)

    def _run_telemetry_simulation_ui(self):
        config={key:var.get() for key,var in self.analysis_sim_vars.items()}
        try:
            raw,info=self._generate_simulated_telemetry(config)
            result=self._analyze_raw_session(raw,SIMULATION_STARTED_AT)
        except ValueError as e:
            self._analysis_lab_set_output(f"TELEMETRY SIMULATION\n\nInvalid simulator input: {e}")
            self.analysis_lab_status.configure(text="Simulation input rejected",fg=RED)
            return
        rec={"game":"Telemetry Simulator","analysis_context":"telemetry_simulator","duration_seconds":info["duration"],"avg_fps":result.get("raw_sampled_avg_fps"),
             "avg_gpu_load_pct":sum(r["gpu_load"] for r in raw)/len(raw),"max_gpu_load_pct":max(r["gpu_load"] for r in raw),
             "avg_power_w":sum(r["power_w"] for r in raw)/len(raw),"max_power_w":max(r["power_w"] for r in raw),
             "gpu_profile":"Synthetic / no tuning","graphics_preset":"Simulator","scaling":"Synthetic",**result}
        f=self._format_session_metric
        lines=["TELEMETRY SIMULATION",f"Preset: {self.analysis_sim_preset.get()}",f"Generated samples: {len(raw)} • duration {info['duration']:.2f}s • interval {info['interval']:.3f}s",f"Analyzer version: {result.get('analyzer_version')}","",
               f"Raw FPS: average {f(result.get('raw_sampled_avg_fps'),' FPS')} • P1 {f(result.get('raw_sampled_p1_fps'),' FPS')}",
               f"Gameplay FPS: average {f(result.get('gameplay_avg_fps'),' FPS')} • P1 {f(result.get('gameplay_p1_fps'),' FPS')}",
               f"Likely menu/capped time: {f(result.get('likely_menu_seconds'),'s')} ({result.get('likely_menu_samples',0)} samples)",
               f"Gameplay cap/synchronization: {result.get('frame_cap_status')} • {result.get('frame_cap_confidence')} • plateau {f(result.get('frame_cap_plateau_fps'),' FPS')} • occupancy {f(result.get('frame_cap_occupancy_pct'),'%')}",
               f"Gameplay median: {f(result.get('gameplay_median_fps'),' FPS')}",
               f"Sustained dips: {result.get('frame_dip_events',0)} • GPU-saturated {result.get('gpu_bound_dip_events',0)} • GPU-headroom {result.get('gpu_headroom_dip_events',0)} • mixed {result.get('mixed_dip_events',0)}",
               f"Isolated hitches: {result.get('isolated_hitch_candidates',0)} • GPU-saturated {result.get('isolated_hitch_gpu_saturated',0)} • GPU-headroom {result.get('isolated_hitch_gpu_headroom',0)} • transition {result.get('isolated_hitch_transition',0)} • mixed {result.get('isolated_hitch_mixed',0)}",
               f"Transition/loading events: {result.get('transition_dip_events',0)}",f"Full-stall candidates: {result.get('full_stall_candidates',0)}",f"Frame consistency: {result.get('frame_dip_rating')}","","EVENT TIMESTAMPS"]
        for event in result.get("menu_cap_intervals",[]):lines.append(f"• +{float(event.get('start_offset_seconds') or 0):.2f}s to +{float(event.get('end_offset_seconds') or 0):.2f}s menu/cap — {event.get('samples',0)} samples")
        for event in result.get("dip_event_log",[]):lines.append(f"• {event.get('clock','—')} sustained — {event.get('kind')} — min {f(event.get('min_fps'),' FPS')}")
        for event in result.get("isolated_hitch_log",[]):lines.append(f"• {event.get('clock','—')} isolated — {event.get('kind')} — {f(event.get('fps'),' FPS')}")
        if result.get("full_stall_log"):lines.append("• Full-stall timestamps: "+", ".join(str(event.get("clock","—")) for event in result["full_stall_log"]))
        if not result.get("menu_cap_intervals") and not result.get("dip_event_log") and not result.get("isolated_hitch_log"):lines.append("• No classified events")
        lines += [""]+self._performance_advisor_lines(rec,synthetic=True)
        lines += ["","PERFORMANCE ANALYSIS"]+[f"• {line}" for line in self._game_session_analysis(rec)]
        self._analysis_lab_set_output("\n".join(lines))
        self.analysis_lab_status.configure(text=f"Simulation complete: {len(raw):,} samples",fg=GREEN)

    def _analysis_lab_set_output(self,text):
        view=self.__dict__.get("analysis_lab_text_view")
        if view is not None:return view.set_text(text)
        self.analysis_lab_current_report=str(text); return True

    def _analysis_lab_report_text(self):
        view=self.__dict__.get("analysis_lab_text_view")
        if view is not None:return view.get_text()
        return self.__dict__.get("analysis_lab_current_report","")

    def _copy_analysis_lab_output(self):
        view=self.__dict__.get("analysis_lab_text_view"); text=self._analysis_lab_report_text()
        if not text:return
        if view is not None:view.copy_all()
        else:self.clipboard_clear(); self.clipboard_append(text); self.update_idletasks()
        status=self.__dict__.get("analysis_lab_status")
        if status is not None:status.configure(text=f"Copied complete analysis ({len(text):,} characters)",fg=GREEN)

    def _analysis_lab_select_all(self,event=None):
        view=self.__dict__.get("analysis_lab_text_view")
        return view.select_all(event) if view is not None else "break"

    def _analysis_lab_copy_selection(self,event=None):
        view=self.__dict__.get("analysis_lab_text_view")
        return view.copy_selection(event) if view is not None else "break"

    def _analysis_lab_layout_actions(self,event=None):
        """Stack actions at narrow widths; vertical page scrolling handles height."""
        row=getattr(self,"analysis_lab_action_row",None)
        buttons=[getattr(self,name,None) for name in ("analysis_lab_replay_button","analysis_lab_export_button","analysis_lab_update_button")]
        if row is None or any(button is None for button in buttons):return
        width=(event.width if event is not None else row.winfo_width())
        mode="narrow" if width and width<680 else "wide"
        if mode==getattr(self,"analysis_lab_action_layout",None):return
        for button in buttons:button.pack_forget()
        if mode=="narrow":
            for button in buttons:button.pack(fill="x",pady=(0,4))
        else:
            for i,button in enumerate(buttons):button.pack(side="left",padx=(0,6) if i<2 else 0)
        self.analysis_lab_action_layout=mode

    def _refresh_analysis_lab_sessions(self):
        combo=getattr(self,"analysis_lab_session_combo",None)
        if combo is None:return
        sessions=self.game_session_history.get("sessions",[]) if isinstance(self.game_session_history,dict) else []
        values=[]; indexes=[]
        for i,rec in reversed(list(enumerate(sessions))):
            values.append(f"{rec.get('game','Game')} • {rec.get('ended_iso','—')}")
            indexes.append(i)
        if not values:values=["No saved sessions"]
        self.analysis_lab_session_indexes=indexes
        combo.configure(values=values)
        if combo.current()<0 or combo.current()>=len(values):combo.current(0)
        self._analysis_lab_selection_changed()

    @classmethod
    def _analysis_lab_action_state(cls,rec):
        selected=isinstance(rec,dict)
        replayable=bool(cls._stored_raw_telemetry(rec)) if selected else False
        return {"replay":replayable,"update":replayable,"export":selected,
                "status":"Replay: Available" if replayable else ("Replay: Unavailable — legacy session has no raw telemetry" if selected else "Replay: Unavailable — no saved session selected")}

    def _analysis_lab_selection_changed(self,event=None):
        _,rec=self._analysis_lab_selected()
        state=self._analysis_lab_action_state(rec)
        mapping=(("analysis_lab_replay_button","replay"),("analysis_lab_update_button","update"),("analysis_lab_export_button","export"))
        for attr,key in mapping:
            button=getattr(self,attr,None)
            if button is not None:button.configure(state="normal" if state[key] else "disabled")
        label=getattr(self,"analysis_lab_replay_status",None)
        if label is not None:label.configure(text=state["status"],fg=GREEN if state["replay"] else YELLOW)
        self.analysis_lab_replay=None

    def _analysis_lab_selected(self):
        combo=getattr(self,"analysis_lab_session_combo",None)
        if combo is None:return None,None
        pos=combo.current()
        if pos<0 or pos>=len(getattr(self,"analysis_lab_session_indexes",[])):return None,None
        idx=self.analysis_lab_session_indexes[pos]
        try:return idx,self.game_session_history["sessions"][idx]
        except Exception:return None,None








