    def _live_intelligence_test_results(self):
        tests=[]
        def test(name,fn):
            try:detail=fn(); tests.append({"name":name,"passed":True,"detail":detail})
            except Exception as exc:tests.append({"name":name,"passed":False,"detail":f"{type(exc).__name__}: {exc}"})
        def rows(count=65,fps=90,load=98,start=1000.0,edge=72,junction=88,power=220,clock=2200):
            return [{"t":start+i,"fps":fps,"gpu_load":load,"edge_c":edge,"junction_c":junction,"power_w":power,"gpu_clock_mhz":clock} for i in range(count)]
        def require(condition,detail):
            assert condition,detail; return detail
        analyze=lambda data,active=True,events=None:self._analyze_live_intelligence(data,events or [],active)
        test("sustained GPU-bound workload",lambda:require(analyze(rows())["state"]=="GPU limited","sustained saturation classified conservatively as GPU limited"))
        headroom_variable=[{"t":1000+i,"fps":80+(i*7%31),"gpu_load":62,"edge_c":72,"junction_c":88,"power_w":120,"gpu_clock_mhz":1450} for i in range(65)]
        test("sustained GPU-headroom workload",lambda:require(analyze(headroom_variable)["state"]=="Likely CPU/game-engine limited","variable headroom workload uses no total-CPU inference and is not mistaken for a tight cap"))
        mixed=[{"t":1000+i,"fps":90,"gpu_load":98 if i%2 else 60,"edge_c":72,"junction_c":88,"power_w":170,"gpu_clock_mhz":1800} for i in range(65)]
        test("mixed workload",lambda:require(analyze(mixed)["state"]=="Mixed / uncertain","contradictory load evidence remains mixed"))
        test("loading/transition interruption",lambda:require(analyze([*rows(55),*rows(6,fps=12,load=15,start=1055,power=35,clock=350)])["state"]!="Insufficient evidence","loading-shaped telemetry remains actively analyzed rather than phase-gated"))
        menu_rows=[dict(r,live_phase="menu/background") for r in rows(fps=60,load=20,power=45,clock=500)]
        test("menu/background plateau",lambda:require(analyze(menu_rows)["state"]=="Frame-rate cap / synchronization likely" and analyze(menu_rows)["confidence"]!="High","menu-like phase remains analyzable with reduced confidence instead of phase gating"))
        def hitch(load,expected):
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("game:test"); h.live_intelligence["phase"]="gameplay"
            for r in rows(12):h._live_intelligence_ingest("game:test",r)
            h._live_intelligence_ingest("game:test",rows(1,fps=30,load=load,start=1012)[0])
            for r in rows(4,start=1013):h._live_intelligence_ingest("game:test",r)
            return require(h.live_intelligence["events"][-1]["kind"]==expected,f"{expected} after bounded temporal classification")
        test("isolated GPU-saturated hitch",lambda:hitch(99,"GPU-saturated hitch"))
        test("isolated GPU-headroom hitch",lambda:hitch(60,"GPU-headroom/engine hitch"))
        test("telemetry gap",lambda:require(analyze(rows(20),False)["state"]=="Insufficient evidence","gap suspends conclusions"))
        test("telemetry recovery",lambda:require(analyze(rows(20),True)["state"]=="GPU limited","existing bounded evidence resumes automatically"))
        def reset_identity():
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("game:a"); h._live_intelligence_ingest("game:a",rows(1)[0]); h._live_intelligence_ingest("game:b",rows(1)[0]); return require(h.live_intelligence["identity"]=="game:b" and len(h.live_intelligence["samples"])==1,"identity change resets samples and events")
        test("game identity change",reset_identity)
        def exit_reset():
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("game:a"); h._reset_live_intelligence(); return require(h.live_intelligence["identity"] is None and not h.live_intelligence["samples"],"game exit clears live-only state")
        test("game exit/reset",exit_reset)
        test("insufficient samples",lambda:require(analyze(rows(4))["state"]=="Insufficient evidence","four samples do not establish a workload"))
        test("confidence growth with observation time",lambda:require(analyze(rows(65))["confidence"]=="High" and analyze(rows(14))["confidence"]=="Moderate","confidence grows from duration and valid sample count"))
        test("contradictory evidence reduces confidence",lambda:require(analyze(mixed)["confidence"]!="High","conflicting load evidence prevents high confidence"))
        def no_gap_event():
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("game:a")
            for r in rows(12):h._live_intelligence_ingest("game:a",r)
            h._suspend_live_intelligence("game:a"); return require(not h.live_intelligence["events"],"telemetry gaps never synthesize hitch events")
        test("no false event from telemetry gap",no_gap_event)
        def bounded():
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("game:a")
            for cycle in range(8):
                for r in rows(9,start=1000+cycle*20):h._live_intelligence_ingest("game:a",r)
                h._live_intelligence_ingest("game:a",rows(1,fps=20,load=99,start=1009+cycle*20)[0])
            for r in rows(300,start=2000):h._live_intelligence_ingest("game:a",r)
            return require(len(h.live_intelligence["events"])<=MAX_LIVE_INTELLIGENCE_EVENTS and len(h.live_intelligence["samples"])<=MAX_LIVE_INTELLIGENCE_SAMPLES,"sample and event histories remain bounded")
        test("bounded event history",bounded)
        test("one recommendation at a time",lambda:require(isinstance(analyze(rows())["recommendation"],str) and "\n" not in analyze(rows())["recommendation"],"result exposes exactly one primary recommendation"))
        test("thermal context",lambda:require("elevated" in analyze(rows(junction=99))["thermal"] and "hardware fault" in analyze(rows(junction=99))["recommendation"],"elevated temperature is contextual, not a GPU-specific diagnosis"))
        test("missing temperature/power sensors",lambda:require("junction —" in analyze(rows(edge=None,junction=None,power=None))["thermal"],"missing sensors remain explicitly unavailable"))
        test("no GPU-specific assumptions",lambda:require("6800" not in str(analyze(rows(junction=99))) and "throttle" not in str(analyze(rows(junction=99))).lower(),"classification contains no model-specific throttle threshold"))
        test("Crimson Desert generic unified-identity path",lambda:require(analyze(rows())["state"]==analyze([{**r,"game_id":"steam:3321460"} for r in rows()])["state"],"AppID 3321460 receives the same provider-neutral analysis"))
        test("HLL regression path",lambda:require(analyze(rows())["state"]==analyze([{**r,"game_id":"steam:686810"} for r in rows()])["state"],"HLL AppID does not alter live thresholds or methodology"))
        def canonical_unchanged():
            raw=rows(65); before=self._analyze_raw_session(raw,1700000000.0); self._analyze_live_intelligence(raw,[],True); after=self._analyze_raw_session(raw,1700000000.0); return require(before==after and before.get("analyzer_version")==ANALYZER_VERSION,"live analysis does not mutate canonical analyzer output")
        test("canonical analyzer isolation",canonical_unchanged)
        return tests

    def _live_analysis_ui_test_results(self):
        tests=[]
        def test(name,fn):
            try:detail=fn(); tests.append({"name":name,"passed":True,"detail":detail})
            except Exception as exc:tests.append({"name":name,"passed":False,"detail":f"{type(exc).__name__}: {exc}"})
        def require(condition,detail):assert condition,detail; return detail
        context={"game":"Crimson Desert","game_id":"steam:3321460","provider":"steam","steam_appid":"3321460","profile":"AMD Default","scaling":""}
        result={"state":"GPU limited","confidence":"High","evidence":"61 paired samples / 60s   •   recent median 90 FPS   •   median GPU load 98%","recommendation":"Lower render scale or GPU-heavy graphics settings for more FPS; recent GPU load is consistently near saturation.","thermal":"unused","events":[]}
        sample={"t":1060,"fps":90,"gpu_load":98,"edge_c":72,"junction_c":88,"power_w":220,"gpu_clock_mhz":2200}
        state={"identity":"steam:3321460","samples":[sample],"events":[],"last_event_t":None,"suspended":False,"result":result,"phase":"gameplay","phase_confidence":"High"}
        telemetry={"fps":90,"low":72,"telemetry_state":"Telemetry active","parser_status":"Valid FPS sample parsed","file_exists":True}
        active=lambda s=state,t=telemetry,c=context:self._live_analysis_view_data(s,c,t)
        def summary_geometry():
            spec=self._dashboard_live_summary_spec(); fits=spec["height"]-2>=spec["minimum_button_height"]+2*spec["button_vertical_padding"]
            return require(spec["lines"]==1 and not spec["renders_event_list"] and fits and not spec["horizontal_scroll"],"fixed summary reserves full button height, border, and vertical padding")
        test("Dashboard fixed height with zero events",summary_geometry)
        def five_event_height():
            five=dict(state,events=[{"clock":f"10:00:0{i}","kind":"GPU-saturated hitch","fps":40} for i in range(5)]); view=active(five); spec=self._dashboard_live_summary_spec(); return require(spec["height"]==self._dashboard_live_summary_spec()["height"] and not spec["changes_graph_position_with_events"] and "5 gameplay events" in self._dashboard_live_summary_text(view),"five events retain identical fixed height and graph position")
        test("Dashboard fixed height with five events",five_event_height)
        test("Dashboard current state",lambda:require("GPU limited" in self._dashboard_live_summary_text(active()),"summary reflects current state"))
        test("Dashboard confidence",lambda:require("High Confidence" in self._dashboard_live_summary_text(active()),"summary reflects confidence"))
        def unavailable_summary():
            suspended=dict(state,suspended=True,result={**result,"state":"Insufficient evidence","confidence":"Low"}); view=self._live_analysis_view_data(suspended,context,{"telemetry_state":"MangoHud active but CSV unavailable"}); return require("MangoHud active but CSV unavailable" in self._dashboard_live_summary_text(view),"summary reports telemetry state instead of a conclusion")
        test("Dashboard telemetry unavailable",unavailable_summary)
        def no_event_list():
            with_events=dict(state,events=[{"clock":"10:42:17","kind":"GPU-saturated hitch","fps":37}]); summary=self._dashboard_live_summary_text(active(with_events)); return require("GPU-saturated hitch" not in summary and "10:42:17" not in summary,"Dashboard renders only event count")
        test("Dashboard omits full event list",no_event_list)
        def navigation():
            class Selector:
                def __init__(self):self.selected=None
                def select(self,value):self.selected=value
            h=App.__new__(App); h.nb=Selector(); h.analysis_nb=Selector(); h.tabs={"Analysis":"outer-analysis"}; h.live_analysis_page="inner-live-analysis"; h._open_live_analysis(); return require(h.nb.selected=="outer-analysis" and h.analysis_nb.selected=="inner-live-analysis","Dashboard action selects Analysis then Live Analysis")
        test("View Live Analysis navigation",navigation)
        test("Live Analysis idle state",lambda:require(self._live_analysis_view_data(state,None,telemetry)["mode"]=="idle" and self._live_analysis_view_data(state,None,telemetry)["game"]=="No active game","idle view contains no stale game"))
        test("Detected game without telemetry",lambda:require(self._live_analysis_view_data(self._new_live_intelligence_state("steam:3321460"),context,{"telemetry_state":"Telemetry not instrumented"})["mode"]=="detected","detected identity remains visible without telemetry"))
        test("Waiting for samples",lambda:require(self._live_analysis_view_data(self._new_live_intelligence_state("steam:3321460"),context,{"telemetry_state":"Telemetry file found — waiting for samples","file_exists":True})["mode"]=="waiting","waiting file state remains truthful"))
        test("Active state",lambda:require(active()["mode"]=="active" and active()["state"]=="GPU limited","active view uses existing result"))
        test("Temporary telemetry loss",lambda:require(self._live_analysis_view_data(dict(state,suspended=True),context,{"telemetry_state":"Telemetry interrupted"})["mode"]=="suspended","identity remains while conclusions suspend"))
        test("Telemetry recovery",lambda:require(active()["mode"]=="active" and active()["confidence"]=="High","active view resumes from recovered telemetry"))
        test("Game exit clear",lambda:require(self._live_analysis_view_data(self._new_live_intelligence_state(),None,{})["events"]==[] and self._live_analysis_view_data(self._new_live_intelligence_state(),None,{})["mode"]=="idle","exit returns a clean idle view"))
        def identity_reset():
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("steam:3321460"); h.live_intelligence["events"]=[{"kind":"old"}]; h._live_intelligence_ingest("steam:686810",sample); return require(h.live_intelligence["identity"]=="steam:686810" and not h.live_intelligence["events"],"new identity clears previous event presentation")
        test("Game identity reset",identity_reset)
        test("Bounded recent-event presentation",lambda:require(len(self._live_analysis_view_data(dict(state,events=[{"kind":str(i)} for i in range(9)]),context,telemetry)["events"])==MAX_LIVE_INTELLIGENCE_EVENTS,"view uses the existing five-event bound"))
        def missing_sensors():
            view=self._live_analysis_view_data(dict(state,samples=[{"t":1,"fps":60,"gpu_load":70}]),context,telemetry); return require(all(value is None for value in view["sensors"].values()),"missing sensors remain unavailable")
        test("Missing sensors unavailable",missing_sensors)
        def long_text():
            long_context={**context,"game":"Very Long Game Name "*30,"provider":"very-long-provider-"*20,"profile":"profile "*40,"scaling":"scale "*40}; before=dict(state); view=self._live_analysis_view_data(state,long_context,telemetry); return require(view["state"]=="GPU limited" and state==before,"long display strings do not alter analysis state")
        test("Long display text state isolation",long_text)
        for width in (1300,1100,980):
            test(f"Responsive layout {width}px",lambda w=width:require(not self._live_analysis_responsive_layout(w)["horizontal_scroll"] and self._live_analysis_responsive_layout(w)["wraplength"]<=w,"vertical responsive layout requires no horizontal scrolling"))
            test(f"Dashboard summary button fit {width}px",lambda w=width:require(self._dashboard_live_summary_spec()["height"]-2>=self._dashboard_live_summary_spec()["minimum_button_height"]+2*self._dashboard_live_summary_spec()["button_vertical_padding"] and not self._dashboard_live_summary_spec()["horizontal_scroll"] and w>=980,"View Live Analysis button fits fully without moving graphs or adding horizontal scrolling"))
        def calculations_unchanged():
            rows=[{"t":1000+i,"fps":90,"gpu_load":98,"edge_c":72,"junction_c":88,"power_w":220,"gpu_clock_mhz":2200} for i in range(65)]; analyzed=self._analyze_live_intelligence(rows,[],True); return require(analyzed["state"]=="GPU limited" and analyzed["confidence"]=="High" and MAX_LIVE_INTELLIGENCE_SAMPLES==240 and MAX_LIVE_INTELLIGENCE_EVENTS==5,"v0.89.0 engine constants and classification remain unchanged")
        test("v0.89.0 calculations unchanged",calculations_unchanged)
        def canonical_unchanged():
            raw=[{"t":1000+i,"fps":90,"gpu_load":98,"power_w":220,"gpu_clock_mhz":2200} for i in range(65)]; before=self._analyze_raw_session(raw,1700000000.0); self._live_analysis_view_data(state,context,telemetry); after=self._analyze_raw_session(raw,1700000000.0); return require(before==after and before.get("analyzer_version")==ANALYZER_VERSION,"UI view model leaves canonical analyzer output unchanged")
        test("Canonical analyzer output unchanged",canonical_unchanged)
        return tests

    def _live_transition_test_results(self):
        tests=[]
        def test(name,fn):
            try:detail=fn(); tests.append({"name":name,"passed":True,"detail":detail})
            except Exception as exc:tests.append({"name":name,"passed":False,"detail":f"{type(exc).__name__}: {exc}"})
        def require(condition,detail):assert condition,detail; return detail
        def feed(parts):
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("steam:3321460"); h.live_intelligence["phase"]="gameplay"; t=1000.0
            for count,fps,load,power,clock in parts:
                values=fps if isinstance(fps,(list,tuple)) else [fps]*count
                for value in values:
                    h._live_intelligence_ingest("steam:3321460",{"t":t,"fps":value,"gpu_load":load,"power_w":power,"gpu_clock_mhz":clock,"edge_c":72,"junction_c":88}); t+=1.0
            return h
        def crimson_fixture():return feed([(20,145,98,220,2200),(5,60,24,65,550),(6,[75,73,72,74,73,75],97,205,1950),(10,145,98,220,2200)])
        def save_load():
            h=crimson_fixture(); kinds=[e["kind"] for e in h.live_intelligence["events"]]; return require("Loading/transition" in kinds and "GPU-saturated hitch" not in kinds,"Crimson Desert menu/save-load lows are transition-only")
        test("Crimson Desert menu/save-load fixture",save_load)
        test("Loading transition does not persist as instability",lambda:require(crimson_fixture().live_intelligence["result"]["state"]=="GPU limited","stable gameplay promptly recovers to GPU limited"))
        def real_hitch():
            h=feed([(12,100,98,220,2200),(1,40,99,222,2200),(4,100,98,220,2200)]); return require(h.live_intelligence["events"][-1]["kind"]=="GPU-saturated hitch" and h.live_intelligence["events"][-1]["gameplay_impact"],"isolated real gameplay hitch is published after the bounded classification delay")
        test("Real gameplay GPU-saturated hitch",real_hitch)
        def headroom_hitch():
            h=feed([(12,100,98,220,2200),(1,40,65,135,1500),(4,100,98,220,2200)]); return require(h.live_intelligence["events"][-1]["kind"]=="GPU-headroom/engine hitch" and h.live_intelligence["events"][-1]["gameplay_impact"],"isolated headroom hitch remains a gameplay-impact event after temporal classification")
        test("Real gameplay GPU-headroom hitch",headroom_hitch)
        def gpu_high_loading():
            h=feed([(12,100,98,220,2200),(2,40,98,130,1450)]); return require(not h.live_intelligence["events"] and h.live_intelligence["phase"] in ("gameplay","unknown","pending"),"two-sample disturbance remains advisory and does not manufacture a loading event")
        test("GPU-high possible-transition restraint",gpu_high_loading)
        def repeated_loading():
            h=feed([(12,140,98,220,2200),(4,60,25,65,550),(8,[75,72,74,73,75,72,74,73],98,205,1950)]); events=h.live_intelligence["events"]; return require(len(events)==1 and events[0]["kind"]=="Loading/transition","one loading sequence produces one transition event")
        test("Repeated loading-event suppression",repeated_loading)
        def real_shape_gpu_saturated_load():
            # Fixture values intentionally reproduce the observed workload; the
            # production detector uses only relative regime and temporal evidence.
            h=feed([(20,142,99,220,2200),(3,118,99,220,2200),(10,[72,71,72,71,72,71,72,71,72,71],99,220,2200),(14,142,99,220,2200)])
            events=h.live_intelligence["events"]; gameplay=[e for e in events if e.get("gameplay_impact")]; transitions=[e for e in events if e.get("gameplay_impact") is False]
            excluded=[r for r in h.live_intelligence["samples"] if r.get("live_phase")!="gameplay"]
            result=h.live_intelligence["result"]
            return require(not gameplay and len(transitions)==1 and len(excluded)>=10 and result["state"]=="GPU limited" and result["state"]!="Frame-time instability","GPU-saturated saved-game load becomes one transition, is excluded from gameplay P1/stability, and recovers to GPU limited")
        test("Real-shape GPU-saturated saved-game load",real_shape_gpu_saturated_load)
        def published_event_reconciliation():
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("steam:fixture"); h.live_intelligence["phase"]="gameplay"; t=1000.0
            def put(fps,load=99):
                nonlocal t
                h._live_intelligence_ingest("steam:fixture",{"t":t,"fps":fps,"gpu_load":load,"power_w":220,"gpu_clock_mhz":2200,"edge_c":72,"junction_c":88}); t+=1.0
            for _ in range(20):put(142)
            for _ in range(3):put(118)
            # Four loading candidates are deliberately allowed to cross the
            # publication delay before later temporal evidence confirms phase.
            for _ in range(4):
                put(72)
                for _ in range(4):put(142)
            published_before=sum(1 for e in h.live_intelligence["events"] if e.get("gameplay_impact"))
            for _ in range(4):put(72)
            confirmed_events=list(h.live_intelligence["events"])
            transition_samples=[r for r in h.live_intelligence["samples"] if r.get("live_phase")=="transition"]
            for _ in range(10):put(142)
            final_events=h.live_intelligence["events"]; gameplay=[e for e in final_events if e.get("gameplay_impact")]; transitions=[e for e in final_events if e.get("gameplay_impact") is False]
            view=self._live_analysis_view_data(h.live_intelligence,{"game":"Fixture","provider":"steam","steam_appid":"1"},{"fps":142,"low":120,"telemetry_state":"Telemetry active"})
            return require(published_before==4 and not [e for e in confirmed_events if e.get("gameplay_impact")] and len([e for e in confirmed_events if e.get("gameplay_impact") is False])==1 and len(transition_samples)>=20 and not gameplay and len(transitions)==1 and h.live_intelligence["phase"]=="gameplay" and h.live_intelligence["result"]["state"]=="GPU limited" and view["gameplay_event_count"]==0 and view["transition_event_count"]==1,"four already-published loading candidates reconcile to one transition; excluded samples recover to GPU limited within ten stable samples")
        test("Published loading-event reconciliation",published_event_reconciliation)
        def recovery_settling():
            h=feed([(12,140,98,220,2200),(4,60,25,65,550),(5,74,98,205,1950),(10,140,98,220,2200)]); phases=[r.get("live_phase") for r in h.live_intelligence["samples"][-10:]]; return require("settling" in phases and phases[-1]=="gameplay" and h.live_intelligence["result"]["state"]!="Frame-time instability","settling samples are excluded before gameplay resumes")
        test("Recovery settling period",recovery_settling)
        test("Menu/background interval",lambda:require(feed([(12,100,98,220,2200),(5,60,20,50,500)]).live_intelligence["result"]["state"]!="Insufficient evidence","menu/settling context does not gate active limiter analysis"))
        def telemetry_gap():
            h=feed([(12,100,98,220,2200),(1,40,99,220,2200)]); before=len(h.live_intelligence["events"]); h._suspend_live_intelligence("steam:3321460")
            t=1013.0
            for _ in range(4):h._live_intelligence_ingest("steam:3321460",{"t":t,"fps":100,"gpu_load":98,"power_w":220,"gpu_clock_mhz":2200}); t+=1
            return require(len(h.live_intelligence["events"])==before and h.live_intelligence["result"]["state"]!="Frame-time instability","gap discards unresolved provisional classification and recovery creates no false event")
        test("Telemetry gap remains event-free",telemetry_gap)
        def true_instability():
            parts=[(12,100,98,220,2200)]
            for _ in range(4):parts.extend(((1,40,99,220,2200),(3,100,98,220,2200)))
            h=feed(parts); gameplay=[e for e in h.live_intelligence["events"] if e.get("gameplay_impact")]; return require(len(gameplay)>=3 and h.live_intelligence["result"]["state"]=="Frame-time instability","repeated gameplay lows remain gameplay-impact instability")
        test("True repeated gameplay instability",true_instability)
        def event_counts():
            h=crimson_fixture(); h.live_intelligence["events"].append({"kind":"GPU-saturated hitch","fps":40,"gameplay_impact":True}); view=self._live_analysis_view_data(h.live_intelligence,{"game":"Crimson Desert","game_id":"steam:3321460","provider":"steam","steam_appid":"3321460"},{"fps":145,"low":120,"telemetry_state":"Telemetry active"}); summary=self._dashboard_live_summary_text(view); return require(view["gameplay_event_count"]==1 and view["transition_event_count"]>=1 and "1 gameplay event" in summary,"Dashboard separates gameplay and transition counts")
        test("Gameplay/transition event counting",event_counts)
        def phase_diagnostics():
            h=feed([(12,140,99,220,2200),(4,[72,71,72,71],99,220,2200)]); view=self._live_analysis_view_data(h.live_intelligence,{"game":"Fixture","provider":"steam","steam_appid":"1"},{"fps":71,"telemetry_state":"Telemetry active"}); return require(view["phase"] in ("Unknown / uncertain","Gameplay") and view["performance_status"].startswith("Active") and view["phase_confidence"] in ("Low","Moderate") and view["phase_evidence"],"weak phase evidence is diagnostic while performance analysis stays active")
        test("Phase diagnostics",phase_diagnostics)
        return tests

    def _live_workload_phase_test_results(self):
        tests=[]
        def test(name,fn):
            try:detail=fn(); tests.append({"name":name,"passed":True,"detail":detail})
            except Exception as exc:tests.append({"name":name,"passed":False,"detail":f"{type(exc).__name__}: {exc}"})
        def require(condition,detail):assert condition,detail; return detail
        def harness(established=False,identity="game:synthetic"):
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state(identity)
            if established:h.live_intelligence["phase"]="gameplay"
            return h
        def put(h,t,fps,load,power=None,clock=None,identity="game:synthetic"):
            h._live_intelligence_ingest(identity,{"t":float(t),"fps":float(fps),"gpu_load":float(load),"power_w":power,"gpu_clock_mhz":clock}); return t+1
        def run(parts,established=False):
            h=harness(established); t=1000
            for values,load,power,clock in parts:
                for fps in values:t=put(h,t,fps,load,power,clock)
            return h
        varied=lambda center,count=14:[center+((-1,1,0,2,-2)[i%5]) for i in range(count)]
        def shape_a():
            h=run([([60]*8,28,None,None),([35,52,29,47,33,55],96,None,None),(varied(105,16),97,None,None)]); return require(h.live_intelligence["phase"]=="gameplay" and h.live_intelligence["result"]["state"]=="GPU limited","low-GPU menu → high-GPU loading → high-GPU gameplay works without optional power/clock sensors")
        test("A low-GPU menu / high-GPU loading / gameplay",shape_a)
        def shape_b():
            h=run([([120]*8,99,215,2150),([70,92,61,88,66,95],99,220,2200),(varied(110,16),99,225,2220)]); phases={r.get("live_phase") for r in h.live_intelligence["samples"]}; return require(h.live_intelligence["phase"]=="gameplay" and "transition" in phases,"high GPU utilization does not prevent menu/loading classification or fresh gameplay recovery")
        test("B high-GPU menu / high-GPU loading / gameplay",shape_b)
        def shape_c():
            h=run([([144]*9,98,210,2100),([90,74,101,68,96,72],97,205,2050),(varied(118,12),98,220,2200)]); return require(h.live_intelligence["phase"]=="gameplay","stable high-work capped startup regime transitions through loading into gameplay")
        test("C capped high-GPU menu / loading / gameplay",shape_c)
        def shape_d():
            h=run([(varied(100,16),96,210,2100),([60]*9,96,180,1800),(varied(100,12),96,210,2100)],True); return require(h.live_intelligence["phase"]=="gameplay" and len(h.live_intelligence["regime_memory"])<=8,"gameplay → distinct menu plateau → gameplay recovers without persistent loading")
        test("D gameplay / menu / gameplay",shape_d)
        def shape_e():
            h=run([(varied(145,16),98,220,2200),([65,82,54,76,59,85],99,215,2150),(varied(92,12),98,218,2180)],True); return require(h.live_intelligence["phase"]=="gameplay" and h.live_intelligence["result"]["state"]=="GPU limited","post-load gameplay establishes from its own stable regime despite a materially different FPS level")
        test("E different post-load gameplay regime",shape_e)
        def isolated(load,kind):
            h=run([(varied(100,14),98,220,2200),([38],load,220 if load>90 else 130,2200 if load>90 else 1450),(varied(100,5),98,220,2200)],True); return require(h.live_intelligence["events"][-1]["kind"]==kind and h.live_intelligence["events"][-1].get("gameplay_impact"),f"established gameplay preserves {kind}")
        test("F isolated GPU-saturated gameplay hitch",lambda:isolated(99,"GPU-saturated hitch"))
        test("G isolated GPU-headroom gameplay hitch",lambda:isolated(62,"GPU-headroom/engine hitch"))
        def instability():
            parts=[(varied(100,14),98,220,2200)]
            for _ in range(4):parts.extend((([40],99,220,2200),(varied(100,3),98,220,2200)))
            h=run(parts,True); return require(sum(1 for e in h.live_intelligence["events"] if e.get("gameplay_impact"))>=3 and h.live_intelligence["result"]["state"]=="Frame-time instability","repeated genuine gameplay hitches remain detectable")
        test("H repeated gameplay instability",instability)
        def interrupted():
            h=run([(varied(100,14),98,220,2200),([42,39,45,37],96,180,1800)],True); before=list(h.live_intelligence["events"]); h._suspend_live_intelligence("game:synthetic"); suspended_phase=h.live_intelligence["phase"]; t=1018
            for fps in varied(108,12):t=put(h,t,fps,97,220,2200)
            return require(suspended_phase in ("transition","settling","unknown","gameplay") and h.live_intelligence["phase"]=="gameplay" and len(h.live_intelligence["events"])>=len(before),"telemetry gap creates no false reconciliation and fresh evidence restores gameplay")
        test("I transition telemetry interruption/recovery",interrupted)
        def ambiguous():
            h=harness(); t=1000
            for fps in [96,104,97,103,96,104]:t=put(h,t,fps,75,None,None) + 19
            return require(h.live_intelligence["phase"]=="unknown" and not h.live_intelligence["events"],"discontinuous contradictory startup evidence remains Unknown")
        test("J ambiguous workload remains unknown",ambiguous)
        def recurring_memory():
            h=run([(varied(100,14),96,210,2100),([60]*8,80,150,1500),(varied(100,10),96,210,2100),([60]*8,80,150,1500),(varied(100,10),96,210,2100)],True)
            menus=[r for r in h.live_intelligence["regime_memory"] if r.get("phase")=="menu/background"]
            return require(h.live_intelligence["phase"]=="gameplay" and menus and max(r.get("hits",0) for r in menus)>=2 and len(h.live_intelligence["regime_memory"])<=8,"recurring menu reference gains bounded within-session evidence without persistence")
        test("K bounded adaptive phase memory",recurring_memory)
        def identity_reset():
            h=run([(varied(100,14),96,210,2100),([60]*8,70,130,1300)],True); assert h.live_intelligence["regime_memory"]
            put(h,2000,100,96,210,2100,"game:new")
            return require(h.live_intelligence["identity"]=="game:new" and not h.live_intelligence["regime_memory"] and h.live_intelligence["phase"]=="unknown","identity change clears every adaptive regime reference")
        test("L identity change resets phase memory",identity_reset)
        return tests

    def _live_phase_failsafe_test_results(self):
        tests=[]
        def test(name,fn):
            try:detail=fn(); tests.append({"name":name,"passed":True,"detail":detail})
            except Exception as exc:tests.append({"name":name,"passed":False,"detail":f"{type(exc).__name__}: {exc}"})
        def require(condition,detail):assert condition,detail; return detail
        varied=lambda center,count:[center+((-2,1,0,2,-1)[i%5]) for i in range(count)]
        def make():
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("game:failsafe"); h.live_intelligence["phase"]="gameplay"; h.live_intelligence["gameplay_established"]=True; return h
        def feed(h,values,load=98,power=220,clock=2200,start=None):
            t=float(start if start is not None else ((h.live_intelligence["samples"][-1]["t"]+1) if h.live_intelligence["samples"] else 1000))
            phases=[]
            for fps in values:
                h._live_intelligence_ingest("game:failsafe",{"t":t,"fps":fps,"gpu_load":load,"power_w":power,"gpu_clock_mhz":clock}); phases.append(h.live_intelligence["phase"]); t+=1
            return phases
        def established():
            h=make(); feed(h,varied(120,20)); return h
        def late_loading_recovery():
            h=established(); feed(h,[52,41,58,38,55,43],35,90,900); phases=feed(h,varied(105,14),97,215,2150)
            return require(h.live_intelligence["phase"]=="gameplay" and "transition" not in phases[-4:] and h.live_intelligence["result"]["state"]!="Loading / transition","late loading recognition cannot retain authority after stable current telemetry")
        test("A late loading recognition releases promptly",late_loading_recovery)
        def slow_recovery_bound():
            h=established(); feed(h,[48,35,57,31,51,39],30,80,800); phases=feed(h,varied(88,25),96,205,2050)
            last_transition=max((i for i,p in enumerate(phases) if p=="transition"),default=-1)
            return require(last_transition<15 and h.live_intelligence["phase"]=="gameplay","fresh stable gameplay wins within the bounded horizon, never an 80-second suppression")
        test("B stale transition authority is bounded",slow_recovery_bound)
        def false_gameplay_transition():
            h=established(); feed(h,[55,52,58,54],98,220,2200); phases=feed(h,varied(120,8),98,220,2200)
            return require("transition" not in phases and not [e for e in h.live_intelligence["events"] if e.get("gameplay_impact") is False] and h.live_intelligence["phase"]=="gameplay","short FPS-only disturbance becomes advisory uncertainty, not confident loading")
        test("C established-gameplay false transition hysteresis",false_gameplay_transition)
        def strong_loading():
            h=established(); feed(h,[48,39,55,34,50,37],32,82,820)
            return require(h.live_intelligence["phase"] in ("transition","settling") and h.live_intelligence["events"] and h.live_intelligence["events"][-1].get("gameplay_impact") is False,"sustained temporal collapse plus independent workload changes still confirms loading")
        test("D strong multi-signal loading remains confirmable",strong_loading)
        def ambiguous_startup():
            h=App.__new__(App); h.live_intelligence=h._new_live_intelligence_state("game:ambiguous"); t=1000
            for fps in [94,106,95,105,94,106,95,105,94,106]:h._live_intelligence_ingest("game:ambiguous",{"t":t,"fps":fps,"gpu_load":82}); t+=1
            view=self._live_analysis_view_data(h.live_intelligence,{"game":"Synthetic","provider":"manual"},{"fps":106,"telemetry_state":"Telemetry active"})
            return require(h.live_intelligence["phase"]=="unknown" and view["performance_status"].startswith("Active") and h.live_intelligence["result"]["state"]!="Loading / transition","ambiguous startup remains Unknown while limiter analysis becomes usable with reduced confidence")
        test("E ambiguous startup keeps analysis active",ambiguous_startup)
        def high_gpu_reconciliation():
            h=established(); feed(h,[58,57,58,57,58,57,58,57,58,57],99,220,2200); feed(h,varied(108,12),99,220,2200)
            gameplay=[e for e in h.live_intelligence["events"] if e.get("gameplay_impact")]; transitions=[e for e in h.live_intelligence["events"] if e.get("gameplay_impact") is False]
            return require(not gameplay and len(transitions)==1,"long high-GPU loading cluster retains reconciliation to one confirmed transition")
        test("F high-GPU loading reconciliation",high_gpu_reconciliation)
        def genuine_hitches():
            one=established(); feed(one,[48],99,220,2200); feed(one,varied(120,5),98,220,2200)
            repeated=established()
            for _ in range(4):feed(repeated,[48],99,220,2200); feed(repeated,varied(120,3),98,220,2200)
            return require(any(e.get("gameplay_impact") for e in one.live_intelligence["events"]) and sum(1 for e in repeated.live_intelligence["events"] if e.get("gameplay_impact"))>=3,"isolated and repeated established-gameplay hitches remain publishable")
        test("G genuine gameplay hitches remain detectable",genuine_hitches)
        def eighty_second_wrong_phase():
            rows=[{"t":1000+i,"fps":90+((-1,1,0)[i%3]),"gpu_load":98,"live_phase":"transition"} for i in range(80)]
            results=[self._analyze_live_intelligence(rows[:count],[],True) for count in range(1,81)]
            active=results[4:]
            state=self._new_live_intelligence_state("game:long-phase"); state.update({"phase":"transition","suspended":False,"samples":rows,"result":results[-1]})
            view=self._live_analysis_view_data(state,{"game":"Synthetic","provider":"manual"},{"fps":90,"low":88,"telemetry_state":"Telemetry active"})
            return require(all(result["state"]!="Insufficient evidence" for result in active) and results[-1]["state"]=="GPU limited" and results[-1]["confidence"]=="Low" and view["performance_status"]=="Active with transition context","80 seconds of incorrect transition annotation cannot suppress analysis after five continuous valid samples")
        test("H 80-second wrong phase cannot gate analysis",eighty_second_wrong_phase)
        def stale_phase_after_loading():
            rows=[]
            for i in range(20):rows.append({"t":1000+i,"fps":45+((-4,5,0)[i%3]),"gpu_load":99,"live_phase":"transition"})
            for i in range(20,50):rows.append({"t":1000+i,"fps":112+((-2,1,0,2)[i%4]),"gpu_load":98,"live_phase":"transition"})
            result=self._analyze_live_intelligence(rows,[],True)
            return require(result["state"]=="GPU limited" and result["confidence"]=="Low" and "phase context is advisory" in result["evidence"],"fresh playable telemetry is analyzed even when the phase detector remains incorrectly stuck")
        test("I stale post-load phase cannot stop analysis",stale_phase_after_loading)
        return tests

    def _recommendation_test_results(self):
        tests=[]
        def test(name,fn):
            try:detail=fn(); tests.append({"name":name,"passed":True,"detail":detail or "ok"})
            except Exception as exc:tests.append({"name":name,"passed":False,"detail":f"{type(exc).__name__}: {exc}"})
        def require(value,detail):assert value,detail; return detail
        game={"game_id":"manual:alpha","provider":"manual","provider_id":"alpha","display_name":"Alpha"}
        def cfg(profile="Balanced",preset="Native"):return {"gpu_profile":profile,"graphics_preset":preset,"scaling":preset,"render_resolution":"1920×1080","output_resolution":"1920×1080","power_limit_w":"Unknown","workload_profile":"Unknown"}
        def rec(index=0,profile="Balanced",avg=100,p1=70,power=120,junction=70,quality="Gameplay",appid=""):
            return {"game":"Alpha","steam_appid":appid,"telemetry_identity":"manual:alpha","quality":quality,"duration_seconds":1200,"started_at_epoch":1000+index,"gameplay_avg_fps":avg,"avg_fps":avg,"gameplay_p1_fps":p1,"avg_gpu_load_pct":70,"avg_power_w":power,"avg_junction_c":junction,"max_junction_c":junction+8,"gameplay_dip_events":2,"isolated_hitch_candidates":1,"raw_paired_telemetry_gzip_base64":"x",**cfg(profile)}
        def harness(rows=(),trials=(),policy="automatic"):
            h=App.__new__(App); h.game_session_history={"sessions":list(rows)}; h.optimization_trials={"format_version":1,"trials":list(trials),"active_trial_id":None}; h.game_profile_data={"telemetry_policy":{"manual:alpha":{"state":policy}}}; h.gpu=None; return h
        def derive(rows=(),goal="Balanced",current=None,trials=(),policy="automatic"):return harness(rows,trials,policy)._derive_game_recommendation(game,goal,current or cfg(),list(rows),{"format_version":1,"trials":list(trials)},policy)
        test("no-evidence game",lambda:require(derive()["status"]=="No measured recommendation yet","new games render a truthful no-evidence state"))
        test("one-configuration game",lambda:require("no alternative" in derive([rec()])["reason"].casefold() and not derive([rec()])["apply_available"],"one measured setup is retained without fabricating an alternative"))
        rows=[rec(0,"Balanced",100,65),rec(1,"Balanced",101,66),rec(2,"Performance",110,78),rec(3,"Performance",111,79)]
        test("two comparable configurations",lambda:require(len(derive(rows,"Better P1 / lows")["groups"])==2,"same-game comparable groups remain separate"))
        test("strong measured winner",lambda:require(derive(rows,"Better P1 / lows")["recommended_configuration"]["gpu_profile"]=="Performance","repeatable P1 advantage selects the observed configuration"))
        noisy=[rec(0,"Balanced",100,60),rec(1,"Balanced",101,61),rec(2,"Performance",102,55),rec(3,"Performance",103,90),rec(4,"Performance",101,56)]
        test("high-variance inconclusive",lambda:require(derive(noisy,"Better P1 / lows")["confidence"] in ("Low","Conservative"),"outlier-sensitive evidence lowers confidence"))
        def trial(outcome,final=None):
            value={"trial_id":"t","game_id":"manual:alpha","game_name":"Alpha","goal":"Better P1 / lows","tested_variable":"gpu_profile","baseline_configuration":cfg("Balanced"),"candidate_configuration":cfg("Performance"),"baseline_session_indexes":[0,1],"candidate_session_indexes":[2,3],"trial_complete":True,"trial_outcome":outcome,"created_at":10}
            if final:value["final_choice"]={"choice":final,"configuration":final}
            return value
        test("completed trial Keep Candidate",lambda:require(derive(rows,trials=[trial("KEEP CANDIDATE")])["recommended_configuration"]["gpu_profile"]=="Performance","clear trial candidate outcome has priority"))
        test("completed trial Keep Baseline",lambda:require(derive(rows,current=cfg("Balanced"),trials=[trial("REVERT TO BASELINE")])["recommended_configuration"]["gpu_profile"]=="Balanced","clear baseline trial outcome has priority"))
        test("completed trial Inconclusive",lambda:require(derive(rows,current=cfg("Balanced"),trials=[trial("INCONCLUSIVE","no_change")])["recommended_configuration"]["gpu_profile"]=="Balanced","inconclusive trial conservatively retains current configuration"))
        test("user choice versus evidence",lambda:require(any("final choice differs" in line for line in derive(rows,trials=[trial("KEEP CANDIDATE","baseline")])["limitations"]),"conflicting final choice is disclosed"))
        capped=[{**row,"frame_cap_status":"Frame-rate cap / synchronization likely"} for row in rows]
        test("frame-cap-aware recommendation",lambda:require(derive(capped)["frame_cap"] and any("Frame-cap" in line for line in derive(capped)["evidence"]),"cap context is visible and changes Balanced weights"))
        test("telemetry-disabled limitation",lambda:require(derive(rows,"Better P1 / lows",policy="compatibility_failed")["status"]=="Insufficient evidence" and "will not re-enable" in derive(rows,"Better P1 / lows",policy="compatibility_failed")["limitations"][0],"FPS guidance is withheld without changing telemetry policy"))
        test("current equals recommendation",lambda:require(not derive(rows,"Better P1 / lows",cfg("Performance"))["apply_available"],"matching current configuration requires no apply"))
        test("current differs from recommendation",lambda:require(derive(rows,"Better P1 / lows",cfg("Balanced"))["apply_available"],"measured different recommendation exposes explicit apply"))
        def placeholder_not_actionable():
            current={"gpu_profile":"Unknown","graphics_preset":"Unknown","scaling":"Unknown","render_resolution":"Unknown","output_resolution":"Unknown","power_limit_w":"Unknown","workload_profile":"Unknown"}
            wanted={**current,"gpu_profile":"—"}
            return require(self._recommendation_changes(current,wanted)==[],"placeholder recommendation values never become actionable changes")
        test("placeholder recommendation is non-actionable",placeholder_not_actionable)
        def apply_confirmation_path():
            recommendation=derive(rows,"Better P1 / lows",cfg("Balanced")); calls=[]; result=harness(rows)._apply_recommended_configuration(recommendation,lambda key,value:calls.append((key,value)) or True); return require(result["applied"] and calls==[("gpu_profile","Performance")],str(calls))
        test("explicit apply path",apply_confirmation_path)
        def apply_failure():
            recommendation={"game":game,"current_configuration":cfg("Balanced","Native"),"recommended_configuration":cfg("Performance","FSR Quality")}; calls=[]
            def callback(key,value):calls.append((key,value)); return key!="graphics_preset"
            result=harness()._apply_recommended_configuration(recommendation,callback); return require(not result["applied"] and calls[-1]==("gpu_profile","Balanced"),str(result))
        test("multi-setting failure rolls back",apply_failure)
        def multi_setting():
            recommendation={"game":game,"current_configuration":cfg("Balanced","Native"),"recommended_configuration":cfg("Performance","FSR Quality")}; calls=[]; result=harness()._apply_recommended_configuration(recommendation,lambda key,value:calls.append((key,value)) or True); return require(result["applied"] and len(calls)==2,"all declared changes apply through existing mechanisms")
        test("multi-setting recommendation",multi_setting)
        manual=derive(rows); test("provider-neutral identity",lambda:require(manual["game"]["game_id"]=="manual:alpha" and len(manual["groups"])==2,"recommendations do not require Steam identity"))
        test("outlier-sensitive evidence",lambda:require(any("unusual retained run" in line for line in derive(noisy,"Better P1 / lows")["limitations"]),"unusual evidence stays included and visible"))
        def no_stale_cache():
            first=derive([rec()],"Better P1 / lows"); second=derive(rows,"Better P1 / lows"); return require(first["recommended_configuration"]!=second["recommended_configuration"],"recommendation is re-derived when evidence changes")
        test("stale recommendation invalidation",no_stale_cache)
        unknown={"gpu_profile":"—","graphics_preset":"","scaling":"—","render_resolution":"Unknown","output_resolution":"Unknown","power_limit_w":"Unknown","workload_profile":"Unknown"}
        def reconstructable_one():
            result=derive([rec()],current=cfg()); return require(result["recommended_configuration"]["gpu_profile"]=="Balanced" and self._recommendation_configuration_known(result["recommended_configuration"]) and not result["apply_available"],"one concrete observed configuration is displayed without claiming comparative superiority")
        test("one measured reconstructable configuration",reconstructable_one)
        def unreconstructable_one():
            row={**rec(),**unknown,"frame_cap_status":"Frame-rate cap / synchronization likely"}; result=derive([row],current=unknown); return require(result["recommended_configuration"] is None and result["status"]=="Insufficient comparative evidence" and not result["apply_available"],"placeholder-only evidence yields an explicit no-change recommendation")
        test("one measured unreconstructable configuration",unreconstructable_one)
        test("unknown current is never already or applicable",lambda:require(not self._recommendation_configuration_known(unknown) and not derive(rows,"Better P1 / lows",unknown)["apply_available"],"unknown current configuration cannot establish equivalence or safe apply"))
        test("known current equals recommendation invariant",lambda:require(self._recommendation_configuration_known(cfg("Performance")) and self._recommendation_config_matches(cfg("Performance"),cfg("Performance")) and not derive(rows,"Better P1 / lows",cfg("Performance"))["apply_available"],"known canonical equality is required for already-active state"))
        test("known current differs from recommendation invariant",lambda:require(not self._recommendation_config_matches(cfg("Balanced"),cfg("Performance")) and derive(rows,"Better P1 / lows",cfg("Balanced"))["apply_available"],"a concrete differing recommendation can be applied explicitly"))
        test("no measured configurations explicit state",lambda:require(derive([],current=unknown)["recommended_configuration"] is None and derive([],current=unknown)["status"]=="No measured recommendation yet","no-evidence state never leaves an implicit recommendation"))
        def hll_inconclusive_regression():
            result=derive(rows,current=cfg("Balanced"),trials=[trial("INCONCLUSIVE","no_change")]); return require(result["recommended_configuration"]["gpu_profile"]=="Balanced" and result["confidence"]=="Moderate" and result["type"]=="Trial-supported recommendation","inconclusive controlled trial conservatively retains the known current profile")
        test("completed inconclusive trial regression",hll_inconclusive_regression)
        def rain_frame_cap_regression():
            rain=[{**rec(i),**unknown,"frame_cap_status":"Frame-rate cap / synchronization likely" if i==2 else "No strong frame-cap evidence"} for i in range(3)]; result=derive(rain,current=unknown); return require(result["frame_cap"] and any("Frame-cap/synchronization evidence is strong" in line for line in result["evidence"]) and result["recommended_configuration"] is None,"frame-cap evidence survives unavailable configuration metadata")
        test("Rain World-shaped frame-cap regression",rain_frame_cap_regression)
        return tests

    def _shutdown_session_test_results(self):
        tests=[]
        def test(name,fn):
            try:detail=fn(); tests.append({"name":name,"passed":True,"detail":detail})
            except Exception as exc:tests.append({"name":name,"passed":False,"detail":f"{type(exc).__name__}: {exc}"})
        def require(condition,detail):assert condition,detail; return detail
        saved=[]
        def harness(with_fps=True):
            h=App.__new__(App); h._shutdown_session_finalized=False; h.game_session_history={"sessions":[]}; h.game_session_missing_since=None; h.live_intelligence=h._new_live_intelligence_state("steam:3321460")
            fps=[90.0,88.0] if with_fps else []; paired=[{"t":1000,"fps":90,"gpu_load":98,"power_w":220,"gpu_clock_mhz":2200},{"t":1001,"fps":88,"gpu_load":97,"power_w":218,"gpu_clock_mhz":2190}] if with_fps else []
            h.game_session_current={"identity":("3321460","Crimson Desert","game:steam:3321460"),"game":"Crimson Desert","steam_appid":"3321460","started_at":time.time()-8,"started_iso":"2026-08-24 10:00:00","gpu_profile":"AMD Default","graphics_preset":"","scaling":"—","telemetry_identity":"steam:3321460","telemetry_status":"Telemetry active" if with_fps else "Game detected — waiting for telemetry","telemetry_method":"Steam + MangoHud","fps":fps,"p1":[],"p1_sources":[],"edge":[72.0],"junction":[88.0],"temp_delta":[16.0],"gpu_load":[98.0],"power":[220.0],"gpu_clock":[2200.0],"memory_clock":[],"vram_pct":[],"paired_perf":paired,"_last_fps":fps[-1] if fps else None,"_last_fps_time":None}
            h._refresh_game_session_history_ui=lambda:None; h._refresh_analysis_lab_sessions=lambda:None; h._refresh_session_trends=lambda:None; h._refresh_optimization_insights=lambda:None
            return h
        def run(with_fps=True):
            h=harness(with_fps); original=globals()["save_game_session_history_file"]; globals()["save_game_session_history_file"]=lambda data:saved.append(list(data.get("sessions",[])))
            try:result=h._finalize_active_session_on_shutdown()
            finally:globals()["save_game_session_history_file"]=original
            return h,result,h.game_session_history["sessions"][0]
        test("Shutdown active session saves partial",lambda:require(run()[1] and len(run()[0].game_session_history["sessions"])==1,"active shutdown finalizes through normal history path"))
        test("Shutdown retains game/AppID",lambda:require((lambda r:r["game"]=="Crimson Desert" and r["steam_appid"]=="3321460" and r["telemetry_identity"]=="steam:3321460")(run()[2]),"unified identity, game, and AppID retained"))
        test("Shutdown retains telemetry",lambda:require((lambda r:r["raw_paired_telemetry_samples"]==2 and r["avg_fps"]==89.0 and r["max_junction_c"]==88.0)(run()[2]),"captured FPS/GPU/thermal/raw telemetry retained"))
        test("Shutdown close reason",lambda:require(run()[2]["reason"]=="ALCC exited while game active","explicit active-game close reason persisted"))
        test("Shutdown no-FPS truthfulness",lambda:require((lambda r:r["avg_fps"] is None and r["raw_paired_telemetry_samples"]==0 and self._game_session_quality(r)!="Gameplay")(run(False)[2]),"no FPS is invented and partial quality remains truthful"))
        def no_duplicate():
            h=harness(); calls=[]; h._game_session_finish=lambda reason:(calls.append(reason),setattr(h,"game_session_current",None)); first=h._finalize_active_session_on_shutdown(); second=h._finalize_active_session_on_shutdown(); return require(first and not second and calls==["ALCC exited while game active"],"repeated shutdown callback is idempotent")
        test("Shutdown no duplicate save",no_duplicate)
        def normal_exit_once():
            h=harness(); original=globals()["save_game_session_history_file"]; globals()["save_game_session_history_file"]=lambda data:None
            try:h._game_session_finish("game exited"); shutdown=h._finalize_active_session_on_shutdown()
            finally:globals()["save_game_session_history_file"]=original
            return require(len(h.game_session_history["sessions"])==1 and h.game_session_history["sessions"][0]["reason"]=="game exited" and not shutdown,"normal game exit remains exactly once")
        test("Normal game exit saves once",normal_exit_once)
        def no_active():
            h=App.__new__(App); h._shutdown_session_finalized=False; h.game_session_current=None; return require(not h._finalize_active_session_on_shutdown(),"shutdown without active session writes nothing")
        test("Shutdown without active session",no_active)
        def normal_exit_low_gpu_quality():
            rec={"duration_seconds":388,"avg_fps":139.6,"avg_gpu_load_pct":14.0,"max_gpu_load_pct":57.0,"paired_perf_samples":294,"raw_paired_telemetry_samples":294,"reason":"game exited"}
            return require(self._game_session_quality(rec)=="Gameplay","normal exit with a substantial valid paired frame stream is Gameplay without an arbitrary GPU-load floor")
        test("Normal game exit low-GPU telemetry quality",normal_exit_low_gpu_quality)
        return tests

    def _analysis_self_test_results(self):
        def rows(parts):
            out=[]; t=1000.0
            for count,fps,load,power,clock in parts:
                for _ in range(count):
                    out.append({"t":t,"fps":fps,"gpu_load":load,"power_w":power,"gpu_clock_mhz":clock}); t+=1.0
            return out
        cases=[]
        def check(name,raw,predicate,expected):
            try:
                result=self._analyze_raw_session(raw,started_at=1700000000.0)
                ok=bool(predicate(result)); detail=(expected(result) if callable(expected) else expected) if ok else f"Expected analyzer condition; got rating={result.get('frame_dip_rating')!r}, menu={result.get('likely_menu_samples')}, GPU dips={result.get('gpu_bound_dip_events')}, headroom={result.get('gpu_headroom_dip_events')}, transitions={result.get('transition_dip_events')}, stalls={result.get('full_stall_candidates')}"
            except Exception as e:
                ok=False; result={}; detail=f"Analyzer raised {type(e).__name__}: {e}"
            cases.append({"name":name,"passed":ok,"detail":detail,"result":result})
        check("Smooth gameplay",rows([(120,90,98,220,2200)]),lambda r:r.get("frame_dip_rating")=="Smooth" and r.get("frame_dip_events")==0,"Smooth classification with no dips")
        check("60 FPS menu/cap",rows([(80,92,98,220,2200),(12,60,55,110,1200),(40,91,97,215,2180)]),lambda r:r.get("likely_menu_samples",0)>=12 and r.get("gameplay_avg_fps",0)>85,"60 FPS low-workload interval excluded from Gameplay FPS")
        check("GPU-saturated hitch",rows([(30,90,98,220,2200),(1,10,99,225,2200),(30,90,98,220,2200)]),lambda r:r.get("isolated_hitch_gpu_saturated")==1,"isolated GPU-saturated hitch")
        check("GPU-headroom hitch",rows([(30,90,98,220,2200),(1,10,55,105,1200),(30,90,98,220,2200)]),lambda r:r.get("isolated_hitch_gpu_headroom")==1,"isolated GPU-headroom hitch")
        check("Transition/loading event",rows([(30,90,98,220,2200),(3,8,8,35,300),(30,90,98,220,2200)]),lambda r:r.get("transition_dip_events")==1 and r.get("gameplay_dip_events")==0 and "transition/loading" in r.get("frame_dip_rating","").lower(),"transition recorded but excluded from consistency severity")
        check("Full stall",rows([(30,90,98,220,2200),(1,0,99,225,2200),(30,90,98,220,2200)]),lambda r:r.get("full_stall_candidates")==1 and len(r.get("full_stall_log",[]))==1,lambda r:f"{int(r['full_stall_candidates'])} full-stall candidate at 0 FPS retained, counted, and timestamped at {r['full_stall_log'][0].get('clock','—')}")
        long_raw=rows([(1090,90,98,220,2200),(2,20,99,225,2200),(1098,90,98,220,2200),(2,18,45,90,900),(1098,90,98,220,2200),(2,15,99,225,2200),(8,90,98,220,2200)])
        check("Rare dips in 55-minute session",long_raw,lambda r:r.get("frame_dip_rating")=="Good — rare brief dips" and r.get("gameplay_dip_fraction_pct",100)<1,lambda r:f"{int(r.get('gameplay_dip_events') or 0)} brief gameplay dips / {float(r.get('gameplay_dip_fraction_pct') or 0):.2f}% of gameplay → {r.get('frame_dip_rating')}")
        return cases

    def _live_replay_equivalence_result(self):
        """Exercise completed-session persistence and replay as separate paths."""
        def append(rows,count,fps,load,power,clock):
            t=(rows[-1]["t"]+1.0) if rows else 1000.0
            for _ in range(count):
                rows.append({"t":t,"fps":fps,"gpu_load":load,"power_w":power,"gpu_clock_mhz":clock}); t+=1.0
        raw=[]
        append(raw,30,90,98,220,2200); append(raw,8,60,55,105,1200); append(raw,15,90,98,220,2200)
        append(raw,2,15,99,225,2200); append(raw,12,90,98,220,2200)
        append(raw,3,8,8,35,300); append(raw,12,90,98,220,2200)
        append(raw,1,10,99,225,2200); append(raw,8,90,98,220,2200)
        append(raw,1,12,55,105,1200); append(raw,8,90,98,220,2200)
        append(raw,1,0,99,225,2200); append(raw,20,90,98,220,2200)
        harness=App.__new__(App)
        harness.game_session_history={"sessions":[]}
        harness.game_session_current={
            "game":"Equivalence Test","steam_appid":"0","started_at":1700000000.0,"started_iso":"2023-11-14 22:13:20",
            "fps":[r["fps"] for r in raw],"p1":[],"edge":[],"junction":[],"temp_delta":[],
            "gpu_load":[r["gpu_load"] for r in raw],"power":[r["power_w"] for r in raw],
            "gpu_clock":[r["gpu_clock_mhz"] for r in raw],"memory_clock":[],"vram_pct":[],"paired_perf":raw,
            "gpu_profile":"Test","graphics_preset":"Test","scaling":"Test",
            "display_refresh_hz":144.0,
        }
        harness.game_session_missing_since=None
        harness._refresh_game_session_history_ui=lambda:None
        harness._refresh_analysis_lab_sessions=lambda:None
        original_save=globals()["save_game_session_history_file"]
        globals()["save_game_session_history_file"]=lambda data:None
        try:
            harness._game_session_finish("equivalence test")
        finally:
            globals()["save_game_session_history_file"]=original_save
        stored=harness.game_session_history["sessions"][0]
        replay=harness._analyze_raw_session(harness._stored_raw_telemetry(stored),stored.get("started_at_epoch"),refresh_hz=stored.get("display_refresh_hz"))
        keys=(
            "raw_sampled_avg_fps","raw_sampled_p1_fps","gameplay_avg_fps","gameplay_p1_fps",
            "likely_menu_samples","likely_menu_seconds","menu_cap_intervals",
            "frame_dip_events","gpu_bound_dip_events","gpu_headroom_dip_events","mixed_dip_events",
            "transition_dip_events","isolated_hitch_candidates","isolated_hitch_gpu_saturated",
            "isolated_hitch_gpu_headroom","isolated_hitch_transition","isolated_hitch_mixed",
            "full_stall_candidates","frame_dip_rating",
            "frame_cap_status","frame_cap_confidence","frame_cap_plateau_fps","frame_cap_occupancy_pct",
            "frame_cap_dispersion_pct","frame_cap_duration_seconds","frame_cap_samples","frame_cap_continuity_pct",
            "frame_cap_avg_gpu_load_pct","frame_cap_avg_power_w","frame_cap_avg_gpu_clock_mhz",
            "frame_cap_refresh_hz","frame_cap_refresh_proximity_pct","frame_cap_excluded_transition_samples",
        )
        differences=[f"{key}: live={stored.get(key)!r}, replay={replay.get(key)!r}" for key in keys if stored.get(key)!=replay.get(key)]
        return {"passed":not differences,"differences":differences,"compared":keys}

