    @staticmethod
    def _analysis_result_differences(stored,current):
        keys=("gameplay_avg_fps","gameplay_p1_fps","likely_menu_samples","frame_cap_status","frame_cap_confidence","frame_cap_plateau_fps","frame_cap_occupancy_pct","frame_dip_rating","frame_dip_events","gameplay_dip_events","transition_dip_events","isolated_hitch_candidates","full_stall_candidates","worst_fps")
        rows=[]
        for key in keys:
            old=stored.get(key); new=current.get(key)
            if old!=new:rows.append(f"• {key}: {old!r} → {new!r}")
        return rows or ["• No important analyzer-result differences."]

    def _replay_analysis_lab_session(self):
        idx,rec=self._analysis_lab_selected()
        raw=self._stored_raw_telemetry(rec)
        if not raw:
            self._analysis_lab_set_output("Replay unavailable: this older/partial session does not contain raw paired telemetry. Its stored analysis remains readable in Session History."); return
        current=self._analyze_raw_session(raw,rec.get("started_at_epoch"),refresh_hz=rec.get("display_refresh_hz"))
        self.analysis_lab_replay=(idx,current)
        replayed=dict(rec); replayed.update(current)
        lines=["OFFLINE SESSION REPLAY",f"{rec.get('game','Game')} • {rec.get('ended_iso','—')}",f"Stored analyzer: {self._session_analyzer_label(rec)}",f"Current analyzer: {ANALYZER_VERSION}",""]
        lines += self._performance_advisor_lines(replayed)
        lines += ["","IMPORTANT DIFFERENCES"]
        lines+=self._analysis_result_differences(rec,current)
        hidden=("raw_paired_telemetry","raw_paired_telemetry_gzip_base64")
        lines+=["","ORIGINAL STORED ANALYSIS",json.dumps({k:v for k,v in rec.items() if k not in hidden},indent=2,sort_keys=True),"","REPLAY / CURRENT ANALYSIS",json.dumps(current,indent=2,sort_keys=True)]
        self._analysis_lab_set_output("\n".join(lines))

    def _update_analysis_lab_session(self):
        idx,rec=self._analysis_lab_selected(); replay=getattr(self,"analysis_lab_replay",None)
        if not self._stored_raw_telemetry(rec):
            self._analysis_lab_set_output("Update unavailable: this legacy/partial session has no replayable raw telemetry."); return
        if idx is None or not replay or replay[0]!=idx:
            messagebox.showinfo("Update Historical Record","Replay the selected session first, review its differences, then choose Update Historical Record."); return
        if not messagebox.askyesno("Update Historical Record","Replace only the selected record's analyzer-result fields with the reviewed current replay? The original raw telemetry and metadata will be preserved."):return
        current=replay[1]; rec.update(current); rec["dip_analysis_version"]=ANALYZER_VERSION
        save_game_session_history_file(self.game_session_history); self._refresh_game_session_history_ui(); self._refresh_analysis_lab_sessions(); self._refresh_session_trends(); self._refresh_optimization_insights()
        self.analysis_lab_status.configure(text="Historical analysis explicitly updated.",fg=GREEN)

    def _export_analysis_lab_session(self):
        _,rec=self._analysis_lab_selected()
        if not isinstance(rec,dict):messagebox.showinfo("Export Diagnostic Session","Select a saved session first."); return
        default=re.sub(r"[^A-Za-z0-9._-]+","_",str(rec.get("game") or "session")).strip("_")+"_diagnostic.json"
        path=filedialog.asksaveasfilename(title="Export Diagnostic Session",defaultextension=".json",initialfile=default,filetypes=(("JSON files","*.json"),("All files","*")))
        if not path:return
        payload=self._diagnostic_session_payload(rec)
        try:
            with open(path,"w",encoding="utf-8") as f:json.dump(payload,f,indent=2,sort_keys=True)
            self.analysis_lab_status.configure(text=f"Exported {os.path.basename(path)}",fg=GREEN)
        except Exception as e:messagebox.showerror("Export Diagnostic Session",f"Could not export session:\n{e}")

    @classmethod
    def _diagnostic_session_payload(cls,rec):
        exported=dict(rec) if isinstance(rec,dict) else {}
        raw=cls._stored_raw_telemetry(rec)
        exported.pop("raw_paired_telemetry_gzip_base64",None)
        exported["raw_paired_telemetry"]=raw if raw else None
        return {
            "export_format":"AMD Linux Control Center diagnostic session",
            "export_schema_version":SESSION_SCHEMA_VERSION,
            "p1_field_meanings":{
                "raw_sampled_p1_fps":"Canonical percentile P1 reconstructed from all retained paired raw-session FPS samples.",
                "gameplay_p1_fps":"Canonical percentile P1 after likely menu/capped samples are excluded.",
                "live_reported_p1_fps":"Arithmetic mean of successive live rolling low readings shown by the telemetry provider/fallback during capture; not a session percentile.",
                "p1_fps":"Legacy compatibility copy of live_reported_p1_fps for new records; older records may contain only this field.",
            },
            "session":exported,
        }

    @staticmethod
    def _session_analyzer_label(rec):
        if not isinstance(rec,dict):return "unknown/legacy"
        analyzer=str(rec.get("analyzer_version") or "").strip()
        try:schema=int(rec.get("schema_version"))
        except Exception:schema=0
        if analyzer and schema>=2:return analyzer
        recorded=str(rec.get("dip_analysis_version") or analyzer or "unknown").strip()
        return f"legacy / recorded metadata {recorded}"

    @staticmethod
    def _session_num(v):
        return analysis_session_num(v)

    @classmethod
    def _canonical_session_p1(cls,rec):
        return analysis_canonical_session_p1(rec)











    @staticmethod
    def _dashboard_live_summary_spec():
        return {"height":54,"lines":1,"renders_event_list":False,"button_vertical_padding":4,"minimum_button_height":32,"changes_graph_position_with_events":False,"horizontal_scroll":False}

    @classmethod
    def _live_analysis_view_data(cls,state,context,telemetry):
        state=state if isinstance(state,dict) else cls._new_live_intelligence_state()
        telemetry=telemetry if isinstance(telemetry,dict) else {}
        if not context:
            return {"mode":"idle","game":"No active game","identity":"—","profile":"—","scaling":"—","telemetry":"Waiting for a detected game","state":"Insufficient evidence","confidence":"Low","interpretation":"Live performance analysis will begin when a detected game has telemetry.","evidence":"No active telemetry evidence.","recommendation":"No recommendation until sufficient evidence is available.","p1":None,"events":[],"gameplay_event_count":0,"transition_event_count":0,"phase":"Unknown / insufficient evidence","phase_confidence":"Low","phase_evidence":[],"performance_status":"Waiting for telemetry","phase_duration":0.0,"pending_event_count":0,"phase_reason":"Waiting for a detected game","sensors":{"edge":None,"junction":None,"delta":None,"power":None,"clock":None}}
        result=state.get("result") or cls._analyze_live_intelligence(state.get("samples",[]),state.get("events",[]),not state.get("suspended",True))
        samples=state.get("samples") or []; latest=samples[-1] if samples else {}
        edge=cls._session_num(latest.get("edge_c")); junction=cls._session_num(latest.get("junction_c")); delta=(junction-edge) if junction is not None and edge is not None else None
        telemetry_state=str(telemetry.get("telemetry_state") or telemetry.get("state") or "Game detected — waiting for telemetry")
        has_fps=cls._session_num(telemetry.get("fps")) is not None
        if state.get("suspended") and samples:mode="suspended"
        elif has_fps:mode="active"
        elif telemetry.get("file_exists"):mode="waiting"
        else:mode="detected"
        provider=str(context.get("provider") or "provider").title(); appid=str(context.get("steam_appid") or "").strip(); game_id=str(context.get("game_id") or "").strip()
        identity=f"{provider} • AppID {appid}" if appid else (f"{provider} • {game_id}" if game_id else provider)
        evidence=result.get("evidence") or "Insufficient live evidence."
        fps=cls._session_num(telemetry.get("fps")); p1=cls._session_num(telemetry.get("low"))
        metrics=[f"Recent FPS: {fps:.0f}" if fps is not None else "Recent FPS: unavailable",f"Rolling/available P1: {p1:.0f} FPS" if p1 is not None else "Rolling/available P1: unavailable",evidence]
        events=list(state.get("events") or [])[-MAX_LIVE_INTELLIGENCE_EVENTS:]
        transitions=sum(1 for event in events if event.get("gameplay_impact") is False or event.get("kind")=="Loading/transition"); gameplay=len(events)-transitions
        raw_phase=str(state.get("phase") or (latest.get("live_phase") if latest else "unknown") or "unknown")
        phase={"transition":"Loading/transition","loading/transition":"Loading/transition","menu":"Menu/background","menu/background":"Menu/background","settling":"Settling","gameplay":"Gameplay","pending":"Unknown / uncertain","unknown":"Unknown / uncertain"}.get(raw_phase,raw_phase)
        phase_start=cls._session_num(state.get("phase_started_t")); latest_t=cls._session_num(latest.get("t")); phase_duration=max(0.0,latest_t-phase_start) if latest_t is not None and phase_start is not None else 0.0
        phase_evidence=list(state.get("phase_evidence") or [])[-4:]
        if mode!="active":performance_status="Suspended until valid telemetry resumes"
        elif phase=="Loading/transition":performance_status="Active with transition context"
        elif phase in ("Menu/background","Settling") or phase.startswith("Unknown"):performance_status="Active with reduced confidence because phase is uncertain"
        else:performance_status="Active"
        return {"mode":mode,"game":str(context.get("game") or "Detected game"),"identity":identity,"profile":str(context.get("profile") or "—"),"scaling":str(context.get("scaling") or "—"),"telemetry":telemetry_state,"state":result.get("state") or "Insufficient evidence","confidence":result.get("confidence") or "Low","interpretation":result.get("evidence") or "Insufficient live evidence.","evidence":"   •   ".join(metrics),"recommendation":result.get("recommendation") or "No recommendation until sufficient evidence is available.","p1":p1,"events":events,"gameplay_event_count":gameplay,"transition_event_count":transitions,"phase":phase,"phase_confidence":str(state.get("phase_confidence") or "Low"),"phase_evidence":phase_evidence,"performance_status":performance_status,"phase_duration":phase_duration,"pending_event_count":len(state.get("pending_events") or []),"phase_reason":str(state.get("phase_reason") or "No phase evidence yet"),"sensors":{"edge":edge,"junction":junction,"delta":delta,"power":cls._session_num(latest.get("power_w")),"clock":cls._session_num(latest.get("gpu_clock_mhz"))}}

    @classmethod
    def _dashboard_live_summary_text(cls,view):
        if view.get("mode")=="idle":return "Live Analysis: No active game"
        if view.get("mode") in ("detected","waiting","suspended"):
            return f"Live Analysis: {view.get('telemetry') or 'Telemetry unavailable'}"
        p1=f"Recent P1 {view['p1']:.0f} FPS" if view.get("p1") is not None else "Recent P1 unavailable"
        phase=view.get("phase") or "Unknown / uncertain"; phase_context="possible loading" if phase=="Loading/transition" else ("uncertain" if phase in ("Menu/background","Settling") or str(phase).startswith("Unknown") else "gameplay")
        gameplay=int(view.get("gameplay_event_count") or 0); transitions=int(view.get("transition_event_count") or 0); return f"Live Analysis: {view.get('state')}  |  {view.get('confidence')} Confidence  |  Phase {phase_context}  |  {p1}  |  {gameplay} gameplay event{'s' if gameplay!=1 else ''} • {transitions} transition{'s' if transitions!=1 else ''}"

    def _refresh_live_intelligence_ui(self):
        view=self._live_analysis_view_data(getattr(self,"live_intelligence",None),getattr(self,"live_analysis_context",None),getattr(self,"telemetry_runtime_status",None))
        if hasattr(self,"dashboard_live_summary"):
            self.dashboard_live_summary.configure(text=self._dashboard_live_summary_text(view),fg=GREEN if view["mode"]=="active" else MUTED)
        if not hasattr(self,"live_analysis_state"):return
        colors={"GPU limited":YELLOW,"Loading / transition":BLUE2,"Frame-time instability":YELLOW,"Stable / balanced":GREEN,"Insufficient evidence":MUTED}
        self.live_analysis_game.configure(text=view["game"]); self.live_analysis_identity.configure(text=f"Provider identity: {view['identity']}")
        self.live_analysis_configuration.configure(text=f"GPU profile: {view['profile']}   •   Scaling: {view['scaling']}")
        self.live_analysis_telemetry.configure(text=f"Telemetry: {view['telemetry']}",fg=GREEN if view["mode"]=="active" else (YELLOW if view["mode"]!="idle" else MUTED))
        phase_evidence=" • ".join(view.get("phase_evidence") or [])
        self.live_analysis_phase.configure(text=f"Phase: {view['phase']} • {view['phase_confidence']} confidence • Performance analysis: {view['performance_status']} • {view['phase_duration']:.0f}s • {view['pending_event_count']} pending • {view['phase_reason']}{(' • '+phase_evidence) if phase_evidence else ''}")
        self.live_analysis_state.configure(text=view["state"],fg=colors.get(view["state"],FG)); self.live_analysis_confidence.configure(text=f"{view['confidence'].upper()} CONFIDENCE",fg=GREEN if view["confidence"]=="High" else (YELLOW if view["confidence"]=="Moderate" else MUTED))
        self.live_analysis_interpretation.configure(text=view["interpretation"]); self.live_analysis_evidence.configure(text=view["evidence"]); self.live_analysis_recommendation.configure(text=view["recommendation"])
        units={"edge":"°C","junction":"°C","delta":"°C","power":" W","clock":" MHz"}
        for key,label in self.live_analysis_sensor_values.items():
            value=view["sensors"].get(key); label.configure(text=f"{value:.0f}{units[key]}" if value is not None else "Unavailable")
        events=view["events"]; self.live_analysis_event_count.configure(text=f"{view['gameplay_event_count']} gameplay event{'s' if view['gameplay_event_count']!=1 else ''} • {view['transition_event_count']} transition{'s' if view['transition_event_count']!=1 else ''} • maximum {MAX_LIVE_INTELLIGENCE_EVENTS}")
        event_text="No recent performance events." if not events else "\n".join(f"{'TRANSITION' if event.get('gameplay_impact') is False or event.get('kind')=='Loading/transition' else 'GAMEPLAY':<10}  {event.get('clock','—')}  {event.get('kind','Uncertain event'):<27} {float(event.get('fps') or 0):.0f} FPS" for event in events)
        self.live_analysis_event_view.set_text(event_text)

    def _game_session_start(self, hit):
        if not hit:
            return
        idx,rule=hit
        preset_name=str(rule.get("graphics_preset","") or "").strip()
        preset=self.game_profile_data.get("graphics_presets",{}).get(preset_name,{})
        raw=preset.get("settings",{}) if isinstance(preset,dict) else {}
        settings=self._resolved_graphics_settings(raw) if raw else {}
        scaling="—"
        if settings:
            rw=settings.get("render_w"); rh=settings.get("render_h")
            ow=settings.get("output_w"); oh=settings.get("output_h")
            filt=str(settings.get("filter") or "None")
            scale=str(settings.get("render_scale") or "").strip()
            if rw and rh and ow and oh:
                scaling=f"{filt}{(' '+scale) if scale else ''} • {rw}×{rh}→{ow}×{oh}"
            elif filt and filt.lower()!="none":
                scaling=f"{filt}{(' '+scale) if scale else ''}"
        now=time.time(); power_limit=None; workload_profile=None
        gpu=self.__dict__.get("gpu")
        if gpu:
            try:
                limits=gpu.power_cap_limits(); power_limit=limits[0] if limits else None
            except Exception:pass
            try:workload_profile=next((name for _,name,active in gpu.performance_profiles() if active),None)
            except Exception:pass
        telemetry_identity=str(rule.get("alcc_game_id") or (f"steam:{rule.get('steam_appid')}" if rule.get("steam_appid") else ""))
        self.game_session_current=runtime_build_session_state(
            identity=self._game_session_rule_identity(hit),
            game=str(rule.get("steam_title") or rule.get("title") or rule.get("match") or "Game"),
            steam_appid=str(rule.get("steam_appid","")), started_at=now,
            gpu_profile=self._rule_gpu_profile_display(rule), graphics_preset=preset_name, scaling=scaling,
            render_resolution=f"{settings.get('render_w')}×{settings.get('render_h')}" if settings.get("render_w") and settings.get("render_h") else None,
            output_resolution=f"{settings.get('output_w')}×{settings.get('output_h')}" if settings.get("output_w") and settings.get("output_h") else None,
            power_limit_w=power_limit, workload_profile=workload_profile, telemetry_identity=telemetry_identity,
            telemetry_method=self.game_profile_data.get("telemetry_instrumentation",{}).get(telemetry_identity,{}).get("method") or "Not instrumented / provider unavailable",
            display_refresh_hz=self._cached_active_display_refresh_hz(),
        )
        self.game_session_missing_since=None
        self._reset_live_intelligence(self.game_session_current.get("telemetry_identity"))

    def _game_session_sample(self, hit, mh=None, gpu_metrics=None):
        identity=self._game_session_rule_identity(hit)
        if identity is None:
            if self.game_session_current is not None and self.game_session_missing_since is None:
                self.game_session_missing_since=time.monotonic()
            return
        if self.game_session_current is None or self.game_session_current.get("identity")!=identity:
            if self.game_session_current is not None:self._game_session_finish("game changed")
            self._game_session_start(hit)
        self.game_session_missing_since=None
        cur=self.game_session_current
        if not cur:return
        live_sample=runtime_ingest_session_sample(cur,mh,gpu_metrics)
        if live_sample is not None:
            self._live_intelligence_ingest(cur.get("telemetry_identity"),live_sample)

    def _game_session_maybe_finish(self):
        if runtime_should_finish_session(self.game_session_current,self.game_session_missing_since,self.game_session_exit_grace_seconds):
            self._game_session_finish("game exited")

