        check("GPU-headroom low",{"avg_gpu_load_pct":55,"frame_dip_rating":"Significant dips","gameplay_dip_events":1,"gpu_headroom_dip_events":1},lambda r:"CPU/game-engine" in r["primary_limiter"])
        check("Transition/loading only",{"avg_gpu_load_pct":98,"frame_dip_rating":"Good — transition/loading events only","transition_dip_events":1,"gameplay_dip_events":0},lambda r:"transition/loading" in r["primary_limiter"].lower() and r["top_recommendation"].startswith("Do not change graphics settings"))
