        check("Large junction-edge delta",{"avg_gpu_load_pct":90,"frame_dip_rating":"Smooth","max_junction_c":100,"avg_temp_delta_c":28,"max_temp_delta_c":34},lambda r:"Large hotspot delta" in r["thermals"] and any("cooling/contact" in x.lower() for x in r["recommendations"]))
        check("Rare dips long session",{"avg_gpu_load_pct":88,"frame_dip_rating":"Good — rare brief dips","gameplay_dip_events":3},lambda r:"rare brief dips" in " ".join(r["diagnoses"]).lower() and any("may not materially" in x for x in r["recommendations"]))
        check("Repeated GPU-saturated dips",{"avg_gpu_load_pct":98,"frame_dip_rating":"Significant dips","gameplay_dip_events":5,"gpu_bound_dip_events":5},lambda r:"Repeated sustained dips" in r["diagnoses"] and any("GPU-saturated" in x for x in r["recommendations"]) and any("render scale" in x.lower() for x in r["recommendations"]))
        check("Insufficient telemetry",{},lambda r:r["primary_limiter"].startswith("Unknown") and r["thermals"].startswith("Unknown") and "Insufficient telemetry" in r["overall"])
        return cases

